```tsx
import { useState, useEffect, useCallback } from 'react';
import { BookHeart, Database, LayoutGrid, List, Plus, X, Loader2, HelpCircle, Layers, CheckCircle, AlertTriangle } from 'lucide-react';
import { Group, Member, GroupDetails, ToastType } from './types';
import { PRESET_DB } from './constants';
import { fetchFromWikiAuto, fetchGroupLogo } from './services/wikiService';
import { GroupCard } from './components/GroupCard';
import { EditGroupModal } from './components/EditGroupModal';
import { GroupDetailsModal } from './components/GroupDetailsModal'; // Import
import { DataModal } from './components/DataModal';
import { Modal } from './components/ui/Modal';
import { normalizeString } from './utils';

// ... (AlertConfig interface)

export default function App() {
  // ... (State definitions)
  const [detailsModalGroup, setDetailsModalGroup] = useState<Group | null>(null); // New state

  // ... (Effects and Helper functions like showToast, handleForceAdd, handleSmartAdd)

  // ... (handleToggleExpand, handleMove, handleToggleRank, handleRemoveGroupClick)

  const handleEditClick = useCallback((group: Group) => {
    setEditingGroup(group);
  }, []);

  const handleDetailsClick = useCallback((group: Group) => {
    setDetailsModalGroup(group);
  }, []);

  // ... (performDeleteGroup)

  const handleSaveEdit = (groupId: string, stanDate: string, members: Member[], logoUrl: string) => {
    setMyGroups(prev => prev.map(g => g.id === groupId ? { ...g, stanDate, members, logoUrl } : g));
    showToast("團體已更新");
  };

  const handleSaveDetails = (groupId: string, details: GroupDetails) => {
    setMyGroups(prev => prev.map(g => g.id === groupId ? { ...g, details } : g));
    showToast("詳細筆記已儲存");
  };

  // ... (handleImport, handleReset, scrollToTop)

  return (
    <div className="max-w-md mx-auto bg-slate-50 min-h-screen shadow-2xl relative overflow-hidden flex flex-col">
      {/* ... (Header and Quick Add Bar) ... */}

      {/* Main Content */}
      <main className={`p-4 flex-1 overflow-y-auto ${viewMode === 'list' ? 'grid grid-cols-2 gap-3 items-stretch' : 'space-y-4'}`}>

        {/* ... (Empty State) ... */}

        {/* Group Cards */}
        {myGroups.map((group, index) => (
          <div key={group.id} className={viewMode === 'list' ? 'col-span-1 h-full' : ''}>
             <GroupCard 
               group={group}
               isFirst={index === 0}
               isLast={index === myGroups.length - 1}
               onMove={(dir) => handleMove(index, dir)}
