## components/GroupCard.tsx

Refactor layout to move move/expand actions to a dedicated vertical sidebar on the right.

```tsx
import React, { useState, useEffect } from 'react';
import { ArrowUp, ArrowDown, Pencil, ChevronUp, ChevronDown, CalendarHeart, Crown, Heart, Users, NotebookPen } from 'lucide-react';
import { Group, Member } from '../types';
import { MemberGrid } from './MemberGrid';

interface GroupCardProps {
  group: Group;
  isFirst: boolean;
  isLast: boolean;
  onMove: (dir: number) => void;
  onEdit: () => void;
  onDetails: () => void;
  onToggleExpand: () => void;
  onToggleRank: (member: Member) => void;
  onRemove: () => void;
}

export const GroupCard: React.FC<GroupCardProps> = React.memo(({ 
  group, isFirst, isLast, onMove, onEdit, onDetails, onToggleExpand, onToggleRank, onRemove 
}) => {
  const biasMembers = group.members.filter(m => m.rank === 1);
  const ultMembers = group.members.filter(m => m.rank === 2);
  const [imageError, setImageError] = useState(false);

  // Reset error state when url changes
  useEffect(() => {
    setImageError(false);
  }, [group.logoUrl]);

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden animate-pop-in h-full flex flex-col w-full hover:shadow-md transition-shadow duration-200">

      <div className="flex items-stretch min-h-[88px]">
          {/* Main Content Area (Click to expand) */}
          <div className="flex-1 p-3.5 flex items-start gap-3 cursor-pointer select-none" onClick={onToggleExpand}>

            {/* Logo */}
            <div className="flex-shrink-0 pt-0.5">
              {group.logoUrl && !imageError ? (
                <img 
                  src={group.logoUrl} 
                  alt={group.name} 
                  className="w-11 h-11 rounded-full object-cover border border-slate-100 shadow-sm"
                  onError={() => setImageError(true)}
                />
              ) : (
                <div className="w-11 h-11 rounded-full bg-slate-50 flex items-center justify-center text-slate-300 border border-slate-100">
                    <Users className="w-5 h-5" />
                </div>
              )}
            </div>

            {/* Text Content */}
            <div className="flex-1 min-w-0 flex flex-col gap-1.5">
                <div className="flex justify-between items-start gap-2">
                    <div className="min-w-0 flex-1">
                      <h2 className="text-lg font-bold text-slate-800 leading-snug break-words">
                        {group.name}
                      </h2>
                      {group.stanDate && (
                        <div className="text-[11px] text-violet-500 font-medium flex items-center gap-1 mt-0.5">
                          <CalendarHeart className="w-3 h-3 flex-shrink-0" /> <span className="truncate">Since {group.stanDate}</span>
                        </div>
                      )}
                    </div>

                    {/* Content Actions (Edit/Details) */}
                    <div className="flex items-center gap-0.5 -mt-1 -mr-1" onClick={(e) => e.stopPropagation()}>
                         <button 
                          onClick={onDetails} 
                          className="p-1.5 text-slate-300 hover:text-violet-600 hover:bg-violet-50 rounded-full transition"
                          title="詳情筆記"
                        >
                          <NotebookPen className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={onEdit} 
                          className="p-1.5 text-slate-300 hover:text-violet-600 hover:bg-violet-50 rounded-full transition"
                          title="編輯內容"
                        >
                          <Pencil className="w-4 h-4" />
                        </button>
                    </div>
                </div>

                {/* Tags */}
                <div className="flex flex-wrap gap-1 min-h-[18px]">
                  {ultMembers.map(m => (
                    <span key={m.name} className="inline-flex items-center gap-1 px-1.5 py-0.5 bg-amber-100 text-amber-700 text-[11px] font-bold rounded-full border border-amber-200 max-w-full">
                      <Crown className="w-3 h-3 fill-current flex-shrink-0" /> <span className="truncate">{m.name}</span>
                    </span>
                  ))}
                  {biasMembers.length > 0 && (
                    <span className="inline-flex items-center gap-1 px-1.5 py-0.5 bg-rose-100 text-rose-600 text-[11px] font-bold rounded-full border border-rose-200">
                      <Heart className="w-3 h-3 fill-current" /> {biasMembers.length}
                    </span>
                  )}
                  {ultMembers.length === 0 && biasMembers.length === 0 && (
                    <span className="text-[11px] text-slate-400 py-0.5">
                      {group.members.length} Members
                    </span>
                  )}
                </div>
            </div>
          </div>

          {/* Right Sidebar: Position Actions */}
          <div className="w-[34px] flex flex-col border-l border-slate-50 bg-slate-50/30">
              <button 
                  onClick={(e) => { e.stopPropagation(); onMove(-1); }}
                  disabled={isFirst}
                  className="flex-1 flex items-center justify-center text-slate-300 hover:text-violet-600 disabled:opacity-20 hover:bg-violet-50 transition active:scale-95"
                  title="Move Up"
              >
                  <ArrowUp className="w-4 h-4" />
              </button>
               <button 
                  onClick={(e) => { e.stopPropagation(); onMove(1); }}
                  disabled={isLast}
                  className="flex-1 flex items-center justify-center text-slate-300 hover:text-violet-600 disabled:opacity-20 hover:bg-violet-50 transition active:scale-95 border-t border-slate-100"
                  title="Move Down"
              >
                  <ArrowDown className="w-4 h-4" />
              </button>
               <button 
                  onClick={(e) => { e.stopPropagation(); onToggleExpand(); }}
                  className="flex-1 flex items-center justify-center text-slate-400 hover:text-violet-600 hover:bg-violet-50 transition active:scale-95 border-t border-slate-100"
                  title={group.isExpanded ? "收合" : "展開"}
              >
                  {group.isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
              </button>
          </div>
      </div>

      {/* Grid */}
      {group.isExpanded && (
        <MemberGrid 
          group={group} 
          onToggleRank={onToggleRank} 
          onRemoveGroup={onRemove}
        />
      )}
    </div>
  );
});

GroupCard.displayName = 'GroupCard';

To improve the visual balance and organization of the Group Card, I will refactor the layout to separate the different types of actions.

**Layout Changes:**
1.  **Sidebar (Right)**: Dedicated to **Structural/Sorting** actions (Move Up, Move Down, Expand/Collapse). This keeps them consistently available and prevents accidental clicks.
2.  **Content Area (Left)**:
    *   **Top**: Logo and Group Name (Clean, uncluttered).
    *   **Middle**: Stan Date.
    *   **Bottom Row**:
        *   **Left**: Member Rank Tags.
        *   **Right**: **Content Actions** (Details Note, Edit).

This ensures that the **Logo**, **Sorting Buttons**, and **Edit Icons** are all on different visual lines or sections, creating a much more balanced and readable card.

