import React, { useMemo } from 'react';
import { CalendarClock, Users, ArrowUp } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group } from '../types';

interface TimelineModalProps {
  isOpen: boolean;
  onClose: () => void;
  groups: Group[];
}

export const TimelineModal: React.FC<TimelineModalProps> = ({ isOpen, onClose, groups }) => {

  const sortedGroups = useMemo(() => {
    return groups
      .filter(g => g.stanDate) // Only groups with a stan date
      .sort((a, b) => b.stanDate.localeCompare(a.stanDate)); // Sort Newest to Oldest
  }, [groups]);

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="追星時間軸">
      <div className="p-5 overflow-y-auto flex-1 bg-slate-50 no-scrollbar">

