import React, { useMemo } from 'react';
import { CalendarClock, Users, LogIn, LogOut, RefreshCcw, CloudFog, ArrowRight } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group, TimelineEvent } from '../types';

interface TimelineModalProps {
  isOpen: boolean;
  onClose: () => void;
  groups: Group[];
}

interface FlattenedEvent extends TimelineEvent {
  groupId: string;
  groupName: string;
  groupLogo?: string;
}

export const TimelineModal: React.FC<TimelineModalProps> = ({ isOpen, onClose, groups }) => {

  const sortedEvents = useMemo(() => {
    // 1. Flatten all events
    let allEvents: FlattenedEvent[] = [];

    groups.forEach(group => {
      // If group has new timeline structure
      if (group.timeline && group.timeline.length > 0) {
        group.timeline.forEach(evt => {
          allEvents.push({
            ...evt,
            groupId: group.id,
            groupName: group.name,
            groupLogo: group.logoUrl
          });
        });
      } 
      // Fallback for groups without timeline structure (backward compatibility)
      else if (group.stanDate) {
        allEvents.push({
          date: group.stanDate,
          type: 'stan',
          groupId: group.id,
          groupName: group.name,
          groupLogo: group.logoUrl
        });
        if (group.unstanDate) {
           allEvents.push({
            date: group.unstanDate,
            type: 'unstan',
            groupId: group.id,
            groupName: group.name,
            groupLogo: group.logoUrl
          });
        }
      }
    });

    // 2. Sort by Date Descending
    return allEvents.sort((a, b) => b.date.localeCompare(a.date));
  }, [groups]);

  const getEventIcon = (type: string) => {
      switch (type) {
          case 'stan': return <LogIn className="w-3 h-3" />;
          case 'restan': return <RefreshCcw className="w-3 h-3" />;
          case 'fade': return <CloudFog className="w-3 h-3" />;
          case 'unstan': return <LogOut className="w-3 h-3" />;
          default: return <Users className="w-3 h-3" />;
      }
  };

  const getEventColor = (type: string) => {
    switch (type) {
        case 'stan': return 'bg-violet-100 text-violet-600 border-violet-200';
        case 'restan': return 'bg-emerald-100 text-emerald-600 border-emerald-200';
        case 'fade': return 'bg-amber-100 text-amber-600 border-amber-200';
        case 'unstan': return 'bg-slate-100 text-slate-500 border-slate-200';
        default: return 'bg-slate-100 text-slate-600';
    }
  };

  const getEventLabel = (type: string) => {
    switch (type) {
        case 'stan': return '入坑';
        case 'restan': return '回坑';
        case 'fade': return '淡坑';
        case 'unstan': return '退坑';
        default: return '紀錄';
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="追星歷史軌跡">
      <div className="p-5 overflow-y-auto flex-1 bg-slate-50 no-scrollbar">

        {sortedEvents.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center opacity-60 py-10">
            <CalendarClock className="w-12 h-12 text-slate-300 mb-3" />
            <p className="text-slate-500 font-medium">還沒有時間軸資料</p>
            <p className="text-xs text-slate-400 mt-1">請在編輯團體時新增「時間軸節點」</p>
          </div>
        ) : (
          <div className="relative pl-4 space-y-6 my-4">
            {/* Vertical Line */}
            <div className="absolute left-[27px] top-2 bottom-2 w-0.5 bg-gradient-to-b from-violet-400 via-fuchsia-300 to-slate-200"></div>

            {/* Now Indicator */}
             <div className="relative flex items-center gap-4 pb-2">
                 <div className="absolute left-[23px] w-2.5 h-2.5 bg-violet-200 rounded-full z-10 animate-pulse"></div>
                 <div className="ml-10 text-xs text-violet-400 font-bold">
                    現在 (Now)
                 </div>
            </div>

            {sortedEvents.map((evt, index) => (
              <div key={`${evt.groupId}-${evt.date}-${evt.type}`} className="relative flex items-center gap-4 animate-pop-in" style={{ animationDelay: `${Math.min(index * 50, 500)}ms` }}>

                {/* Node Dot */}
                <div className={`absolute left-[23px] w-2.5 h-2.5 rounded-full ring-4 ring-white shadow-sm z-10
                    ${evt.type === 'unstan' ? 'bg-slate-300' : 
                      evt.type === 'fade' ? 'bg-amber-400' :
                      evt.type === 'restan' ? 'bg-emerald-400' : 'bg-violet-500'}
                `}></div>

                {/* Content Card */}
                <div className={`ml-10 flex-1 bg-white p-3 rounded-xl border shadow-sm flex items-center gap-3 active:scale-95 transition-transform
                    ${evt.type === 'unstan' ? 'border-slate-100 opacity-90' : 'border-slate-100'}
                `}>
                   {/* Logo */}
                   <div className="flex-shrink-0 relative">
                      {evt.groupLogo ? (
                        <img 
                          src={evt.groupLogo} 
                          alt={evt.groupName} 
                          className={`w-10 h-10 rounded-full object-cover border ${evt.type === 'unstan' ? 'grayscale border-slate-200' : 'border-slate-100'}`}
                        />
                      ) : (
                        <div className="w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center text-slate-300 border border-slate-100">
                           <Users className="w-5 h-5" />
                        </div>
                      )}
                   </div>

                   {/* Info */}
                   <div className="flex-1 min-w-0">
                      <div className="flex justify-between items-start">
                        <div className="text-xs font-bold text-slate-400 font-mono mb-0.5">
                            {evt.date}
                        </div>
                        <span className={`text-[10px] px-1.5 py-0.5 rounded-md font-bold flex items-center gap-1 ${getEventColor(evt.type)}`}>
                            {getEventIcon(evt.type)} {getEventLabel(evt.type)}
