                        {evt.groupName}
                      </div>
                   </div>
                </div>
              </div>
            ))}

            {/* Start Node */}
            <div className="relative flex items-center gap-4 pt-2">
                 <div className="absolute left-[24px] w-2 h-2 bg-slate-300 rounded-full z-10"></div>
                 <div className="ml-10 text-xs text-slate-400 font-medium">
