  );
});

GroupCard.displayName = 'GroupCard';

import React, { useState, useEffect } from 'react';
import { Image as ImageIcon, Upload, Plus, Trash2, ArrowRight, AlertCircle, Info } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group, Member, TimelineEvent, EventType } from '../types';
import { compressImage } from '../utils';

interface EditGroupModalProps {
  isOpen: boolean;
  onClose: () => void;
  group: Group | null;
  onSave: (groupId: string, members: Member[], logoUrl: string, timeline: TimelineEvent[]) => void;
}

export const EditGroupModal: React.FC<EditGroupModalProps> = ({ isOpen, onClose, group, onSave }) => {
  const [memberString, setMemberString] = useState('');
  const [logoUrl, setLogoUrl] = useState('');

  // Timeline State
  const [timeline, setTimeline] = useState<TimelineEvent[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (group && isOpen) {
      const str = group.members.map(m => m.cn ? `${m.name}(${m.cn})` : m.name).join(', ');
      setMemberString(str);
      setLogoUrl(group.logoUrl || '');
      setError(null);

      // Initialize timeline
      if (group.timeline && group.timeline.length > 0) {
        setTimeline([...group.timeline]);
      } else {
        const initialEvents: TimelineEvent[] = [];
        if (group.stanDate) {
          initialEvents.push({ date: group.stanDate, type: 'stan' });
        }
        if (group.unstanDate) {
          initialEvents.push({ date: group.unstanDate, type: 'unstan' });
        }
        setTimeline(initialEvents);
      }
    }
  }, [group, isOpen]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const dataUrl = await compressImage(file);
      setLogoUrl(dataUrl);
    } catch (error) {
      console.error("Image compression failed", error);
      alert("圖片處理失敗，請重試");
    }
  };

  // --- Timeline Logic Helpers ---

  // Sort events by date for logic checking
  const getSortedTimeline = (currentTimeline: TimelineEvent[]) => {
    return [...currentTimeline].sort((a, b) => a.date.localeCompare(b.date));
  };

  const addEvent = () => {
    setError(null);
    const sorted = getSortedTimeline(timeline);
    const lastEvent = sorted[sorted.length - 1];

    // Smart Suggestion Logic
    let nextType: EventType = 'stan';
    let nextDate = '';

    if (lastEvent) {
       // Default date to current month
       const now = new Date();
       const year = now.getFullYear();
       const month = String(now.getMonth() + 1).padStart(2, '0');
       nextDate = `${year}-${month}`;

       // Suggest type based on last state
       if (lastEvent.type === 'stan' || lastEvent.type === 'restan') {
           nextType = 'fade'; // Active -> Fade
       } else if (lastEvent.type === 'fade') {
           nextType = 'unstan'; // Fade -> Unstan
       } else if (lastEvent.type === 'unstan') {
           nextType = 'restan'; // Unstan -> Restan
       }
    }

    setTimeline(prev => [...prev, { date: nextDate, type: nextType }]);
  };

  const removeEvent = (index: number) => {
    setTimeline(prev => prev.filter((_, i) => i !== index));
    setError(null);
  };

  const updateEvent = (index: number, field: keyof TimelineEvent, value: string) => {
    setTimeline(prev => prev.map((ev, i) => i === index ? { ...ev, [field]: value } : ev));
    setError(null);
  };

  const validateTimeline = (events: TimelineEvent[]): string | null => {
    if (events.length === 0) return null;

    // 1. Check for empty dates
    if (events.some(e => !e.date)) return "所有節點都必須設定日期";

    const sorted = getSortedTimeline(events);

    // 2. First event must be 'stan'
    if (sorted[0].type !== 'stan') {
        return `時間軸起始錯誤：${sorted[0].date} 的事件必須是「入坑」`;
    }

    // 3. Logic flow check
    // States: 0=Inactive, 1=Active(Stan/Restan), 2=Faded
    let currentState = 1; // Started with stan

    for (let i = 1; i < sorted.length; i++) {
        const evt = sorted[i];
        const prev = sorted[i-1];

        // Prevent duplicate dates causing confusion (optional, but good for logic)
        if (evt.date === prev.date) return `${evt.date} 有重複的時間點，請合併或修正日期`;

        if (currentState === 1) { // Currently Active
            if (evt.type === 'stan') return `${evt.date} 錯誤：已經在坑底了，不需再次「入坑」`;
            if (evt.type === 'restan') return `${evt.date} 錯誤：目前是活躍狀態，不需「回坑」`;

            if (evt.type === 'fade') currentState = 2;
            else if (evt.type === 'unstan') currentState = 0;
        } 
        else if (currentState === 2) { // Currently Faded
            if (evt.type === 'stan') return `${evt.date} 錯誤：若要恢復熱度，請選擇「回坑」`;
            if (evt.type === 'fade') return `${evt.date} 錯誤：已經是淡坑狀態`;

            if (evt.type === 'restan') currentState = 1;
            else if (evt.type === 'unstan') currentState = 0;
        }
        else if (currentState === 0) { // Currently Unstanned
            if (evt.type === 'fade') return `${evt.date} 錯誤：已經退坑了，無法「淡坑」`;
            if (evt.type === 'unstan') return `${evt.date} 錯誤：已經退坑了，無法再次「退坑」`;

            if (evt.type === 'stan' || evt.type === 'restan') currentState = 1;
        }
    }

    return null;
  };

  const handleSave = () => {
    if (!group) return;

    const validationError = validateTimeline(timeline);
    if (validationError) {
        setError(validationError);
        return;
    }

    // Parse member string
    const list = memberString.split(/,|，|\n/).map(s => s.trim()).filter(s => s);
    const newMembers: Member[] = list.map(item => {
      const match = item.match(/^(.*?)\s*[\(（](.*?)[\)）]/);
      let name = item;
      let cn = '';
      if (match) {
        name = match[1];
        cn = match[2];
      }

      const oldMember = group.members.find(m => m.name === name);
      return { name, cn, rank: oldMember ? oldMember.rank : 0 };
    });

    const cleanTimeline = getSortedTimeline(timeline);
    onSave(group.id, newMembers, logoUrl, cleanTimeline);
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="編輯團體詳細資訊">
      <div className="p-4 overflow-y-auto flex-1 bg-slate-50 space-y-4">

        {/* Logo Section */}
        <div className="bg-white p-3 rounded-xl border border-slate-200 space-y-3">
          <label className="text-xs font-bold text-slate-500 flex items-center gap-1">
            <ImageIcon className="w-3 h-3" /> 團體徽標 (Logo)
          </label>
          <div className="flex items-center gap-4">
             {logoUrl ? (
               <img src={logoUrl} alt="Preview" className="w-16 h-16 rounded-full object-cover border border-slate-200 shadow-sm" />
             ) : (
               <div className="w-16 h-16 rounded-full bg-slate-100 flex items-center justify-center text-slate-400">
                 <ImageIcon className="w-8 h-8" />
               </div>
             )}
             <div className="flex-1 space-y-2">
                <label className="flex items-center gap-2 px-3 py-2 bg-violet-50 text-violet-600 rounded-lg text-xs font-bold cursor-pointer hover:bg-violet-100 transition w-fit border border-violet-100">
                   <Upload className="w-3 h-3" /> 上傳圖片
                   <input type="file" accept="image/*" className="hidden" onChange={handleFileChange} />
                </label>
                <input 
                  type="text" 
                  value={logoUrl}
                  onChange={(e) => setLogoUrl(e.target.value)}
                  placeholder="或貼上圖片網址..."
                  className="w-full p-2 bg-slate-50 rounded-lg border border-slate-200 text-xs focus:ring-2 focus:ring-violet-500 outline-none"
                />
             </div>
          </div>
        </div>

        {/* Timeline Editor Section */}
        <div className={`bg-white p-3 rounded-xl border transition-colors ${error ? 'border-rose-300 ring-4 ring-rose-50' : 'border-slate-200'}`}>
            <div className="flex justify-between items-center mb-2">
                <label className="text-xs font-bold text-slate-500 flex items-center gap-1">
                    追星歷程
                    <Info className="w-3 h-3 text-slate-300" />
                </label>
                <button onClick={addEvent} className="text-xs bg-violet-50 text-violet-600 px-2 py-1 rounded-md font-bold flex items-center gap-1 hover:bg-violet-100 transition">
                    <Plus className="w-3 h-3" /> 新增節點
                </button>
            </div>

            {error && (
                <div className="mb-3 p-2 bg-rose-50 text-rose-600 text-xs rounded-lg flex items-start gap-2 animate-shake">
                    <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
                    <span>{error}</span>
                </div>
            )}

            <div className="space-y-2 relative">
                 {/* Logic connection line visual (simplified) */}
                 {timeline.length > 1 && (
                     <div className="absolute left-[52px] top-4 bottom-4 w-0.5 bg-slate-100 -z-0" />
                 )}

                {timeline.length === 0 && (
                    <div className="text-center py-6 text-slate-400 text-xs bg-slate-50 rounded-lg border border-dashed border-slate-200">
                        點擊「新增節點」設定入坑時間
                    </div>
                )}

                {timeline.map((event, index) => (
                    <div key={index} className="flex gap-2 items-center animate-pop-in relative z-10">
                        <input 
                            type="month" 
                            value={event.date}
                            onChange={(e) => updateEvent(index, 'date', e.target.value)}
                            className="w-[105px] p-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-mono focus:border-violet-400 focus:ring-2 focus:ring-violet-100 outline-none"
                        />
                        <select
                            value={event.type}
                            onChange={(e) => updateEvent(index, 'type', e.target.value as EventType)}
                            className={`flex-1 p-2 border border-slate-200 rounded-lg text-xs font-bold outline-none cursor-pointer
                                ${event.type === 'stan' ? 'text-violet-600 bg-violet-50 border-violet-100' : ''}
                                ${event.type === 'restan' ? 'text-emerald-600 bg-emerald-50 border-emerald-100' : ''}
                                ${event.type === 'fade' ? 'text-amber-600 bg-amber-50 border-amber-100' : ''}
                                ${event.type === 'unstan' ? 'text-slate-500 bg-slate-100 border-slate-200' : ''}
                            `}
                        >
                            <option value="stan">入坑 (開始)</option>
                            <option value="fade">淡坑 (少追)</option>
                            <option value="restan">回坑 (重追)</option>
                            <option value="unstan">退坑 (結束)</option>
                        </select>
                        <button 
                            onClick={() => removeEvent(index)}
                            className="p-2 text-slate-300 hover:text-red-400 hover:bg-red-50 rounded-lg transition"
                            title="移除節點"
                        >
                            <Trash2 className="w-4 h-4" />
                        </button>
                    </div>
                ))}
            </div>
             {timeline.length > 0 && (
                <div className="mt-2 text-[10px] text-slate-400 flex items-center gap-1 justify-end px-1">
                    <ArrowRight className="w-3 h-3" /> 系統會自動驗證邏輯並排序
                </div>
            )}
        </div>

        {/* Members */}
        <div>
          <label className="text-xs font-bold text-slate-500 mb-1 block">成員名單 (英文, 中文)</label>
          <textarea 
            value={memberString}
            onChange={(e) => setMemberString(e.target.value)}
            className="w-full h-40 p-3 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-violet-500 outline-none resize-none font-mono transition-shadow" 
            placeholder="成員A(中文名), 成員B, 成員C..."
          />
        </div>
      </div>
      <div className="p-3 border-t border-slate-100 bg-white rounded-b-2xl">
        <button 
          onClick={handleSave} 
          className="w-full bg-violet-600 text-white py-3 rounded-xl font-bold active:scale-95 transition shadow-lg shadow-violet-200 hover:bg-violet-700 disabled:opacity-50 disabled:cursor-not-allowed"
          disabled={!!error}
        >
          儲存變更
        </button>
      </div>
    </Modal>
  );
};

import React, { useMemo } from 'react';
import { CalendarClock, Users, LogIn, LogOut, RefreshCcw, CloudFog } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group, TimelineEvent } from '../types';

interface TimelineModalProps {
  isOpen: boolean;
  onClose: () => void;
  groups: Group[];
}

interface FlattenedEvent extends TimelineEvent {
  groupId: string;
  groupName: string;
  groupLogo?: string;
}

export const TimelineModal: React.FC<TimelineModalProps> = ({ isOpen, onClose, groups }) => {

  const sortedEvents = useMemo(() => {
    // 1. Flatten all events
    let allEvents: FlattenedEvent[] = [];

    groups.forEach(group => {
      if (group.timeline && group.timeline.length > 0) {
        group.timeline.forEach(evt => {
          allEvents.push({
            ...evt,
            groupId: group.id,
            groupName: group.name,
            groupLogo: group.logoUrl
          });
        });
      } 
      else if (group.stanDate) {
        allEvents.push({
          date: group.stanDate,
          type: 'stan',
          groupId: group.id,
          groupName: group.name,
          groupLogo: group.logoUrl
        });
        if (group.unstanDate) {
           allEvents.push({
            date: group.unstanDate,
            type: 'unstan',
            groupId: group.id,
            groupName: group.name,
            groupLogo: group.logoUrl
          });
        }
      }
    });

    // 2. Sort by Date Descending
    return allEvents.sort((a, b) => b.date.localeCompare(a.date));
  }, [groups]);

  const getEventIcon = (type: string) => {
      switch (type) {
          case 'stan': return <LogIn className="w-3 h-3" />;
          case 'restan': return <RefreshCcw className="w-3 h-3" />;
          case 'fade': return <CloudFog className="w-3 h-3" />;
          case 'unstan': return <LogOut className="w-3 h-3" />;
          default: return <Users className="w-3 h-3" />;
      }
  };

  const getEventStyle = (type: string) => {
    switch (type) {
        case 'stan': 
            return {
                bg: 'bg-violet-50',
                border: 'border-violet-100',
                text: 'text-violet-600',
                badge: 'bg-violet-100 text-violet-700',
                dot: 'bg-violet-500'
            };
        case 'restan': 
            return {
                bg: 'bg-emerald-50',
                border: 'border-emerald-100',
                text: 'text-emerald-600',
                badge: 'bg-emerald-100 text-emerald-700',
                dot: 'bg-emerald-500'
            };
        case 'fade': 
            return {
                bg: 'bg-amber-50',
                border: 'border-amber-100',
                text: 'text-amber-700',
                badge: 'bg-amber-100 text-amber-800',
                dot: 'bg-amber-400'
            };
        case 'unstan': 
            return {
                bg: 'bg-slate-50',
                border: 'border-slate-100',
                text: 'text-slate-500',
                badge: 'bg-slate-200 text-slate-600',
                dot: 'bg-slate-300'
            };
        default: 
            return {
                bg: 'bg-white',
                border: 'border-slate-100',
                text: 'text-slate-600',
                badge: 'bg-slate-100',
                dot: 'bg-slate-300'
            };
    }
  };

  const getEventLabel = (type: string) => {
    switch (type) {
        case 'stan': return '入坑';
        case 'restan': return '回坑';
        case 'fade': return '淡坑';
        case 'unstan': return '退坑';
        default: return '紀錄';
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="追星歷史軌跡">
      <div className="p-5 overflow-y-auto flex-1 bg-slate-50 no-scrollbar">

        {sortedEvents.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center opacity-60 py-10">
            <CalendarClock className="w-12 h-12 text-slate-300 mb-3" />
            <p className="text-slate-500 font-medium">還沒有時間軸資料</p>
            <p className="text-xs text-slate-400 mt-1">請在編輯團體時新增「時間軸節點」</p>
          </div>
        ) : (
          <div className="relative pl-4 space-y-6 my-4">
            {/* Vertical Line */}
            <div className="absolute left-[27px] top-2 bottom-2 w-0.5 bg-gradient-to-b from-violet-400 via-fuchsia-300 to-slate-200"></div>

            {/* Now Indicator */}
             <div className="relative flex items-center gap-4 pb-2">
                 <div className="absolute left-[23px] w-2.5 h-2.5 bg-violet-200 rounded-full z-10 animate-pulse"></div>
                 <div className="ml-10 text-xs text-violet-400 font-bold">
                    現在 (Now)
                 </div>
            </div>

            {sortedEvents.map((evt, index) => {
                const style = getEventStyle(evt.type);
                return (
                  <div key={`${evt.groupId}-${evt.date}-${evt.type}`} className="relative flex items-center gap-4 animate-pop-in" style={{ animationDelay: `${Math.min(index * 50, 500)}ms` }}>

                    {/* Node Dot */}
                    <div className={`absolute left-[23px] w-2.5 h-2.5 rounded-full ring-4 ring-white shadow-sm z-10 ${style.dot}`}></div>

                    {/* Content Card */}
                    <div className={`ml-10 flex-1 p-3 rounded-xl border shadow-sm flex items-center gap-3 active:scale-95 transition-transform ${style.bg} ${style.border} ${evt.type === 'unstan' ? 'opacity-80' : ''}`}>

                       {/* Logo */}
                       <div className="flex-shrink-0 relative">
                          {evt.groupLogo ? (
                            <img 
                              src={evt.groupLogo} 
                              alt={evt.groupName} 
                              className={`w-10 h-10 rounded-full object-cover border bg-white ${style.border} ${evt.type === 'unstan' ? 'grayscale opacity-80' : ''}`}
                            />
                          ) : (
                            <div className={`w-10 h-10 rounded-full bg-white flex items-center justify-center border ${style.border}`}>
                               <Users className={`w-5 h-5 ${style.text}`} />
                            </div>
                          )}
                       </div>

                       {/* Info */}
                       <div className="flex-1 min-w-0">
                          <div className="flex justify-between items-start mb-0.5">
                            <div className="text-xs font-bold text-slate-400 font-mono">
                                {evt.date}
                            </div>
                            <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold flex items-center gap-1 shadow-sm ${style.badge}`}>
                                {getEventIcon(evt.type)} {getEventLabel(evt.type)}
                            </span>
                          </div>

                          <div className={`text-sm font-bold leading-tight truncate ${evt.type === 'unstan' ? 'text-slate-500' : 'text-slate-800'}`}>
                            {evt.groupName}
                          </div>
                       </div>
                    </div>
                  </div>
                );
            })}

            {/* Start Node */}
            <div className="relative flex items-center gap-4 pt-2">
                 <div className="absolute left-[24px] w-2 h-2 bg-slate-300 rounded-full z-10"></div>
                 <div className="ml-10 text-xs text-slate-400 font-medium">
                    旅程起點
                 </div>
            </div>
          </div>
        )}

      </div>
      <div className="p-3 border-t border-slate-100 bg-white rounded-b-2xl">
        <button onClick={onClose} className="w-full py-2 text-slate-400 text-sm hover:text-slate-600">關閉</button>
      </div>
    </Modal>
  );
};

