            // Updated to Gray (Slate), slightly darker than unstan to indicate "still here but faded"
            return {
                bg: 'bg-slate-50',
                border: 'border-slate-200',
                text: 'text-slate-600',
                badge: 'bg-slate-200 text-slate-700',
                dot: 'bg-slate-400'
            };
        case 'unstan': 
            return {
                bg: 'bg-slate-100',
                border: 'border-slate-200',
                text: 'text-slate-400',
                badge: 'bg-slate-200 text-slate-500',
                dot: 'bg-slate-300'
            };
        default: 
            return {
                bg: 'bg-white',
                border: 'border-slate-100',
                text: 'text-slate-600',
                badge: 'bg-slate-100',
                dot: 'bg-slate-300'
            };
    }
  };

  const getEventLabel = (type: string) => {
    switch (type) {
        case 'stan': return '入坑';
        case 'restan': return '回坑';
        case 'fade': return '淡坑';
        case 'unstan': return '退坑';
        default: return '紀錄';
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="追星歷史軌跡">
      <div className="p-5 overflow-y-auto flex-1 bg-slate-50 no-scrollbar">

        {sortedEvents.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center opacity-60 py-10">
            <CalendarClock className="w-12 h-12 text-slate-300 mb-3" />
            <p className="text-slate-500 font-medium">還沒有時間軸資料</p>
            <p className="text-xs text-slate-400 mt-1">請在編輯團體時新增「時間軸節點」</p>
          </div>
        ) : (
          <div className="relative pl-4 space-y-6 my-4">
            {/* Vertical Line */}
            <div className="absolute left-[27px] top-2 bottom-2 w-0.5 bg-gradient-to-b from-violet-400 via-fuchsia-300 to-slate-200"></div>

            {/* Now Indicator */}
             <div className="relative flex items-center gap-4 pb-2">
                 <div className="absolute left-[23px] w-2.5 h-2.5 bg-violet-200 rounded-full z-10 animate-pulse"></div>
                 <div className="ml-10 text-xs text-violet-400 font-bold">
                    現在 (Now)
                 </div>
            </div>

            {sortedEvents.map((evt, index) => {
                const style = getEventStyle(evt.type);
                return (
                  <div key={`${evt.groupId}-${evt.date}-${evt.type}`} className="relative flex items-center gap-4 animate-pop-in" style={{ animationDelay: `${Math.min(index * 50, 500)}ms` }}>

                    {/* Node Dot */}
                    <div className={`absolute left-[23px] w-2.5 h-2.5 rounded-full ring-4 ring-white shadow-sm z-10 ${style.dot}`}></div>

                    {/* Content Card */}
                    <div className={`ml-10 flex-1 p-3 rounded-xl border shadow-sm flex items-center gap-3 active:scale-95 transition-transform ${style.bg} ${style.border} ${evt.type === 'unstan' ? 'opacity-80' : ''}`}>

                       {/* Logo */}
                       <div className="flex-shrink-0 relative">
                          {evt.groupLogo ? (
                            <img 
                              src={evt.groupLogo} 
                              alt={evt.groupName} 
                              className={`w-10 h-10 rounded-full object-cover border bg-white ${style.border} ${evt.type === 'unstan' ? 'grayscale opacity-80' : ''}`}
                            />
                          ) : (
                            <div className={`w-10 h-10 rounded-full bg-white flex items-center justify-center border ${style.border}`}>
                               <Users className={`w-5 h-5 ${style.text}`} />
                            </div>
                          )}
                       </div>

                       {/* Info */}
                       <div className="flex-1 min-w-0">
                          <div className="flex justify-between items-start mb-0.5">
                            <div className="text-xs font-bold text-slate-400 font-mono">
                                {evt.date}
                            </div>
                            <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold flex items-center gap-1 shadow-sm ${style.badge}`}>
                                {getEventIcon(evt.type)} {getEventLabel(evt.type)}
                            </span>
                          </div>

                          <div className={`text-sm font-bold leading-tight truncate ${evt.type === 'unstan' ? 'text-slate-500' : 'text-slate-800'}`}>
                            {evt.groupName}
                          </div>
                       </div>
                    </div>
                  </div>
                );
            })}

            {/* Start Node */}
            <div className="relative flex items-center gap-4 pt-2">
                 <div className="absolute left-[24px] w-2 h-2 bg-slate-300 rounded-full z-10"></div>
                 <div className="ml-10 text-xs text-slate-400 font-medium">
                    旅程起點
                 </div>
            </div>
          </div>
        )}

      </div>
      <div className="p-3 border-t border-slate-100 bg-white rounded-b-2xl">
        <button onClick={onClose} className="w-full py-2 text-slate-400 text-sm hover:text-slate-600">關閉</button>
      </div>
    </Modal>
  );
};

import React, { useState, useEffect } from 'react';
import { Image as ImageIcon, Upload, Plus, Trash2, ArrowRight, AlertCircle, Info } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group, Member, TimelineEvent, EventType } from '../types';
import { compressImage } from '../utils';

interface EditGroupModalProps {
  isOpen: boolean;
  onClose: () => void;
  group: Group | null;
  onSave: (groupId: string, members: Member[], logoUrl: string, timeline: TimelineEvent[]) => void;
}

export const EditGroupModal: React.FC<EditGroupModalProps> = ({ isOpen, onClose, group, onSave }) => {
  const [memberString, setMemberString] = useState('');
  const [logoUrl, setLogoUrl] = useState('');

  // Timeline State
  const [timeline, setTimeline] = useState<TimelineEvent[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (group && isOpen) {
      const str = group.members.map(m => m.cn ? `${m.name}(${m.cn})` : m.name).join(', ');
      setMemberString(str);
      setLogoUrl(group.logoUrl || '');
      setError(null);

      // Initialize timeline
      if (group.timeline && group.timeline.length > 0) {
        setTimeline([...group.timeline]);
      } else {
        const initialEvents: TimelineEvent[] = [];
        if (group.stanDate) {
          initialEvents.push({ date: group.stanDate, type: 'stan' });
        }
        if (group.unstanDate) {
          initialEvents.push({ date: group.unstanDate, type: 'unstan' });
        }
        setTimeline(initialEvents);
      }
    }
  }, [group, isOpen]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const dataUrl = await compressImage(file);
      setLogoUrl(dataUrl);
    } catch (error) {
      console.error("Image compression failed", error);
      alert("圖片處理失敗，請重試");
    }
  };

  // --- Timeline Logic Helpers ---

  // Sort events by date for logic checking
  const getSortedTimeline = (currentTimeline: TimelineEvent[]) => {
    return [...currentTimeline].sort((a, b) => a.date.localeCompare(b.date));
  };

  const addEvent = () => {
    setError(null);
    const sorted = getSortedTimeline(timeline);
    const lastEvent = sorted[sorted.length - 1];

    // Smart Suggestion Logic
    let nextType: EventType = 'stan';
    let nextDate = '';

    if (lastEvent) {
       // Default date to current month
       const now = new Date();
       const year = now.getFullYear();
       const month = String(now.getMonth() + 1).padStart(2, '0');
       nextDate = `${year}-${month}`;

       // Suggest type based on last state
       if (lastEvent.type === 'stan' || lastEvent.type === 'restan') {
           nextType = 'fade'; // Active -> Fade
       } else if (lastEvent.type === 'fade') {
           nextType = 'unstan'; // Fade -> Unstan
       } else if (lastEvent.type === 'unstan') {
           nextType = 'restan'; // Unstan -> Restan
       }
    }

    setTimeline(prev => [...prev, { date: nextDate, type: nextType }]);
  };

  const removeEvent = (index: number) => {
    setTimeline(prev => prev.filter((_, i) => i !== index));
    setError(null);
  };

  const updateEvent = (index: number, field: keyof TimelineEvent, value: string) => {
    setTimeline(prev => prev.map((ev, i) => i === index ? { ...ev, [field]: value } : ev));
    setError(null);
  };

  const validateTimeline = (events: TimelineEvent[]): string | null => {
    if (events.length === 0) return null;

    // 1. Check for empty dates
    if (events.some(e => !e.date)) return "所有節點都必須設定日期";

    const sorted = getSortedTimeline(events);

    // 2. First event must be 'stan'
    if (sorted[0].type !== 'stan') {
        return `時間軸起始錯誤：${sorted[0].date} 的事件必須是「入坑」`;
    }

    // 3. Logic flow check
    // States: 0=Inactive, 1=Active(Stan/Restan), 2=Faded
    let currentState = 1; // Started with stan

    for (let i = 1; i < sorted.length; i++) {
        const evt = sorted[i];
        const prev = sorted[i-1];

        // Prevent duplicate dates causing confusion (optional, but good for logic)
        if (evt.date === prev.date) return `${evt.date} 有重複的時間點，請合併或修正日期`;

        if (currentState === 1) { // Currently Active
            if (evt.type === 'stan') return `${evt.date} 錯誤：已經在坑底了，不需再次「入坑」`;
            if (evt.type === 'restan') return `${evt.date} 錯誤：目前是活躍狀態，不需「回坑」`;

            if (evt.type === 'fade') currentState = 2;
            else if (evt.type === 'unstan') currentState = 0;
        } 
        else if (currentState === 2) { // Currently Faded
            if (evt.type === 'stan') return `${evt.date} 錯誤：若要恢復熱度，請選擇「回坑」`;
            if (evt.type === 'fade') return `${evt.date} 錯誤：已經是淡坑狀態`;

            if (evt.type === 'restan') currentState = 1;
            else if (evt.type === 'unstan') currentState = 0;
        }
        else if (currentState === 0) { // Currently Unstanned
            if (evt.type === 'fade') return `${evt.date} 錯誤：已經退坑了，無法「淡坑」`;
            if (evt.type === 'unstan') return `${evt.date} 錯誤：已經退坑了，無法再次「退坑」`;

            if (evt.type === 'stan' || evt.type === 'restan') currentState = 1;
        }
    }

    return null;
  };

  const handleSave = () => {
    if (!group) return;

    const validationError = validateTimeline(timeline);
    if (validationError) {
        setError(validationError);
        return;
    }

    // Parse member string
    const list = memberString.split(/,|，|\n/).map(s => s.trim()).filter(s => s);
    const newMembers: Member[] = list.map(item => {
      const match = item.match(/^(.*?)\s*[\(（](.*?)[\)）]/);
      let name = item;
      let cn = '';
      if (match) {
        name = match[1];
        cn = match[2];
      }

      const oldMember = group.members.find(m => m.name === name);
      return { name, cn, rank: oldMember ? oldMember.rank : 0 };
    });

    const cleanTimeline = getSortedTimeline(timeline);
    onSave(group.id, newMembers, logoUrl, cleanTimeline);
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="編輯團體詳細資訊">
      <div className="p-4 overflow-y-auto flex-1 bg-slate-50 space-y-4">

        {/* Logo Section */}
        <div className="bg-white p-3 rounded-xl border border-slate-200 space-y-3">
          <label className="text-xs font-bold text-slate-500 flex items-center gap-1">
            <ImageIcon className="w-3 h-3" /> 團體徽標 (Logo)
          </label>
          <div className="flex items-center gap-4">
             {logoUrl ? (
               <img src={logoUrl} alt="Preview" className="w-16 h-16 rounded-full object-cover border border-slate-200 shadow-sm" />
             ) : (
               <div className="w-16 h-16 rounded-full bg-slate-100 flex items-center justify-center text-slate-400">
                 <ImageIcon className="w-8 h-8" />
               </div>
             )}
             <div className="flex-1 space-y-2">
                <label className="flex items-center gap-2 px-3 py-2 bg-violet-50 text-violet-600 rounded-lg text-xs font-bold cursor-pointer hover:bg-violet-100 transition w-fit border border-violet-100">
                   <Upload className="w-3 h-3" /> 上傳圖片
                   <input type="file" accept="image/*" className="hidden" onChange={handleFileChange} />
                </label>
                <input 
                  type="text" 
                  value={logoUrl}
                  onChange={(e) => setLogoUrl(e.target.value)}
                  placeholder="或貼上圖片網址..."
                  className="w-full p-2 bg-slate-50 rounded-lg border border-slate-200 text-xs focus:ring-2 focus:ring-violet-500 outline-none"
                />
             </div>
          </div>
        </div>

        {/* Timeline Editor Section */}
        <div className={`bg-white p-3 rounded-xl border transition-colors ${error ? 'border-rose-300 ring-4 ring-rose-50' : 'border-slate-200'}`}>
            <div className="flex justify-between items-center mb-2">
                <label className="text-xs font-bold text-slate-500 flex items-center gap-1">
                    追星歷程
                    <Info className="w-3 h-3 text-slate-300" />
                </label>
                <button onClick={addEvent} className="text-xs bg-violet-50 text-violet-600 px-2 py-1 rounded-md font-bold flex items-center gap-1 hover:bg-violet-100 transition">
                    <Plus className="w-3 h-3" /> 新增節點
                </button>
            </div>

            {error && (
                <div className="mb-3 p-2 bg-rose-50 text-rose-600 text-xs rounded-lg flex items-start gap-2 animate-shake">
                    <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
                    <span>{error}</span>
                </div>
            )}

            <div className="space-y-2 relative">
                 {/* Logic connection line visual (simplified) */}
                 {timeline.length > 1 && (
                     <div className="absolute left-[52px] top-4 bottom-4 w-0.5 bg-slate-100 -z-0" />
                 )}

                {timeline.length === 0 && (
                    <div className="text-center py-6 text-slate-400 text-xs bg-slate-50 rounded-lg border border-dashed border-slate-200">
                        點擊「新增節點」設定入坑時間
                    </div>
                )}

                {timeline.map((event, index) => (
                    <div key={index} className="flex gap-2 items-center animate-pop-in relative z-10">
                        <input 
                            type="month" 
                            value={event.date}
                            onChange={(e) => updateEvent(index, 'date', e.target.value)}
                            className="w-[105px] p-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-mono focus:border-violet-400 focus:ring-2 focus:ring-violet-100 outline-none"
                        />
                        <select
                            value={event.type}
                            onChange={(e) => updateEvent(index, 'type', e.target.value as EventType)}
                            className={`flex-1 p-2 border border-slate-200 rounded-lg text-xs font-bold outline-none cursor-pointer
                                ${event.type === 'stan' ? 'text-violet-600 bg-violet-50 border-violet-100' : ''}
                                ${event.type === 'restan' ? 'text-violet-600 bg-violet-50 border-violet-100' : ''}
                                ${event.type === 'fade' ? 'text-slate-600 bg-slate-50 border-slate-200' : ''}
                                ${event.type === 'unstan' ? 'text-slate-400 bg-slate-100 border-slate-200' : ''}
                            `}
                        >
                            <option value="stan">入坑 (開始)</option>
                            <option value="fade">淡坑 (少追)</option>
                            <option value="restan">回坑 (重追)</option>
                            <option value="unstan">退坑 (結束)</option>
                        </select>
                        <button 
                            onClick={() => removeEvent(index)}
                            className="p-2 text-slate-300 hover:text-red-400 hover:bg-red-50 rounded-lg transition"
                            title="移除節點"
                        >
                            <Trash2 className="w-4 h-4" />
                        </button>
                    </div>
                ))}
            </div>
             {timeline.length > 0 && (
                <div className="mt-2 text-[10px] text-slate-400 flex items-center gap-1 justify-end px-1">
                    <ArrowRight className="w-3 h-3" /> 系統會自動驗證邏輯並排序
                </div>
            )}
        </div>

        {/* Members */}
        <div>
          <label className="text-xs font-bold text-slate-500 mb-1 block">成員名單 (英文, 中文)</label>
          <textarea 
            value={memberString}
            onChange={(e) => setMemberString(e.target.value)}
            className="w-full h-40 p-3 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-violet-500 outline-none resize-none font-mono transition-shadow" 
            placeholder="成員A(中文名), 成員B, 成員C..."
          />
        </div>
      </div>
      <div className="p-3 border-t border-slate-100 bg-white rounded-b-2xl">
        <button 
          onClick={handleSave} 
          className="w-full bg-violet-600 text-white py-3 rounded-xl font-bold active:scale-95 transition shadow-lg shadow-violet-200 hover:bg-violet-700 disabled:opacity-50 disabled:cursor-not-allowed"
          disabled={!!error}
        >
          儲存變更
        </button>
      </div>
    </Modal>
  );
};

import React, { useMemo } from 'react';
import { Trophy, Users, Calendar, Heart, Crown, Activity, TrendingUp, Hourglass } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group, EventType } from '../types';

interface DashboardModalProps {
  isOpen: boolean;
  onClose: () => void;
  groups: Group[];
}

export const DashboardModal: React.FC<DashboardModalProps> = ({ isOpen, onClose, groups }) => {

  const stats = useMemo(() => {
    const now = new Date();
    let earliestDate: Date | null = null;
    let activeCount = 0;
    let fadedCount = 0;
    let unstanCount = 0;

    let biasCount = 0; // Rank 1
    let ultCount = 0;  // Rank 2
    let totalMembers = 0;

    const yearlyIntake: Record<string, number> = {};
    let longestStanGroup = { name: '', days: 0, img: '' };

    groups.forEach(g => {
        // 1. Member Stats
        totalMembers += g.members.length;
        g.members.forEach(m => {
            if (m.rank === 1) biasCount++;
            if (m.rank === 2) ultCount++;
        });

        // 2. Status & Date Stats
        let gStanDateStr = g.stanDate;
        let isUnstanned = !!g.unstanDate;
        let isFaded = false;

        // Determine precise status from timeline if available
        if (g.timeline && g.timeline.length > 0) {
             const sorted = [...g.timeline].sort((a, b) => b.date.localeCompare(a.date));
             const lastType = sorted[0].type;

             if (lastType === 'unstan') isUnstanned = true;
             else if (lastType === 'fade') isFaded = true;

             // Find earliest stan date from timeline if root stanDate is missing
             const firstStan = g.timeline.find(t => t.type === 'stan');
             if (firstStan && (!gStanDateStr || firstStan.date < gStanDateStr)) {
                 gStanDateStr = firstStan.date;
             }
        }

        // Count Status
        if (isUnstanned) unstanCount++;
        else if (isFaded) fadedCount++;
        else activeCount++;

        // 3. Yearly Intake
        if (gStanDateStr) {
            const year = gStanDateStr.split('-')[0];
            yearlyIntake[year] = (yearlyIntake[year] || 0) + 1;

            const d = new Date(gStanDateStr);
            if (!earliestDate || d < earliestDate) earliestDate = d;

            // Longest Stan Calculation
            const endDate = isUnstanned && g.unstanDate ? new Date(g.unstanDate) : now;
            const diffTime = Math.abs(endDate.getTime() - d.getTime());
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

            if (diffDays > longestStanGroup.days) {
                longestStanGroup = { name: g.name, days: diffDays, img: g.logoUrl || '' };
            }
        }
    });

    // Fan Age
    let fanAge = "0 天";
    if (earliestDate) {
        const diff = Math.abs(now.getTime() - (earliestDate as Date).getTime());
        const days = Math.ceil(diff / (1000 * 60 * 60 * 24));
        if (days > 365) {
            const years = (days / 365).toFixed(1);
            fanAge = `${years} 年`;
        } else {
            fanAge = `${days} 天`;
        }
    }

    // Chart Data Preparation
    const sortedYears = Object.keys(yearlyIntake).sort();
    const maxIntake = Math.max(...Object.values(yearlyIntake), 1);

    // Fill gaps in years
    const chartData = [];
    if (sortedYears.length > 0) {
        const startY = parseInt(sortedYears[0]);
        const endY = parseInt(sortedYears[sortedYears.length - 1]);
        for (let y = startY; y <= endY; y++) {
            chartData.push({ year: y.toString(), count: yearlyIntake[y.toString()] || 0 });
        }
    }

    return {
        activeCount, fadedCount, unstanCount,
        biasCount, ultCount, totalMembers,
        fanAge, longestStanGroup,
        chartData, maxIntake
    };
  }, [groups]);

  // CSS for Pie Chart
  const totalGroups = groups.length || 1;
  const activeDeg = (stats.activeCount / totalGroups) * 360;
  const fadeDeg = (stats.fadedCount / totalGroups) * 360;
  // Pie chart conic gradient: Active(Purple) -> Fade(Slate-400) -> Unstan(Slate-200)
  const pieStyle = {
      background: `conic-gradient(
        #8b5cf6 0deg ${activeDeg}deg,
        #94a3b8 ${activeDeg}deg ${activeDeg + fadeDeg}deg,
        #e2e8f0 ${activeDeg + fadeDeg}deg 360deg
      )`
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="追星數據儀表板">
      <div className="p-5 overflow-y-auto flex-1 bg-slate-50 space-y-5 no-scrollbar">

        {/* Top Stats Row */}
        <div className="grid grid-cols-3 gap-3">
            <div className="bg-white p-3 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center justify-center gap-1">
                <div className="p-2 bg-violet-100 text-violet-600 rounded-full mb-1">
                    <Hourglass className="w-4 h-4" />
                </div>
                <span className="text-xl font-black text-slate-800">{stats.fanAge}</span>
                <span className="text-[10px] text-slate-400 font-bold">追星資歷</span>
            </div>
            <div className="bg-white p-3 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center justify-center gap-1">
                <div className="p-2 bg-emerald-100 text-emerald-600 rounded-full mb-1">
                    <Activity className="w-4 h-4" />
                </div>
                <span className="text-xl font-black text-slate-800">{stats.activeCount}</span>
                <span className="text-[10px] text-slate-400 font-bold">現役團體</span>
            </div>
             <div className="bg-white p-3 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center justify-center gap-1">
                <div className="p-2 bg-rose-100 text-rose-600 rounded-full mb-1">
                    <Heart className="w-4 h-4" />
                </div>
                <span className="text-xl font-black text-slate-800">{stats.biasCount + stats.ultCount}</span>
                <span className="text-[10px] text-slate-400 font-bold">本命總數</span>
            </div>
        </div>

        {/* Yearly Intake Chart */}
        {stats.chartData.length > 0 && (
            <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
                <div className="flex items-center gap-2 mb-4">
                    <TrendingUp className="w-4 h-4 text-slate-400" />
                    <h3 className="text-sm font-bold text-slate-600">入坑年份趨勢</h3>
                </div>
                <div className="flex items-end gap-2 h-32 pt-2 pb-1">
                    {stats.chartData.map((d) => (
                        <div key={d.year} className="flex-1 flex flex-col items-center gap-1 group">
                             <div className="text-[10px] font-bold text-violet-600 opacity-0 group-hover:opacity-100 transition-opacity absolute -mt-4">
                                {d.count}
                             </div>
                             <div 
                                className="w-full bg-violet-200 rounded-t-md hover:bg-violet-400 transition-colors relative"
                                style={{ height: `${(d.count / stats.maxIntake) * 100}%` }}
                             >
                             </div>
                             <span className="text-[10px] text-slate-400">{d.year.slice(2)}</span>
                        </div>
                    ))}
                </div>
            </div>
        )}

        <div className="grid grid-cols-2 gap-3">
            {/* Status Pie */}
            <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center">
                 <h3 className="text-xs font-bold text-slate-500 mb-3 w-full text-left">狀態分佈</h3>
                 <div className="relative w-24 h-24 rounded-full mb-4 shadow-inner" style={pieStyle}>
                    <div className="absolute inset-4 bg-white rounded-full flex items-center justify-center">
                        <span className="text-xs font-bold text-slate-400">{groups.length} 團</span>
                    </div>
                 </div>
                 <div className="w-full space-y-1.5 px-1">
                    <div className="flex items-center justify-between text-[10px]">
                        <div className="flex items-center gap-1.5">
                            <div className="w-2 h-2 rounded-full bg-violet-500"></div>
                            <span className="text-slate-600 font-medium">坑底/回坑</span>
                        </div>
                        <span className="font-bold text-violet-600">{Math.round((stats.activeCount/totalGroups)*100)}%</span>
                    </div>
                    <div className="flex items-center justify-between text-[10px]">
                        <div className="flex items-center gap-1.5">
                            <div className="w-2 h-2 rounded-full bg-slate-400"></div>
                            <span className="text-slate-600 font-medium">淡坑</span>
                        </div>
                        <span className="font-bold text-slate-500">{Math.round((stats.fadedCount/totalGroups)*100)}%</span>
                    </div>
                    <div className="flex items-center justify-between text-[10px]">
                        <div className="flex items-center gap-1.5">
                            <div className="w-2 h-2 rounded-full bg-slate-200"></div>
                            <span className="text-slate-600 font-medium">退坑</span>
                        </div>
                        <span className="font-bold text-slate-400">{Math.round((stats.unstanCount/totalGroups)*100)}%</span>
                    </div>
                 </div>
            </div>

            {/* Bias Pyramid */}
            <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col">
                 <h3 className="text-xs font-bold text-slate-500 mb-3 text-left">本命金字塔</h3>

                 <div className="flex-1 flex flex-col justify-center items-center gap-1">
                    {/* Level 1: Ult */}
                    <div className="w-1/3 bg-amber-100 border border-amber-200 text-amber-600 rounded-lg py-1.5 text-center shadow-sm relative group">
                        <Crown className="w-3 h-3 absolute -left-1 top-1/2 -translate-y-1/2 -ml-3 text-amber-400" />
                        <span className="text-xs font-bold">{stats.ultCount}</span>
                    </div>

                    {/* Level 2: Bias */}
                    <div className="w-2/3 bg-rose-100 border border-rose-200 text-rose-600 rounded-lg py-1.5 text-center shadow-sm relative">
                        <Heart className="w-3 h-3 absolute -left-1 top-1/2 -translate-y-1/2 -ml-3 text-rose-400" />
                        <span className="text-xs font-bold">{stats.biasCount}</span>
                    </div>

                    {/* Level 3: All */}
                    <div className="w-full bg-slate-100 border border-slate-200 text-slate-500 rounded-lg py-1.5 text-center shadow-sm relative">
                        <Users className="w-3 h-3 absolute -left-1 top-1/2 -translate-y-1/2 -ml-3 text-slate-400" />
                        <span className="text-xs font-bold">{stats.totalMembers}</span>
                    </div>
                 </div>
                 <p className="text-[10px] text-center text-slate-400 mt-2">總計人數</p>
            </div>
        </div>

        {/* Fun Insight: Longest Stan */}
        {stats.longestStanGroup.name && (
            <div className="bg-gradient-to-r from-violet-500 to-fuchsia-500 p-4 rounded-2xl shadow-lg text-white flex items-center justify-between">
                <div>
                    <div className="flex items-center gap-1 text-white/80 text-xs font-bold mb-1">
                        <Trophy className="w-3 h-3" /> 最長情的陪伴
                    </div>
                    <div className="text-lg font-black">{stats.longestStanGroup.name}</div>
                    <div className="text-xs opacity-90">{stats.longestStanGroup.days} 天</div>
                </div>
                {stats.longestStanGroup.img ? (
                    <img src={stats.longestStanGroup.img} className="w-12 h-12 rounded-full border-2 border-white/30 bg-white object-cover" />
                ) : (
                    <div className="w-12 h-12 rounded-full border-2 border-white/30 bg-white/20 flex items-center justify-center">
                        <Heart className="w-6 h-6 text-white" />
                    </div>
                )}
            </div>
        )}

      </div>
      <div className="p-3 border-t border-slate-100 bg-white rounded-b-2xl">
        <button onClick={onClose} className="w-full py-2 text-slate-400 text-sm hover:text-slate-600">關閉</button>
      </div>
    </Modal>
  );
};

import { useState, useEffect, useCallback } from 'react';
import { BookHeart, Database, LayoutGrid, List, Plus, X, Loader2, HelpCircle, Layers, CheckCircle, AlertTriangle, History, BarChart3 } from 'lucide-react';
import { Group, Member, GroupDetails, ToastType, TimelineEvent } from './types';
import { PRESET_DB } from './constants';
import { fetchFromWikiAuto, fetchGroupLogo } from './services/wikiService';
import { GroupCard } from './components/GroupCard';
import { EditGroupModal } from './components/EditGroupModal';
import { GroupDetailsModal } from './components/GroupDetailsModal';
import { DataModal } from './components/DataModal';
import { TimelineModal } from './components/TimelineModal';
import { DashboardModal } from './components/DashboardModal';
import { Modal } from './components/ui/Modal';
import { normalizeString } from './utils';

interface AlertConfig {
  title: string;
  msg: string;
  action?: () => void;
  actionLabel?: string;
}

export default function App() {
  // --- State ---
  const [myGroups, setMyGroups] = useState<Group[]>([]);
  const [inputQuery, setInputQuery] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isInputError, setIsInputError] = useState(false);
  const [viewMode, setViewMode] = useState<'card' | 'list'>('card');

  // Modals
  const [editingGroup, setEditingGroup] = useState<Group | null>(null);
  const [detailsModalGroup, setDetailsModalGroup] = useState<Group | null>(null);
  const [isDataModalOpen, setIsDataModalOpen] = useState(false);
  const [isTimelineOpen, setIsTimelineOpen] = useState(false);
  const [isDashboardOpen, setIsDashboardOpen] = useState(false);
  const [deleteConfirmGroup, setDeleteConfirmGroup] = useState<Group | null>(null);
  const [alertConfig, setAlertConfig] = useState<AlertConfig | null>(null);

  // Toast
  const [toast, setToast] = useState<{ msg: string; type: ToastType } | null>(null);

  // --- Effects ---
  useEffect(() => {
    const saved = localStorage.getItem('stan-binder-v7-react');
    if (saved) {
      try {
        setMyGroups(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load data", e);
      }
    }
  }, []);

  useEffect(() => {
    if (myGroups.length > 0 || localStorage.getItem('stan-binder-v7-react')) {
      localStorage.setItem('stan-binder-v7-react', JSON.stringify(myGroups));
    }
  }, [myGroups]);

  // --- Handlers ---

  const showToast = (msg: string, type: ToastType = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const resetError = () => setIsInputError(false);

  // Wrapped in useCallback to act as a stable reference for the alert action if needed
  const handleForceAdd = useCallback(() => {
    if (!inputQuery.trim()) return;
    const groupName = inputQuery.trim();

    const newGroup: Group = {
      id: Date.now().toString(),
      name: groupName,
      stanDate: '',
      isExpanded: true,
      members: []
    };
    setMyGroups(prev => [newGroup, ...prev]);
    setEditingGroup(newGroup);
    setInputQuery('');
    resetError();

    // Try to fetch logo in background for manual add
    fetchGroupLogo(groupName).then(url => {
      if (url) {
        setMyGroups(prev => prev.map(g => 
          g.id === newGroup.id ? { ...g, logoUrl: url } : g
        ));
      }
    });
  }, [inputQuery]);

  const handleSmartAdd = async () => {
    const rawInput = inputQuery.trim();
    if (!rawInput) return;

    setIsLoading(true);
    resetError();

    const key = normalizeString(rawInput);

    // 1. Check Preset
    let preset = PRESET_DB[key];
    if (preset) {
      if (preset.ref && PRESET_DB[preset.ref]) {
        preset = PRESET_DB[preset.ref];
      }

      if (!preset.n) {
         showToast(`${key} 設定錯誤`, 'error');
         setIsLoading(false);
         return;
      }

      if (myGroups.find(g => g.name === preset.n)) {
        showToast(`${preset.n} 已存在`, 'error');
        setIsLoading(false);
        return;
      }

      const newGroup: Group = {
        id: Date.now().toString(),
        name: preset.n,
        stanDate: '',
        isExpanded: true,
        members: preset.m ? preset.m.map(m => ({ name: m[0], cn: m[1] || '', rank: 0 })) : [],
        logoUrl: preset.l
      };

      setMyGroups(prev => [newGroup, ...prev]);
      showToast(`已新增 ${newGroup.name}`);
      setInputQuery('');
      setIsLoading(false);

      // Background fetch logo if not provided in preset
      if (!newGroup.logoUrl) {
        fetchGroupLogo(newGroup.name).then(url => {
          if (url) {
            setMyGroups(prev => prev.map(g => 
              g.id === newGroup.id ? { ...g, logoUrl: url } : g
            ));
          }
        });
      }

      return;
    }

    // 2. Wiki Search
    try {
      const data = await fetchFromWikiAuto(rawInput);
      if (myGroups.find(g => g.name === data.name)) {
        showToast(`${data.name} 已存在`, 'error');
      } else {
        // Prevent adding empty groups automatically
        if (data.members.length === 0) {
          setAlertConfig({
            title: "無法抓取成員",
            msg: `找到 "${data.name}" 但無法自動抓取成員名單。\n\n您可以選擇手動新增此團體並自行編輯成員。`,
            action: handleForceAdd,
            actionLabel: "手動新增"
          });
        } else {
          const newGroup: Group = {
            id: Date.now().toString(),
            name: data.name,
            stanDate: '',
            isExpanded: true,
            members: data.members,
            logoUrl: data.logoUrl
          };
          setMyGroups(prev => [newGroup, ...prev]);
          showToast(`已新增 ${data.name}`);
          setInputQuery('');
        }
      }
    } catch (e) {
      setIsInputError(true);
      setAlertConfig({
        title: "找不到團體",
        msg: `找不到 "${rawInput}"。\n請確認拼字，或者直接手動建立此團體。`,
        action: handleForceAdd,
        actionLabel: `手動新增 "${rawInput}"`
      });
    } finally {
      setIsLoading(false);
    }
  };

  // Group Actions - Wrapped in useCallback for memoization
  const handleToggleExpand = useCallback((id: string) => {
    setMyGroups(prev => prev.map(g => g.id === id ? { ...g, isExpanded: !g.isExpanded } : g));
  }, []);

  const handleMove = useCallback((index: number, dir: number) => {
    setMyGroups(prev => {
      const newGroups = [...prev];
      const targetIndex = index + dir;
      if (targetIndex >= 0 && targetIndex < newGroups.length) {
        // Optional: Prevent moving an active group below an unstanned group if we want strict sorting
        // For now, we allow manual sort but re-sort on save
        [newGroups[index], newGroups[targetIndex]] = [newGroups[targetIndex], newGroups[index]];
        return newGroups;
      }
      return prev;
    });
  }, []);

  const handleToggleRank = useCallback((groupId: string, member: Member) => {
    setMyGroups(prev => prev.map(g => {
      if (g.id !== groupId) return g;
      return {
        ...g,
        members: g.members.map(m => 
          m.name === member.name ? { ...m, rank: (m.rank + 1) % 3 } : m
        )
      };
    }));
  }, []);

  const handleRemoveGroupClick = useCallback((group: Group) => {
    setDeleteConfirmGroup(group);
  }, []);

  const handleEditClick = useCallback((group: Group) => {
    setEditingGroup(group);
  }, []);

  const handleDetailsClick = useCallback((group: Group) => {
    setDetailsModalGroup(group);
  }, []);

  const performDeleteGroup = () => {
    if (deleteConfirmGroup) {
      setMyGroups(prev => prev.filter(g => g.id !== deleteConfirmGroup.id));
      showToast("團體已移除");
      setDeleteConfirmGroup(null);
    }
  };

  const handleSaveEdit = (groupId: string, members: Member[], logoUrl: string, timeline: TimelineEvent[]) => {
    setMyGroups(prev => {
        // Calculate derived fields from timeline for compatibility/sorting
        // 1. stanDate: The earliest 'stan' date
        const earliestStan = timeline
            .filter(e => e.type === 'stan')
            .sort((a, b) => a.date.localeCompare(b.date))[0]?.date || '';

        // 2. unstanDate: If the LATEST event is 'unstan', use that date. Otherwise undefined (active).
        // This logic determines if the card is grayed out.
        // We sort by date DESC to find latest.
        const sortedEvents = [...timeline].sort((a, b) => b.date.localeCompare(a.date));
        const latestEvent = sortedEvents[0];

        // If latest event is unstan, mark as unstan. Otherwise treat as active (including fade/restan).
        const derivedUnstanDate = (latestEvent && latestEvent.type === 'unstan') ? latestEvent.date : undefined;

        const updatedGroups = prev.map(g => g.id === groupId ? { 
            ...g, 
            members, 
            logoUrl, 
            timeline,
            stanDate: earliestStan || g.stanDate, // Fallback to existing if no timeline stan
            unstanDate: derivedUnstanDate
        } : g);

        // Sort: Active groups first, Unstanned (with unstanDate) last. Keep relative order otherwise.
        return updatedGroups.sort((a, b) => {
            const aUnstan = !!a.unstanDate;
            const bUnstan = !!b.unstanDate;
            if (aUnstan === bUnstan) return 0; // Keep relative order
            return aUnstan ? 1 : -1; // Unstanned goes to bottom
        });
    });
    showToast("團體已更新");
  };

  const handleSaveDetails = (groupId: string, details: GroupDetails) => {
    setMyGroups(prev => prev.map(g => g.id === groupId ? { ...g, details } : g));
    showToast("詳細筆記已儲存");
  };

  const handleImport = (data: Group[]) => {
    setMyGroups(data);
    showToast(`成功匯入 ${data.length} 個團體`);
  };

  const handleReset = () => {
    if (window.confirm("恢復原廠設定：清除所有資料？")) {
      setMyGroups([]);
      localStorage.removeItem('stan-binder-v7-react');
      showToast("所有資料已清除");
      setIsDataModalOpen(false);
    }
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: 'smooth' });

  return (
    <div className="max-w-md mx-auto bg-slate-50 min-h-screen shadow-2xl relative overflow-hidden flex flex-col">
      {/* Header */}
      <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-4 py-3 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-2.5 cursor-pointer group" onClick={scrollToTop}>
          <div className="bg-gradient-to-br from-violet-500 to-fuchsia-500 text-white p-1.5 rounded-lg shadow-md shadow-violet-200 group-hover:scale-105 transition-transform">
            <BookHeart className="w-5 h-5" />
          </div>
          <div className="flex items-center gap-2">
            <h1 className="text-xl font-bold text-slate-800 tracking-tight group-hover:text-violet-700 transition-colors">追星歷程記錄</h1>
            {myGroups.length > 0 && (
              <span className="text-xs font-bold text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full border border-slate-200">
                {myGroups.length}
              </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button 
            onClick={() => setIsDashboardOpen(true)}
            className="p-2 text-slate-500 bg-slate-100/80 hover:bg-slate-100 rounded-full active:bg-slate-200 transition"
            title="數據儀表板"
          >
            <BarChart3 className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setIsTimelineOpen(true)}
            className="p-2 text-slate-500 bg-slate-100/80 hover:bg-slate-100 rounded-full active:bg-slate-200 transition"
            title="追星時間軸"
          >
            <History className="w-5 h-5" />
          </button>
          <button onClick={() => setIsDataModalOpen(true)} className="p-2 text-slate-500 bg-slate-100/80 hover:bg-slate-100 rounded-full active:bg-slate-200 transition">
            <Database className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setViewMode(v => v === 'card' ? 'list' : 'card')} 
            className="p-2 text-slate-500 bg-slate-100/80 hover:bg-slate-100 rounded-full active:bg-slate-200 transition">
            {viewMode === 'card' ? <List className="w-5 h-5" /> : <LayoutGrid className="w-5 h-5" />}
          </button>
        </div>
      </header>

      {/* Quick Add Bar */}
      <div className="bg-white p-3 border-b border-slate-100 sticky top-[61px] z-20 shadow-sm transition-all">
        <div className="relative flex items-center gap-2">
          <div className="relative flex-1">
            <input 
              value={inputQuery}
              onChange={(e) => { setInputQuery(e.target.value); resetError(); }}
              onKeyDown={(e) => e.key === 'Enter' && handleSmartAdd()}
              type="text" 
              placeholder="輸入團名 (如: RIIZE, ZB1)" 
              disabled={isLoading}
              className={`
                w-full pl-4 pr-10 py-3 bg-slate-50 border-2 rounded-2xl outline-none text-base font-medium transition-all
                placeholder-slate-400
                ${isInputError ? 'border-red-300 bg-red-50 animate-shake' : 'border-slate-100 focus:border-violet-300 focus:ring-4 focus:ring-violet-100 focus:bg-white'}
              `}
            />
            {inputQuery && (
              <button onClick={() => { setInputQuery(''); resetError(); }} className="absolute right-3 top-3.5 text-slate-400 hover:text-slate-600">
                <X className="w-4 h-4" />
              </button>
            )}
          </div>
          <button 
            onClick={handleSmartAdd}
            disabled={isLoading || !inputQuery}
            className={`
              text-white p-3 rounded-2xl shadow-lg active:scale-95 transition flex items-center justify-center min-w-[50px]
              ${isInputError ? 'bg-rose-500 shadow-rose-200' : 'bg-violet-600 shadow-violet-200 hover:bg-violet-700'}
              ${(isLoading || !inputQuery) ? 'opacity-50 scale-100 shadow-none' : ''}
            `}
          >
            {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Plus className="w-6 h-6" />}
          </button>
        </div>

        {isInputError && (
          <div className="mt-2 text-center animate-pulse">
            <button onClick={handleForceAdd} className="text-xs text-violet-500 font-bold hover:underline flex items-center justify-center gap-1 mx-auto">
              <HelpCircle className="w-3 h-3" /> 找不到？手動新增 "{inputQuery}"
            </button>
          </div>
        )}
      </div>

      {/* Main Content */}
      <main className={`p-4 flex-1 overflow-y-auto ${viewMode === 'list' ? 'grid grid-cols-2 gap-3 items-stretch' : 'space-y-4'}`}>

        {/* Empty State */}
        {myGroups.length === 0 && (
          <div className={`flex flex-col items-center justify-center py-12 text-center px-6 opacity-60 ${viewMode === 'list' ? 'col-span-2' : ''}`}>
            <div className="w-16 h-16 bg-slate-100 text-slate-300 rounded-full flex items-center justify-center mb-4">
              <Layers className="w-8 h-8" />
            </div>
            <p className="text-slate-400 font-medium leading-relaxed">尚無團體。<br/>試試輸入 "RIIZE" 或 "TWS"</p>
            <div className="mt-5">
              <button onClick={() => setIsDataModalOpen(true)} className="text-violet-500 text-sm font-bold hover:text-violet-600 transition-colors">已有備份？點此匯入</button>
            </div>
          </div>
        )}

        {/* Group Cards */}
        {myGroups.map((group, index) => (
          <div key={group.id} className={viewMode === 'list' ? 'col-span-1 h-full' : ''}>
             <GroupCard 
               group={group}
               isFirst={index === 0}
               isLast={index === myGroups.length - 1}
               onMove={(dir) => handleMove(index, dir)}
               onEdit={() => handleEditClick(group)}
               onDetails={() => handleDetailsClick(group)}
               onToggleExpand={() => handleToggleExpand(group.id)}
               onToggleRank={(m) => handleToggleRank(group.id, m)}
               onRemove={() => handleRemoveGroupClick(group)}
             />
          </div>
        ))}
      </main>

      {/* Modals */}
      <EditGroupModal 
        isOpen={!!editingGroup} 
        onClose={() => setEditingGroup(null)} 
        group={editingGroup} 
        onSave={handleSaveEdit} 
      />

      <GroupDetailsModal
        isOpen={!!detailsModalGroup}
        onClose={() => setDetailsModalGroup(null)}
        group={detailsModalGroup}
        onSave={handleSaveDetails}
      />

      <TimelineModal 
        isOpen={isTimelineOpen}
        onClose={() => setIsTimelineOpen(false)}
        groups={myGroups}
      />

      <DashboardModal 
        isOpen={isDashboardOpen} 
        onClose={() => setIsDashboardOpen(false)} 
        groups={myGroups} 
      />

      <DataModal 
        isOpen={isDataModalOpen} 
        onClose={() => setIsDataModalOpen(false)} 
        data={myGroups} 
        onImport={handleImport} 
        onReset={handleReset} 
      />

      {/* Delete Confirmation Modal */}
      <Modal 
        isOpen={!!deleteConfirmGroup} 
        onClose={() => setDeleteConfirmGroup(null)} 
        title="確認移除"
      >
        <div className="p-4">
          <p className="text-slate-600 mb-6">
            確定要移除 <span className="font-bold text-slate-800">{deleteConfirmGroup?.name}</span> 嗎？此動作無法復原。
          </p>
          <div className="flex gap-3">
              <button 
                onClick={() => setDeleteConfirmGroup(null)} 
                className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold active:scale-95 transition hover:bg-slate-200"
              >
                取消
              </button>
              <button 
                onClick={performDeleteGroup} 
                className="flex-1 py-3 bg-rose-500 text-white rounded-xl font-bold shadow-lg shadow-rose-200 active:scale-95 transition hover:bg-rose-600"
              >
                確認移除
              </button>
          </div>
        </div>
      </Modal>

      {/* Alert Modal */}
      <Modal 
        isOpen={!!alertConfig} 
        onClose={() => setAlertConfig(null)} 
        title={alertConfig?.title || '提示'}
      >
         <div className="p-4">
           <div className="flex flex-col items-center text-center gap-3">
              <div className="w-12 h-12 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center">
                  <AlertTriangle className="w-6 h-6" />
              </div>
              <p className="text-slate-700 font-medium whitespace-pre-wrap">{alertConfig?.msg}</p>
           </div>

           {alertConfig?.action ? (
             <div className="flex gap-3 mt-6">
                <button 
                  onClick={() => setAlertConfig(null)} 
                  className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold active:scale-95 transition hover:bg-slate-200"
                >
                  取消
                </button>
                <button 
                  onClick={() => {
                    alertConfig.action?.();
                    setAlertConfig(null);
                  }}
                  className="flex-1 py-3 bg-violet-600 text-white rounded-xl font-bold shadow-lg shadow-violet-200 active:scale-95 transition hover:bg-violet-700"
                >
                  {alertConfig.actionLabel || '確定'}
                </button>
             </div>
           ) : (
             <button 
               onClick={() => setAlertConfig(null)} 
               className="w-full mt-6 py-3 bg-slate-800 text-white rounded-xl font-bold active:scale-95 transition hover:bg-slate-900"
             >
               我知道了
             </button>
           )}
         </div>
      </Modal>

      {/* Toast */}
      {toast && (
        <div className={`
          fixed bottom-6 left-1/2 transform -translate-x-1/2 px-4 py-2.5 rounded-full text-xs font-bold shadow-xl shadow-slate-300/50
          transition-all duration-300 flex items-center gap-2 pointer-events-none z-[110]
          animate-pop-in border border-white/20 backdrop-blur-md
          ${toast.type === 'error' ? 'bg-rose-500 text-white' : 'bg-slate-800 text-white'}
        `}>
          {toast.type === 'success' ? <CheckCircle className="w-4 h-4 text-emerald-400" /> : <AlertTriangle className="w-4 h-4 text-white" />}
          {toast.msg}
        </div>
      )}
    </div>
  );
}

import React, { useMemo } from 'react';
