import React, { useMemo } from 'react';
import { Trophy, Users, Calendar, Heart, Crown, Activity, TrendingUp, Hourglass } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group } from '../types';

interface DashboardModalProps {
  isOpen: boolean;
  onClose: () => void;
  groups: Group[];
}

export const DashboardModal: React.FC<DashboardModalProps> = ({ isOpen, onClose, groups }) => {

  const stats = useMemo(() => {
    const now = new Date();
    let earliestDate: Date | null = null;
    let activeCount = 0;
    let fadedCount = 0;
    let unstanCount = 0;

    let biasCount = 0; // Rank 1
    let ultCount = 0;  // Rank 2
    let totalMembers = 0;

    const yearlyIntake: Record<number, number> = {};
    let longestStanGroup = { name: '', days: 0, img: '' };

    groups.forEach(g => {
        // 1. Member Stats
        totalMembers += g.members.length;
        g.members.forEach(m => {
            if (m.rank === 1) biasCount++;
            if (m.rank === 2) ultCount++;
        });

        // 2. Advanced Status Logic
        // Determine status based on the LATEST event in timeline if available
        let isUnstanned = !!g.unstanDate;
        let isFaded = false;

        // We also need to find the specific "Start Date" for the chart
        let startDateStr = g.stanDate;

        if (g.timeline && g.timeline.length > 0) {
             // Sort: Newest First for Status
             const sortedDesc = [...g.timeline].sort((a, b) => b.date.localeCompare(a.date));
             const latestType = sortedDesc[0].type;

             // Override status based on latest timeline event
             if (latestType === 'unstan') {
                 isUnstanned = true;
                 isFaded = false;
             } else if (latestType === 'fade') {
                 isFaded = true;
                 isUnstanned = false;
             } else {
                 // stan or restan -> Active
                 isUnstanned = false;
                 isFaded = false;
             }

             // Sort: Oldest First for Start Date
             const sortedAsc = [...g.timeline].sort((a, b) => a.date.localeCompare(b.date));

             // Try to find the first explicit 'stan'
             const firstStan = sortedAsc.find(t => t.type === 'stan');
             if (firstStan) {
                 startDateStr = firstStan.date;
             } else if (!startDateStr) {
                 // Fallback: Use the very first event date if no stanDate is set
                 startDateStr = sortedAsc[0].date;
             }
        }

        // Count Status
        if (isUnstanned) unstanCount++;
        else if (isFaded) fadedCount++;
        else activeCount++;

        // 3. Yearly Intake & Fan Age
        if (startDateStr && startDateStr.length >= 4) {
            // Robust parsing: take first 4 chars as year
            const yearStr = startDateStr.substring(0, 4);
            const year = parseInt(yearStr);

            if (!isNaN(year) && year > 1990 && year <= now.getFullYear() + 1) {
                yearlyIntake[year] = (yearlyIntake[year] || 0) + 1;

                const d = new Date(startDateStr);
                if (!isNaN(d.getTime())) {
                    if (!earliestDate || d < earliestDate) earliestDate = d;

                    // Longest Stan Calculation
                    let endDate = now;
                    // If unstanned, try to find the specific unstan date
                    if (isUnstanned) {
                        if (g.unstanDate) endDate = new Date(g.unstanDate);
                        else if (g.timeline) {
                             // Find latest unstan event
                             const lastUnstan = g.timeline.find(t => t.type === 'unstan');
                             if (lastUnstan) endDate = new Date(lastUnstan.date);
                        }
                    }

                    const diffTime = Math.abs(endDate.getTime() - d.getTime());
                    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

                    if (diffDays > longestStanGroup.days) {
                        longestStanGroup = { name: g.name, days: diffDays, img: g.logoUrl || '' };
                    }
                }
            }
        }
    });

    // Fan Age Display
    let fanAge = "0 天";
    if (earliestDate) {
        const diff = Math.abs(now.getTime() - (earliestDate as Date).getTime());
        const days = Math.ceil(diff / (1000 * 60 * 60 * 24));
        if (days > 365) {
            const years = (days / 365).toFixed(1);
            fanAge = `${years} 年`;
        } else {
            fanAge = `${days} 天`;
        }
    }

    // Chart Data Preparation
    const years = Object.keys(yearlyIntake).map(Number).sort((a, b) => a - b);
    const maxIntake = Math.max(...Object.values(yearlyIntake), 1);

    const chartData = [];
    if (years.length > 0) {
        const startY = years[0];
        const endY = years[years.length - 1];
        // Prevent huge range if bad data
        const safeEndY = Math.min(endY, now.getFullYear() + 1);

        if (safeEndY - startY < 50) { 
            for (let y = startY; y <= safeEndY; y++) {
                chartData.push({ year: y, count: yearlyIntake[y] || 0 });
            }
        } else {
             // Fallback for weird ranges: just show data points
             years.forEach(y => {
                 chartData.push({ year: y, count: yearlyIntake[y] });
             });
        }
    }

    return {
        activeCount, fadedCount, unstanCount,
        biasCount, ultCount, totalMembers,
        fanAge, longestStanGroup,
        chartData, maxIntake
    };
  }, [groups]);

  // CSS for Pie Chart
  const totalGroups = groups.length || 1;
  const activeDeg = (stats.activeCount / totalGroups) * 360;
  const fadeDeg = (stats.fadedCount / totalGroups) * 360;

  const pieStyle = {
      background: `conic-gradient(
        #8b5cf6 0deg ${activeDeg}deg,
        #94a3b8 ${activeDeg}deg ${activeDeg + fadeDeg}deg,
        #e2e8f0 ${activeDeg + fadeDeg}deg 360deg
      )`
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="追星數據儀表板">
