import React, { useState, useEffect } from 'react';
import { ArrowUp, ArrowDown, Pencil, ChevronUp, ChevronDown, CalendarHeart, Crown, Heart, Users, NotebookPen, CalendarOff } from 'lucide-react';
import { Group, Member } from '../types';
import { MemberGrid } from './MemberGrid';

interface GroupCardProps {
  group: Group;
  isFirst: boolean;
  isLast: boolean;
  onMove: (dir: number) => void;
  onEdit: () => void;
  onDetails: () => void;
  onToggleExpand: () => void;
  onToggleRank: (member: Member) => void;
  onRemove: () => void;
}

export const GroupCard: React.FC<GroupCardProps> = React.memo(({ 
  group, isFirst, isLast, onMove, onEdit, onDetails, onToggleExpand, onToggleRank, onRemove 
}) => {
  const biasMembers = group.members.filter(m => m.rank === 1);
  const ultMembers = group.members.filter(m => m.rank === 2);
  const [imageError, setImageError] = useState(false);

  // Reset error state when url changes
  useEffect(() => {
    setImageError(false);
  }, [group.logoUrl]);

  // Visual state
  const isUnstanned = !!group.unstanDate;

  // Detect if current status is "Fade" (latest event is 'fade')
  // We look at the timeline if available, otherwise assume active unless unstanned
  // Use spread syntax [...] to create a shallow copy before sorting to avoid mutating the original array
  const isFaded = !isUnstanned && group.timeline && group.timeline.length > 0 && 
    [...group.timeline].sort((a, b) => b.date.localeCompare(a.date))[0].type === 'fade';

  return (
    <div className={`
      bg-white rounded-2xl shadow-sm border overflow-hidden animate-pop-in h-full flex flex-col w-full transition-all duration-200
      ${isUnstanned ? 'border-slate-100 opacity-75 grayscale' : isFaded ? 'border-amber-100' : 'border-slate-100 hover:shadow-md'}
    `}>

      <div className={`flex items-stretch min-h-[100px] ${isUnstanned ? 'bg-slate-50' : isFaded ? 'bg-amber-50/30' : ''}`}>
          {/* Main Content Area (Click to expand) */}
          <div className="flex-1 p-3.5 flex gap-3 cursor-pointer select-none group" onClick={onToggleExpand}>

            {/* Logo Column */}
            <div className="flex-shrink-0 pt-0.5">
              {group.logoUrl && !imageError ? (
                <img 
                  src={group.logoUrl} 
                  alt={group.name} 
                  className={`w-12 h-12 rounded-full object-cover border shadow-sm ${isUnstanned ? 'border-slate-200' : 'border-slate-100'}`}
                  onError={() => setImageError(true)}
                />
              ) : (
                <div className="w-12 h-12 rounded-full bg-slate-50 flex items-center justify-center text-slate-300 border border-slate-100 group-hover:bg-slate-100 transition-colors">
                    <Users className="w-6 h-6" />
                </div>
              )}
            </div>

            {/* Info Column */}
            <div className="flex-1 min-w-0 flex flex-col justify-between">

                {/* Top: Name & Date */}
                <div className="mb-2">
                  <h2 className={`text-lg font-bold leading-tight break-words transition-colors 
                    ${isUnstanned ? 'text-slate-500' : isFaded ? 'text-slate-700' : 'text-slate-800 group-hover:text-violet-700'}
                  `}>
                    {group.name}
                    {isFaded && <span className="text-[10px] ml-2 px-1.5 py-0.5 bg-amber-100 text-amber-600 rounded-full align-middle font-medium">淡坑</span>}
                  </h2>
                  <div className="flex flex-wrap items-center gap-x-2 gap-y-1 mt-1">
                    {group.stanDate && (
                        <div className={`text-[11px] font-medium flex items-center gap-1 ${isUnstanned ? 'text-slate-400' : 'text-violet-500'}`}>
                        <CalendarHeart className="w-3 h-3 flex-shrink-0" /> <span>{group.stanDate}</span>
                        </div>
                    )}
                    {group.unstanDate && (
                        <div className="text-[11px] text-slate-400 font-medium flex items-center gap-1">
                            <span>~</span> <CalendarOff className="w-3 h-3 flex-shrink-0" /> <span>{group.unstanDate}</span>
                        </div>
                    )}
                  </div>
                </div>

                {/* Bottom: Tags & Actions Row */}
                <div className="flex items-end justify-between gap-2">
                    {/* Tags */}
                    <div className="flex flex-wrap gap-1 min-h-[18px]">
                      {ultMembers.map(m => (
                        <span key={m.name} className={`inline-flex items-center gap-1 px-1.5 py-0.5 text-[10px] font-bold rounded-full border max-w-full ${isUnstanned ? 'bg-slate-200 text-slate-500 border-slate-300' : 'bg-amber-100 text-amber-700 border-amber-200'}`}>
                          <Crown className="w-3 h-3 fill-current flex-shrink-0" /> <span className="truncate">{m.name}</span>
                        </span>
                      ))}
