import { Member } from '../types';
import { isFuzzyMatch } from '../utils';

export const parseMembers = (htmlString: string): Member[] => {
  try {
    const parser = new DOMParser();
    const doc = parser.parseFromString(htmlString, 'text/html');
    let names: string[] = [];

    // 1. Search for Member section (Priority: H2/H3 Headers)
    const headers = Array.from(doc.querySelectorAll('h2, h3'));
    const memberHeader = headers.find(h => {
      const text = h.textContent?.toLowerCase() || '';
      return (text.includes('members') || text.includes('line-up')) && 
             !text.includes('former') && 
             !text.includes('past');
    });

    if (memberHeader) {
      let el = memberHeader.parentElement?.nextElementSibling || memberHeader.nextElementSibling;
      let limit = 0;
      // Search siblings for a list (UL) or a table
      while (el && limit < 10) {
        if (el.tagName === 'UL') {
          el.querySelectorAll('li').forEach(li => {
            // Clean common wiki list patterns: "Name – role", "Name: role", "Name (Birth name)"
            let text = li.textContent?.replace(/\[.*?\]/g, '').split(/–|-|:|：/)[0].trim();
            if (text) names.push(text);
          });
          break;
        }
        if (el.tagName === 'TABLE') {
          // If members are in a table, usually the first column (except if it's Rank/Position)
          el.querySelectorAll('tr').forEach((row, i) => {
             if (i === 0) return; // skip header
             const cells = row.querySelectorAll('td');
             if (cells.length > 0) {
                 const firstCellText = cells[0].textContent?.trim();
                 if (firstCellText && firstCellText.length > 1 && !/^\d+$/.test(firstCellText)) {
                     names.push(firstCellText);
                 }
             }
          });
          break;
        }
        el = el.nextElementSibling;
        limit++;
      }
    }

    // 2. Fallback: Infobox search (Common for very new groups)
    if (names.length === 0) {
      const infobox = doc.querySelector('.infobox');
      if (infobox) {
        const rows = infobox.querySelectorAll('tr');
        rows.forEach(row => {
          const th = row.querySelector('th');
          const thText = th?.textContent?.toLowerCase() || '';
          if (thText.includes('members') || thText.includes('current members')) {
            const td = row.querySelector('td');
            if (td) {
              // Handle names separated by <br>, <li>, or commas
              const rawNames = td.innerText.split(/\n|,|·/).map(n => n.trim());
              rawNames.forEach(n => {
                  let clean = n.replace(/\[.*?\]/g, '').trim();
                  if (clean && clean.length > 1) names.push(clean);
              });
            }
          }
        });
      }
    }

    // Final cleanup: Remove roles, parenthesis, and duplicates
    const cleanedNames = names.map(n => n.split('(')[0].split('/')[0].trim()).filter(n => n.length > 0);
    const uniqueNames = Array.from(new Set(cleanedNames));

    return uniqueNames.slice(0, 30).map(n => ({ 
      name: n,
      cn: '', 
      rank: 0 
    }));
  } catch (e) {
    console.error("Parse Error", e);
    return [];
  }
};

export const fetchFromWikiAuto = async (query: string): Promise<{ name: string; members: Member[]; logoUrl?: string }> => {
  // Search with a more focused query
  const searchUrl = `https://en.wikipedia.org/w/api.php?origin=*&action=query&list=search&srsearch=${encodeURIComponent(query + " k-pop")}&format=json&srlimit=5`;

  const searchRes = await fetch(searchUrl);
  const searchData = await searchRes.json();

  if (!searchData.query.search || searchData.query.search.length === 0) {
    throw new Error("No results found");
  }

  // Find the best match among top 5 results
  const results = searchData.query.search;
  let bestResult = null;

  for (const res of results) {
      if (isFuzzyMatch(query, res.title)) {
          bestResult = res;
          break;
      }
  }

  // If no good fuzzy match, fall back to the very first result but warn in console
  if (!bestResult) {
      bestResult = results[0];
  }

  const pageTitle = bestResult.title;

  // Parallel fetch: Content (for members) + Metadata (for image)
  const parseUrl = `https://en.wikipedia.org/w/api.php?origin=*&action=parse&page=${encodeURIComponent(pageTitle)}&prop=text&format=json&redirects=true`;
  const imageUrl = `https://en.wikipedia.org/w/api.php?origin=*&action=query&titles=${encodeURIComponent(pageTitle)}&prop=pageimages&pithumbsize=400&format=json&redirects=true`;

  const [parseRes, imageRes] = await Promise.all([
    fetch(parseUrl),
    fetch(imageUrl)
  ]);

  const parseData = await parseRes.json();
  const imageData = await imageRes.json();

  if (!parseData.parse) {
      throw new Error("Could not parse page content");
  }

  const members = parseMembers(parseData.parse.text['*']);
  // Clean title: remove " (band)", " (group)", etc.
  const cleanName = pageTitle.replace(/\s\(.*?\)/, '');

  let logoUrl = '';
  try {
    const pages = imageData.query?.pages;
    if (pages) {
      const pageId = Object.keys(pages)[0];
      if (pages[pageId].thumbnail) {
        logoUrl = pages[pageId].thumbnail.source;
      }
    }
  } catch (e) {
    console.warn("Failed to extract image", e);
  }

  return { name: cleanName, members, logoUrl };
};

