/**
 * 將圖片檔案壓縮並轉換為 Base64 字串
 */
export const compressImage = (
  file: File, 
  maxWidth: number = 300, 
  quality: number = 0.8
): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;

        if (width > maxWidth) {
          height *= maxWidth / width;
          width = maxWidth;
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', quality));
        } else {
          reject(new Error("Canvas context not available"));
        }
      };
      img.onerror = (err) => reject(err);
      img.src = event.target?.result as string;
    };
    reader.onerror = (err) => reject(err);
    reader.readAsDataURL(file);
  });
};

/**
 * 正規化字串：轉小寫並移除非英數字符
 */
export const normalizeString = (s: string): string => {
  return s.toLowerCase().replace(/[^a-z0-9]/g, '');
};

/**
 * 驗證兩個字串是否具有相關性（用於防止錯誤的搜尋結果）
 * 針對維基百科標題進行優化，忽略常見的後綴
 */
export const isFuzzyMatch = (query: string, resultTitle: string): boolean => {
  const nQuery = normalizeString(query);
  const nTitle = normalizeString(resultTitle)
    .replace(/southkorean/g, '')
    .replace(/band/g, '')
    .replace(/group/g, '')
    .replace(/kpop/g, '');

  return nTitle.includes(nQuery) || nQuery.includes(nTitle);
};

import { GoogleGenAI, Type } from "@google/genai";
import { Member } from '../types';
import { isFuzzyMatch } from '../utils';

// Initialize Gemini AI
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Use Gemini AI to find Traditional Chinese names for a list of members
 */
export const enrichMembersWithAI = async (groupName: string, members: Member[]): Promise<Member[]> => {
  if (members.length === 0) return [];

  const ai = getAI();
  const memberNames = members.map(m => m.name).join(', ');

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `You are a K-pop expert. For the group "${groupName}", I have the following members: ${memberNames}. 
      Please provide their standard Traditional Chinese (繁體中文) stage names used in Taiwan/Hong Kong. 
      Return the data as a JSON array of objects.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING, description: "The original English stage name" },
              cn: { type: Type.STRING, description: "The Traditional Chinese stage name" }
            },
            required: ["name", "cn"]
          }
        }
      }
    });

    const aiResults = JSON.parse(response.text || "[]");

    // Map AI results back to members
    return members.map(m => {
      const match = aiResults.find((r: any) => 
        r.name.toLowerCase() === m.name.toLowerCase() || 
        m.name.toLowerCase().includes(r.name.toLowerCase())
      );
      return {
        ...m,
        cn: match ? match.cn : m.cn
      };
    });
  } catch (error) {
    console.error("AI Enrichment failed:", error);
    return members; // Return original if AI fails
  }
};

