        <div className="flex items-center gap-2.5 cursor-pointer group" onClick={scrollToTop}>
          <div className="bg-gradient-to-br from-violet-500 to-fuchsia-500 text-white p-1.5 rounded-lg shadow-md shadow-violet-200 group-hover:scale-105 transition-transform">
            <BookHeart className="w-5 h-5" />
          </div>
          <div className="flex items-center gap-2">
            <h1 className="text-xl font-bold text-slate-800 tracking-tight group-hover:text-violet-700 transition-colors">追星歷程記錄</h1>
            {myGroups.length > 0 && (
              <span className="text-xs font-bold text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full border border-slate-200">
                {myGroups.length}
