            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button 
            onClick={() => setIsDashboardOpen(true)}
            className="p-2 text-slate-500 bg-slate-100/80 hover:bg-slate-100 rounded-full active:bg-slate-200 transition"
            title="數據儀表板"
          >
            <BarChart3 className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setIsTimelineOpen(true)}
            className="p-2 text-slate-500 bg-slate-100/80 hover:bg-slate-100 rounded-full active:bg-slate-200 transition"
            title="追星時間軸"
          >
            <History className="w-5 h-5" />
          </button>
          <button onClick={() => setIsDataModalOpen(true)} className="p-2 text-slate-500 bg-slate-100/80 hover:bg-slate-100 rounded-full active:bg-slate-200 transition">
            <Database className="w-5 h-5" />
          </button>
          <button 
