      const newGroup: Group = {
        id: Date.now().toString(),
        name: preset.n,
        stanDate: '',
        isExpanded: true,
        members: preset.m ? preset.m.map(m => ({ name: m[0], cn: m[1] || '', rank: 0 })) : [],
