                ${isExporting ? 'bg-slate-100 text-slate-400' : 'bg-violet-600 text-white hover:bg-violet-700 shadow-violet-200'}
                disabled:opacity-50
            `}
          >
            {isExporting ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Download className="w-3.5 h-3.5" />}
            {isExporting ? '生成中' : '匯出評比圖'}
