                      ))}
                    </tr>
                  </tbody>
                </table>

                {/* Footer for Exported Image */}
                <div className="hidden block-for-export mt-8 pt-4 border-t border-slate-200 text-center">
                    <p className="text-[9px] text-slate-300 font-black uppercase tracking-[0.2em] italic opacity-60">
                        * Colors reflect rank within category. Generated via K-pop Stan Binder.
