這是一個為您的「追星歷程記錄」App 量身打造的 **Google Apps Script (GAS)** 完整程式碼。

### 如何使用此程式碼：
1. 建立一個新的 **Google 試算表**。
2. 點擊選單的 **「延伸功能」 > 「Apps Script」**。
3. 刪除原本的 `myFunction`，將下方的程式碼完整貼上。
4. 點擊 **「部署」 > 「新部署」**。
5. 類型選擇 **「網頁應用程式」**，並將「誰可以存取」設為 **「所有人」**（這很重要，否則 App 無法存取）。
6. 部署後，您會得到一個 **「網頁應用程式網址」**，這就是您的 API Endpoint。

```javascript
/**
 * 追星歷程記錄 - Google Sheets API 橋樑
 * 支援 4 張工作表同步：Groups, Members, Timeline, Details_Ratings
 */

const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();

// 初始化工作表（第一次執行時會自動建立）
function setup() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = {
    "Groups": ["id", "name", "logoUrl", "stanDate", "unstanDate", "isExpanded", "sortOrder"],
    "Members": ["group_id", "name", "cn", "rank"],
    "Timeline": ["group_id", "date", "type", "note"],
    "Details_Ratings": ["group_id", "reason", "visual", "favShip", "leastShip", "favSubUnit", "topSong", "rating_songs", "rating_stage", "rating_variety", "rating_visual"]
  };

  for (let name in sheets) {
    let sheet = ss.getSheetByName(name);
    if (!sheet) {
      sheet = ss.insertSheet(name);
      sheet.getRange(1, 1, 1, sheets[name].length).setValues([sheets[name]]).setFontWeight("bold");
      sheet.setFrozenRows(1);
    }
  }
}

/**
 * 接收 App 傳來的同步請求 (POST)
 */
function doPost(e) {
  setup();
  const lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    const data = JSON.parse(e.postData.contents); // 預期接收 [Group, Group, ...] 陣列

    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const sheetGroups = ss.getSheetByName("Groups");
    const sheetMembers = ss.getSheetByName("Members");
    const sheetTimeline = ss.getSheetByName("Timeline");
    const sheetDetails = ss.getSheetByName("Details_Ratings");

    // 清除舊資料（保留標題）
    sheetGroups.getRange(2, 1, sheetGroups.getLastRow() + 1, 7).clearContent();
    if(sheetMembers.getLastRow() > 1) sheetMembers.getRange(2, 1, sheetMembers.getLastRow(), 4).clearContent();
    if(sheetTimeline.getLastRow() > 1) sheetTimeline.getRange(2, 1, sheetTimeline.getLastRow(), 4).clearContent();
    if(sheetDetails.getLastRow() > 1) sheetDetails.getRange(2, 1, sheetDetails.getLastRow(), 11).clearContent();

    let groupsRows = [];
    let membersRows = [];
    let timelineRows = [];
    let detailsRows = [];

    data.forEach((g, index) => {
      // 1. Groups
      groupsRows.push([g.id, g.name, g.logoUrl || "", g.stanDate || "", g.unstanDate || "", g.isExpanded, index]);

      // 2. Members
      if (g.members) {
        g.members.forEach(m => {
          membersRows.push([g.id, m.name, m.cn || "", m.rank || 0]);
        });
      }

      // 3. Timeline
      if (g.timeline) {
        g.timeline.forEach(t => {
          timelineRows.push([g.id, t.date, t.type, t.note || ""]);
        });
      }

      // 4. Details & Ratings
      const d = g.details || {};
      const r = g.ratings || { songs: 0, stage: 0, variety: 0, visual: 0 };
      detailsRows.push([
        g.id, d.reason || "", d.visual || "", d.favShip || "", d.leastShip || "", 
        d.favSubUnit || "", d.topSong || "", 
        r.songs, r.stage, r.variety, r.visual
      ]);
    });

    // 寫入新資料
    if (groupsRows.length > 0) sheetGroups.getRange(2, 1, groupsRows.length, 7).setValues(groupsRows);
    if (membersRows.length > 0) sheetMembers.getRange(2, 1, membersRows.length, 4).setValues(membersRows);
    if (timelineRows.length > 0) sheetTimeline.getRange(2, 1, timelineRows.length, 4).setValues(timelineRows);
    if (detailsRows.length > 0) sheetDetails.getRange(2, 1, detailsRows.length, 11).setValues(detailsRows);

    return ContentService.createTextOutput(JSON.stringify({ "result": "success", "count": data.length }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ "result": "error", "message": err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

/**
 * 讓 App 抓取資料 (GET)
 */
function doGet() {
  setup();
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // 抓取所有表資料並轉換為物件格式
  const groups = getSheetDataAsObjects(ss.getSheetByName("Groups"));
  const members = getSheetDataAsObjects(ss.getSheetByName("Members"));
  const timeline = getSheetDataAsObjects(ss.getSheetByName("Timeline"));
  const details = getSheetDataAsObjects(ss.getSheetByName("Details_Ratings"));

  // 重新組裝成 App 需要的 JSON 結構
  const result = groups.sort((a, b) => a.sortOrder - b.sortOrder).map(g => {
    return {
      id: String(g.id),
      name: g.name,
      logoUrl: g.logoUrl,
      stanDate: g.stanDate,
      unstanDate: g.unstanDate || undefined,
      isExpanded: g.isExpanded === true || g.isExpanded === "true",
      members: members.filter(m => String(m.group_id) === String(g.id)).map(m => ({
        name: m.name, cn: m.cn, rank: Number(m.rank)
      })),
      timeline: timeline.filter(t => String(t.group_id) === String(g.id)).map(t => ({
        date: t.date, type: t.type, note: t.note
      })),
      details: details.find(d => String(d.group_id) === String(g.id)) || {},
      ratings: (function() {
        const r = details.find(d => String(d.group_id) === String(g.id));
        return r ? {
          songs: Number(r.rating_songs),
          stage: Number(r.rating_stage),
          variety: Number(r.rating_variety),
          visual: Number(r.rating_visual)
        } : undefined;
      })()
    };
  });

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

// 輔助函式：將工作表內容轉為 JSON 物件陣列
function getSheetDataAsObjects(sheet) {
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const rows = data.slice(1);
  return rows.map(row => {
    let obj = {};
    headers.forEach((header, i) => obj[header] = row[i]);
    return obj;
  });
}
```

