import React, { useState, useEffect } from 'react';
import { Copy, Download, AlertCircle, Cloud, CloudUpload, CloudDownload, Link, Loader2, CheckCircle2 } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group } from '../types';

interface DataModalProps {
  isOpen: boolean;
  onClose: () => void;
  data: Group[];
  onImport: (data: Group[]) => void;
  onReset: () => void;
}

export const DataModal: React.FC<DataModalProps> = ({ isOpen, onClose, data, onImport, onReset }) => {
  const [activeTab, setActiveTab] = useState<'export' | 'import' | 'cloud'>('export');
  const [importStr, setImportStr] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [gasUrl, setGasUrl] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const exportStr = JSON.stringify(data);

  // 讀取存儲的 GAS URL
  useEffect(() => {
    const savedUrl = localStorage.getItem('stan-binder-gas-url');
    if (savedUrl) setGasUrl(savedUrl);
  }, []);

  const handleCopy = () => {
    navigator.clipboard.writeText(exportStr).then(() => {
        alert("已複製到剪貼簿！");
    });
  };

  const handleImport = () => {
    setErrorMsg('');
    try {
      if (!importStr.trim()) throw new Error("內容為空");
      const parsed = JSON.parse(importStr);
      if (!Array.isArray(parsed)) throw new Error("資料格式錯誤 (須為陣列)");
      onImport(parsed as Group[]);
      onClose();
      setImportStr('');
    } catch (e: any) {
      setErrorMsg(e.message || "匯入失敗");
    }
  };

  const handleCloudAction = async (type: 'upload' | 'download') => {
    if (!gasUrl.startsWith('https://script.google.com')) {
      setErrorMsg('無效的 GAS 網址');
      return;
    }

    setErrorMsg('');
    setIsSyncing(true);
    setSyncStatus('idle');
    localStorage.setItem('stan-binder-gas-url', gasUrl);

    try {
      if (type === 'upload') {
        const response = await fetch(gasUrl, {
          method: 'POST',
          mode: 'no-cors', // GAS Web App POST usually requires no-cors for simple requests
          body: JSON.stringify(data),
          headers: { 'Content-Type': 'application/json' }
        });
        // Since no-cors doesn't allow reading response, we assume success if no error thrown
        setSyncStatus('success');
        setTimeout(() => setSyncStatus('idle'), 3000);
      } else {
        const response = await fetch(gasUrl);
        const cloudData = await response.json();
        if (Array.isArray(cloudData)) {
          onImport(cloudData);
          setSyncStatus('success');
          setTimeout(() => setSyncStatus('idle'), 3000);
        } else {
          throw new Error('雲端資料格式不正確');
        }
      }
    } catch (e: any) {
      setErrorMsg(e.message || "同步失敗，請檢查網址與權限");
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="資料管理">
      <div className="flex border-b border-slate-100">
        {[
          { id: 'export', label: '匯出', icon: Copy },
          { id: 'import', label: '匯入', icon: Download },
          { id: 'cloud', label: '雲端同步', icon: Cloud }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)} 
            className={`flex-1 py-4 font-bold text-xs flex flex-col items-center gap-1 transition ${activeTab === tab.id ? 'text-violet-600 border-b-2 border-violet-600' : 'text-slate-400 hover:text-slate-600'}`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="p-5 flex-1 overflow-y-auto bg-slate-50 min-h-[350px]">
        {activeTab === 'export' && (
          <div className="space-y-4 animate-pop-in">
            <p className="text-sm text-slate-600">複製代碼以進行手動備份：</p>
            <div className="relative">
              <textarea 
                readOnly 
                className="w-full h-48 p-3 text-xs font-mono bg-white border border-slate-200 rounded-xl focus:outline-none resize-none text-slate-500 break-all shadow-inner" 
                value={exportStr}
              />
              <button 
                onClick={handleCopy} 
                className="absolute bottom-3 right-3 bg-slate-800 text-white text-xs px-4 py-2 rounded-xl flex items-center gap-2 active:scale-95 transition hover:bg-slate-900 shadow-lg"
              >
                <Copy className="w-3.5 h-3.5" /> 一鍵複製
              </button>
            </div>
            <div className="text-center">
              <button onClick={onReset} className="text-[10px] font-black text-rose-400 uppercase tracking-widest hover:text-rose-600 transition">危險區域：重置所有資料</button>
            </div>
          </div>
        )}

        {activeTab === 'import' && (
          <div className="space-y-4 animate-pop-in">
            <p className="text-sm text-slate-600">貼上先前備份的 JSON 代碼：</p>
            <textarea 
              value={importStr}
              onChange={(e) => setImportStr(e.target.value)}
              className="w-full h-48 p-3 text-xs font-mono bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-violet-500 outline-none resize-none placeholder-slate-300 shadow-inner" 
              placeholder='[{"id":"...", "name":"..."}]'
            />
            {errorMsg && <p className="text-xs text-rose-500 flex items-center gap-1 font-bold animate-shake"><AlertCircle className="w-3 h-3" /> {errorMsg}</p>}
            <button 
              onClick={handleImport} 
              className="w-full bg-violet-600 text-white py-4 rounded-xl font-bold active:scale-95 transition flex items-center justify-center gap-2 shadow-xl shadow-violet-200"
            >
              <Download className="w-5 h-5" /> 覆蓋並匯入資料
            </button>
          </div>
        )}

        {activeTab === 'cloud' && (
          <div className="space-y-5 animate-pop-in">
            <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm space-y-3">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                <Link className="w-3.5 h-3.5" /> GAS API URL
              </label>
              <input 
                type="text" 
                value={gasUrl}
                onChange={(e) => setGasUrl(e.target.value)}
                placeholder="貼上您的 Google Apps Script 部署網址"
                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-mono focus:border-violet-400 focus:ring-4 focus:ring-violet-100 outline-none transition-all"
              />
              <p className="text-[10px] text-slate-400 leading-relaxed">
                * 請將 Google Sheets 的 Apps Script 部署為「網頁應用程式」，並設定存取權限為「所有人」。
              </p>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => handleCloudAction('upload')}
                disabled={isSyncing || !gasUrl}
                className="flex flex-col items-center justify-center gap-2 p-4 bg-white border border-slate-200 rounded-2xl hover:border-violet-300 hover:bg-violet-50 transition active:scale-95 disabled:opacity-50"
              >
                <CloudUpload className={`w-8 h-8 ${isSyncing ? 'text-slate-300' : 'text-violet-500'}`} />
                <span className="text-xs font-bold text-slate-600">備份到雲端</span>
              </button>
              <button 
                onClick={() => handleCloudAction('download')}
                disabled={isSyncing || !gasUrl}
                className="flex flex-col items-center justify-center gap-2 p-4 bg-white border border-slate-200 rounded-2xl hover:border-violet-300 hover:bg-violet-50 transition active:scale-95 disabled:opacity-50"
              >
                <CloudDownload className={`w-8 h-8 ${isSyncing ? 'text-slate-300' : 'text-emerald-500'}`} />
                <span className="text-xs font-bold text-slate-600">從雲端還原</span>
              </button>
            </div>

            {isSyncing && (
              <div className="flex items-center justify-center gap-2 text-violet-500 animate-pulse">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span className="text-xs font-bold">雲端同步中...</span>
              </div>
            )}

            {syncStatus === 'success' && (
              <div className="flex items-center justify-center gap-2 text-emerald-500 bg-emerald-50 py-2 rounded-xl border border-emerald-100 animate-pop-in">
                <CheckCircle2 className="w-4 h-4" />
                <span className="text-xs font-bold">同步成功！</span>
              </div>
            )}

            {errorMsg && (
              <div className="p-3 bg-rose-50 border border-rose-100 rounded-xl flex items-start gap-2 text-rose-600 animate-shake">
                <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
                <span className="text-[11px] font-bold leading-tight">{errorMsg}</span>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="p-3 border-t border-slate-100 bg-white rounded-b-2xl">
        <button onClick={onClose} className="w-full py-2 text-slate-400 text-sm font-bold hover:text-slate-600">關閉視窗</button>
      </div>
    </Modal>
  );
};

