import { useState, useEffect, useCallback } from 'react';
import { BookHeart, Database, LayoutGrid, List, Plus, X, Loader2, HelpCircle, Layers, CheckCircle, AlertTriangle, History, BarChart3, Sparkles, Trophy, Heart } from 'lucide-react';
import { Group, Member, GroupDetails, ToastType, TimelineEvent, GroupRatings } from './types';
import { PRESET_DB } from './constants';
import { fetchFromWikiAuto, fetchGroupLogo } from './services/wikiService';
import { GroupCard } from './components/GroupCard';
import { EditGroupModal } from './components/EditGroupModal';
import { GroupDetailsModal } from './components/GroupDetailsModal';
import { DataModal } from './components/DataModal';
import { TimelineModal } from './components/TimelineModal';
import { DashboardModal } from './components/DashboardModal';
import { RatingModal } from './components/RatingModal';
import { BiasListModal } from './components/BiasListModal';
import { Modal } from './components/ui/Modal';
import { normalizeString } from './utils';

interface AlertConfig {
  title: string;
  msg: string;
  action?: () => void;
  actionLabel?: string;
}

export default function App() {
  // --- State ---
  const [myGroups, setMyGroups] = useState<Group[]>([]);
  const [inputQuery, setInputQuery] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isInputError, setIsInputError] = useState(false);
  const [viewMode, setViewMode] = useState<'card' | 'list'>('card');

  // Modals
  const [editingGroup, setEditingGroup] = useState<Group | null>(null);
  const [detailsModalGroup, setDetailsModalGroup] = useState<Group | null>(null);
  const [isDataModalOpen, setIsDataModalOpen] = useState(false);
  const [isTimelineOpen, setIsTimelineOpen] = useState(false);
  const [isDashboardOpen, setIsDashboardOpen] = useState(false);
  const [isRatingModalOpen, setIsRatingModalOpen] = useState(false);
  const [isBiasListOpen, setIsBiasListOpen] = useState(false);
  const [deleteConfirmGroup, setDeleteConfirmGroup] = useState<Group | null>(null);
  const [alertConfig, setAlertConfig] = useState<AlertConfig | null>(null);

  // Toast
  const [toast, setToast] = useState<{ msg: string; type: ToastType } | null>(null);

  // Helper to get current YYYY-MM
  const getCurrentMonth = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  };

  // --- Effects ---
  useEffect(() => {
    const saved = localStorage.getItem('stan-binder-v7-react');
    if (saved) {
      try {
        setMyGroups(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load data", e);
      }
    }
  }, []);

  useEffect(() => {
    if (myGroups.length > 0 || localStorage.getItem('stan-binder-v7-react')) {
      localStorage.setItem('stan-binder-v7-react', JSON.stringify(myGroups));
    }
  }, [myGroups]);

  // --- Handlers ---

  const showToast = (msg: string, type: ToastType = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const resetError = () => setIsInputError(false);

  const handleForceAdd = useCallback(() => {
    if (!inputQuery.trim()) return;
    const groupName = inputQuery.trim();
    const now = getCurrentMonth();

    const newGroup: Group = {
      id: Date.now().toString(),
      name: groupName,
      stanDate: now,
      isExpanded: true,
      members: [],
      timeline: [{ date: now, type: 'stan' }]
    };
    setMyGroups(prev => [newGroup, ...prev]);
    setEditingGroup(newGroup);
    setInputQuery('');
    resetError();

    fetchGroupLogo(groupName).then(url => {
      if (url) {
        setMyGroups(prev => prev.map(g => 
          g.id === newGroup.id ? { ...g, logoUrl: url } : g
        ));
      }
    });
  }, [inputQuery]);

  const handleSmartAdd = async () => {
    const rawInput = inputQuery.trim();
    if (!rawInput) return;

    setIsLoading(true);
    resetError();

    const key = normalizeString(rawInput);
    const now = getCurrentMonth();

    let preset = PRESET_DB[key];
    if (preset) {
      if (preset.ref && PRESET_DB[preset.ref]) {
        preset = PRESET_DB[preset.ref];
      }

      if (!preset.n) {
         showToast(`${key} 設定錯誤`, 'error');
         setIsLoading(false);
         return;
      }

      if (myGroups.find(g => g.name === preset.n)) {
        showToast(`${preset.n} 已存在`, 'error');
        setIsLoading(false);
        return;
      }

      const newGroup: Group = {
        id: Date.now().toString(),
        name: preset.n,
        stanDate: now,
        isExpanded: true,
        members: preset.m ? preset.m.map(m => ({ name: m[0], cn: m[1] || '', rank: 0 })) : [],
        logoUrl: preset.l,
        timeline: [{ date: now, type: 'stan' }]
      };

      setMyGroups(prev => [newGroup, ...prev]);
      showToast(`已新增 ${newGroup.name}`);
      setInputQuery('');
      setIsLoading(false);

      if (!newGroup.logoUrl) {
        fetchGroupLogo(newGroup.name).then(url => {
          if (url) {
            setMyGroups(prev => prev.map(g => 
              g.id === newGroup.id ? { ...g, logoUrl: url } : g
            ));
          }
        });
      }

      return;
    }

    try {
      const data = await fetchFromWikiAuto(rawInput);
      if (myGroups.find(g => g.name === data.name)) {
        showToast(`${data.name} 已存在`, 'error');
      } else {
        if (data.members.length === 0) {
          setAlertConfig({
            title: "無法抓取成員",
            msg: `找到 "${data.name}" 但無法自動抓取成員名單。\n\n您可以選擇手動新增此團體並自行編輯成員。`,
            action: handleForceAdd,
            actionLabel: "手動新增"
          });
        } else {
          const newGroup: Group = {
            id: Date.now().toString(),
            name: data.name,
            stanDate: now,
            isExpanded: true,
            members: data.members,
            logoUrl: data.logoUrl,
            timeline: [{ date: now, type: 'stan' }]
          };
          setMyGroups(prev => [newGroup, ...prev]);
          showToast(`已新增 ${data.name} 並透過 AI 優化中文名稱`);
          setInputQuery('');
        }
      }
    } catch (e) {
      setIsInputError(true);
      setAlertConfig({
        title: "找不到團體",
        msg: `找不到 "${rawInput}"。\n請確認拼字，或者直接手動建立此團體。`,
        action: handleForceAdd,
        actionLabel: `手動新增 "${rawInput}"`
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggleExpand = useCallback((id: string) => {
    setMyGroups(prev => prev.map(g => g.id === id ? { ...g, isExpanded: !g.isExpanded } : g));
  }, []);

  const handleMove = useCallback((index: number, dir: number) => {
    setMyGroups(prev => {
      const newGroups = [...prev];
      const targetIndex = index + dir;
      if (targetIndex >= 0 && targetIndex < newGroups.length) {
        [newGroups[index], newGroups[targetIndex]] = [newGroups[targetIndex], newGroups[index]];
        return newGroups;
      }
      return prev;
    });
  }, []);

  const handleToggleRank = useCallback((groupId: string, member: Member) => {
    setMyGroups(prev => prev.map(g => {
      if (g.id !== groupId) return g;
      return {
        ...g,
        members: g.members.map(m => 
          m.name === member.name ? { ...m, rank: (m.rank + 1) % 3 } : m
        )
      };
    }));
  }, []);

  const handleRemoveGroupClick = useCallback((group: Group) => {
    setDeleteConfirmGroup(group);
  }, []);

  const handleEditClick = useCallback((group: Group) => {
    setEditingGroup(group);
  }, []);

  const handleDetailsClick = useCallback((group: Group) => {
    setDetailsModalGroup(group);
  }, []);

  const performDeleteGroup = () => {
    if (deleteConfirmGroup) {
      setMyGroups(prev => prev.filter(g => g.id !== deleteConfirmGroup.id));
      showToast("團體已移除");
      setDeleteConfirmGroup(null);
    }
  };

  const handleSaveEdit = (groupId: string, members: Member[], logoUrl: string, timeline: TimelineEvent[]) => {
    setMyGroups(prev => {
        const earliestStan = timeline
            .filter(e => e.type === 'stan')
            .sort((a, b) => a.date.localeCompare(b.date))[0]?.date || '';

        const sortedEvents = [...timeline].sort((a, b) => b.date.localeCompare(a.date));
        const latestEvent = sortedEvents[0];
        const derivedUnstanDate = (latestEvent && latestEvent.type === 'unstan') ? latestEvent.date : undefined;

        const updatedGroups = prev.map(g => g.id === groupId ? { 
            ...g, 
            members, 
            logoUrl, 
            timeline,
            stanDate: earliestStan || g.stanDate,
            unstanDate: derivedUnstanDate
        } : g);

        return updatedGroups.sort((a, b) => {
            const aUnstan = !!a.unstanDate;
            const bUnstan = !!b.unstanDate;
            if (aUnstan === bUnstan) return 0;
            return aUnstan ? 1 : -1;
        });
    });
    showToast("團體已更新");
  };

  const handleSaveDetails = (groupId: string, details: GroupDetails) => {
    setMyGroups(prev => prev.map(g => g.id === groupId ? { ...g, details } : g));
    showToast("詳細筆記已儲存");
  };

  const handleUpdateRatings = (groupId: string, ratings: GroupRatings) => {
    setMyGroups(prev => prev.map(g => g.id === groupId ? { ...g, ratings } : g));
  };

  const handleImport = (data: Group[]) => {
    setMyGroups(data);
    showToast(`成功匯入 ${data.length} 個團體`);
  };

  const handleReset = () => {
    if (window.confirm("恢復原廠設定：清除所有資料？")) {
      setMyGroups([]);
      localStorage.removeItem('stan-binder-v7-react');
      showToast("所有資料已清除");
      setIsDataModalOpen(false);
    }
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: 'smooth' });

  return (
    <div className="max-w-md mx-auto bg-slate-50 min-h-screen shadow-2xl relative overflow-hidden flex flex-col">
      <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-3 py-3 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-2 cursor-pointer group shrink-0" onClick={scrollToTop}>
          <div className="bg-gradient-to-br from-violet-500 to-fuchsia-500 text-white p-1.5 rounded-lg shadow-md shadow-violet-200 group-hover:scale-105 transition-transform">
            <BookHeart className="w-5 h-5" />
          </div>
          <div className="flex items-center gap-1.5 overflow-hidden">
            <h1 className="text-lg font-bold text-slate-800 tracking-tight group-hover:text-violet-700 transition-colors whitespace-nowrap">追星歷程</h1>
            {myGroups.length > 0 && (
              <span className="text-[10px] font-bold text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded-full border border-slate-200 shrink-0">
                {myGroups.length}
              </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-1">
          <button 
            onClick={() => setIsBiasListOpen(true)}
            className="p-2 text-rose-500 hover:bg-rose-50 rounded-full active:bg-rose-100 transition"
            title="本命清單"
          >
            <Heart className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setIsRatingModalOpen(true)}
            className="p-2 text-amber-500 hover:bg-amber-50 rounded-full active:bg-amber-100 transition"
            title="戰力評比"
          >
            <Trophy className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setIsDashboardOpen(true)}
            className="p-2 text-slate-500 hover:bg-slate-100 rounded-full active:bg-slate-200 transition"
            title="數據統計"
          >
            <BarChart3 className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setIsTimelineOpen(true)}
            className="p-2 text-slate-500 hover:bg-slate-100 rounded-full active:bg-slate-200 transition"
            title="時間軸"
          >
            <History className="w-5 h-5" />
          </button>
          <button onClick={() => setIsDataModalOpen(true)} className="p-2 text-slate-500 hover:bg-slate-100 rounded-full active:bg-slate-200 transition" title="資料管理">
            <Database className="w-5 h-5" />
          </button>
        </div>
      </header>

      <div className="bg-white p-3 border-b border-slate-100 sticky top-[57px] z-20 shadow-sm transition-all">
        <div className="relative flex items-center gap-2">
          <div className="relative flex-1">
            <input 
              value={inputQuery}
              onChange={(e) => { setInputQuery(e.target.value); resetError(); }}
              onKeyDown={(e) => e.key === 'Enter' && handleSmartAdd()}
              type="text" 
              placeholder="輸入團名 (如: 82MAJOR)" 
              disabled={isLoading}
              className={`
                w-full pl-4 pr-10 py-3 bg-slate-50 border-2 rounded-2xl outline-none text-base font-medium transition-all
                placeholder-slate-400
                ${isInputError ? 'border-red-300 bg-red-50 animate-shake' : 'border-slate-100 focus:border-violet-300 focus:ring-4 focus:ring-violet-100 focus:bg-white'}
              `}
            />
            {inputQuery && !isLoading && (
              <button onClick={() => { setInputQuery(''); resetError(); }} className="absolute right-3 top-3.5 text-slate-400 hover:text-slate-600">
                <X className="w-4 h-4" />
              </button>
            )}
            {isLoading && (
               <div className="absolute right-3 top-3.5 text-violet-500">
                  <Loader2 className="w-4 h-4 animate-spin" />
               </div>
            )}
          </div>

          <button 
            onClick={() => setViewMode(v => v === 'card' ? 'list' : 'card')} 
            className="p-3 text-slate-500 bg-slate-50 border border-slate-100 rounded-2xl active:bg-slate-100 transition shadow-sm shrink-0"
            title={viewMode === 'card' ? "切換至列表" : "切換至卡片"}
          >
            {viewMode === 'card' ? <List className="w-5 h-5" /> : <LayoutGrid className="w-5 h-5" />}
          </button>

          <button 
            onClick={handleSmartAdd}
            disabled={isLoading || !inputQuery}
            className={`
              text-white p-3 rounded-2xl shadow-lg active:scale-95 transition flex items-center justify-center min-w-[50px]
              ${isInputError ? 'bg-rose-500 shadow-rose-200' : 'bg-violet-600 shadow-violet-200 hover:bg-violet-700'}
              ${(isLoading || !inputQuery) ? 'opacity-50 scale-100 shadow-none' : ''}
            `}
          >
            {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Plus className="w-6 h-6" />}
          </button>
        </div>

        {isLoading ? (
          <div className="mt-2 text-center flex items-center justify-center gap-2 text-violet-500 animate-pulse">
            <Sparkles className="w-3.5 h-3.5" />
            <span className="text-xs font-bold">AI 正在搜尋與辨識成員...</span>
          </div>
        ) : isInputError ? (
          <div className="mt-2 text-center">
            <button onClick={handleForceAdd} className="text-xs text-violet-500 font-bold hover:underline flex items-center justify-center gap-1 mx-auto">
              <HelpCircle className="w-3 h-3" /> 找不到？手動新增 "{inputQuery}"
            </button>
          </div>
        ) : null}
      </div>

      <main className={`p-4 flex-1 overflow-y-auto ${viewMode === 'list' ? 'grid grid-cols-2 gap-3 items-stretch' : 'space-y-4'}`}>
        {myGroups.length === 0 && (
          <div className={`flex flex-col items-center justify-center py-12 text-center px-6 opacity-60 ${viewMode === 'list' ? 'col-span-2' : ''}`}>
            <div className="w-16 h-16 bg-slate-100 text-slate-300 rounded-full flex items-center justify-center mb-4">
              <Layers className="w-8 h-8" />
            </div>
            <p className="text-slate-400 font-medium leading-relaxed">尚無團體。<br/>試試輸入 "82MAJOR" 或 "8TURN"</p>
            <div className="mt-5">
              <button onClick={() => setIsDataModalOpen(true)} className="text-violet-500 text-sm font-bold hover:text-violet-600 transition-colors">已有備份？點此匯入</button>
            </div>
          </div>
        )}

        {myGroups.map((group, index) => (
          <div key={group.id} className={viewMode === 'list' ? 'col-span-1 h-full' : ''}>
             <GroupCard 
               group={group}
               isFirst={index === 0}
               isLast={index === myGroups.length - 1}
               onMove={(dir) => handleMove(index, dir)}
               onEdit={() => handleEditClick(group)}
               onDetails={() => handleDetailsClick(group)}
               onToggleExpand={() => handleToggleExpand(group.id)}
               onToggleRank={(m) => handleToggleRank(group.id, m)}
               onRemove={() => handleRemoveGroupClick(group)}
             />
          </div>
        ))}
      </main>

      <EditGroupModal 
        isOpen={!!editingGroup} 
        onClose={() => setEditingGroup(null)} 
        group={editingGroup} 
        onSave={handleSaveEdit} 
      />

      <GroupDetailsModal
        isOpen={!!detailsModalGroup}
        onClose={() => setDetailsModalGroup(null)}
        group={detailsModalGroup}
        onSave={handleSaveDetails}
      />

      <TimelineModal 
        isOpen={isTimelineOpen}
        onClose={() => setIsTimelineOpen(false)}
        groups={myGroups}
      />

      <DashboardModal 
        isOpen={isDashboardOpen} 
        onClose={() => setIsDashboardOpen(false)} 
        groups={myGroups} 
      />

      <RatingModal
        isOpen={isRatingModalOpen}
        onClose={() => setIsRatingModalOpen(false)}
        groups={myGroups}
        onUpdateRatings={handleUpdateRatings}
      />

      <BiasListModal
        isOpen={isBiasListOpen}
        onClose={() => setIsBiasListOpen(false)}
        groups={myGroups}
      />

      <DataModal 
        isOpen={isDataModalOpen} 
        onClose={() => setIsDataModalOpen(false)} 
        data={myGroups} 
        onImport={handleImport} 
        onReset={handleReset} 
      />

      <Modal 
        isOpen={!!deleteConfirmGroup} 
        onClose={() => setDeleteConfirmGroup(null)} 
        title="確認移除"
      >
        <div className="p-4">
          <p className="text-slate-600 mb-6">
            確定要移除 <span className="font-bold text-slate-800">{deleteConfirmGroup?.name}</span> 嗎？此動作無法復原。
          </p>
          <div className="flex gap-3">
              <button 
                onClick={() => setDeleteConfirmGroup(null)} 
                className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold active:scale-95 transition hover:bg-slate-200"
              >
                取消
              </button>
              <button 
                onClick={performDeleteGroup} 
                className="flex-1 py-3 bg-rose-500 text-white rounded-xl font-bold shadow-lg shadow-rose-200 active:scale-95 transition hover:bg-rose-600"
              >
                確認移除
              </button>
          </div>
        </div>
      </Modal>

      <Modal 
        isOpen={!!alertConfig} 
        onClose={() => setAlertConfig(null)} 
        title={alertConfig?.title || '提示'}
      >
         <div className="p-4">
           <div className="flex flex-col items-center text-center gap-3">
              <div className="w-12 h-12 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center">
                  <AlertTriangle className="w-6 h-6" />
              </div>
              <p className="text-slate-700 font-medium whitespace-pre-wrap">{alertConfig?.msg}</p>
           </div>

           {alertConfig?.action ? (
             <div className="flex gap-3 mt-6">
                <button 
                  onClick={() => setAlertConfig(null)} 
                  className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold active:scale-95 transition hover:bg-slate-200"
                >
                  取消
                </button>
                <button 
                  onClick={() => {
                    alertConfig.action?.();
                    setAlertConfig(null);
                  }}
                  className="flex-1 py-3 bg-violet-600 text-white rounded-xl font-bold shadow-lg shadow-violet-200 active:scale-95 transition hover:bg-violet-700"
                >
                  {alertConfig.actionLabel || '確定'}
                </button>
             </div>
           ) : (
             <button 
               onClick={() => setAlertConfig(null)} 
               className="w-full mt-6 py-3 bg-slate-800 text-white rounded-xl font-bold active:scale-95 transition hover:bg-slate-900"
             >
               我知道了
             </button>
           )}
         </div>
      </Modal>

      {toast && (
        <div className={`
          fixed bottom-6 left-1/2 transform -translate-x-1/2 px-4 py-2.5 rounded-full text-xs font-bold shadow-xl shadow-slate-300/50
          transition-all duration-300 flex items-center gap-2 pointer-events-none z-[110]
          animate-pop-in border border-white/20 backdrop-blur-md
          ${toast.type === 'error' ? 'bg-rose-500 text-white' : 'bg-slate-800 text-white'}
        `}>
          {toast.type === 'success' ? <CheckCircle className="w-4 h-4 text-emerald-400" /> : <AlertTriangle className="w-4 h-4 text-white" />}
          {toast.msg}
        </div>
      )}
    </div>
  );
}

/**
 * 將圖片檔案壓縮並轉換為 Base64 字串
 */
export const compressImage = (
  file: File, 
  maxWidth: number = 300, 
  quality: number = 0.8
): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;

        if (width > maxWidth) {
          height *= maxWidth / width;
          width = maxWidth;
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', quality));
        } else {
          reject(new Error("Canvas context not available"));
        }
      };
      img.onerror = (err) => reject(err);
      img.src = event.target?.result as string;
    };
    reader.onerror = (err) => reject(err);
    reader.readAsDataURL(file);
  });
};

/**
 * 正規化字串：轉小寫並移除非英數字符
 */
export const normalizeString = (s: string): string => {
  return s.toLowerCase().replace(/[^a-z0-9]/g, '');
};

/**
 * 驗證兩個字串是否具有相關性（用於防止錯誤的搜尋結果）
 * 針對維基百科標題進行優化，忽略常見的後綴
 */
export const isFuzzyMatch = (query: string, resultTitle: string): boolean => {
  const nQuery = normalizeString(query);
  const nTitle = normalizeString(resultTitle)
    .replace(/southkorean/g, '')
    .replace(/band/g, '')
    .replace(/group/g, '')
    .replace(/kpop/g, '');

  return nTitle.includes(nQuery) || nQuery.includes(nTitle);
};

/**
 * 清洗日期格式：將 ISO 格式或其他格式強制轉為 YYYY-MM
 * 例如: "2024-05-01T16:00:00.000Z" -> "2024-05"
 */
export const sanitizeDate = (dateStr: any): string => {
  if (!dateStr || typeof dateStr !== 'string') return '';
  // 取前 7 個字元 (YYYY-MM)
  const match = dateStr.match(/^(\d{4}-\d{2})/);
  return match ? match[1] : '';
};

import { useState, useEffect, useCallback } from 'react';
import { BookHeart, Database, LayoutGrid, List, Plus, X, Loader2, HelpCircle, Layers, CheckCircle, AlertTriangle, History, BarChart3, Sparkles, Trophy, Heart } from 'lucide-react';
import { Group, Member, GroupDetails, ToastType, TimelineEvent, GroupRatings } from './types';
import { PRESET_DB } from './constants';
import { fetchFromWikiAuto, fetchGroupLogo } from './services/wikiService';
import { GroupCard } from './components/GroupCard';
import { EditGroupModal } from './components/EditGroupModal';
import { GroupDetailsModal } from './components/GroupDetailsModal';
import { DataModal } from './components/DataModal';
import { TimelineModal } from './components/TimelineModal';
import { DashboardModal } from './components/DashboardModal';
import { RatingModal } from './components/RatingModal';
import { BiasListModal } from './components/BiasListModal';
import { Modal } from './components/ui/Modal';
import { normalizeString, sanitizeDate } from './utils';

interface AlertConfig {
  title: string;
  msg: string;
  action?: () => void;
  actionLabel?: string;
}

export default function App() {
  // --- State ---
  const [myGroups, setMyGroups] = useState<Group[]>([]);
  const [inputQuery, setInputQuery] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isInputError, setIsInputError] = useState(false);
  const [viewMode, setViewMode] = useState<'card' | 'list'>('card');

  // Modals
  const [editingGroup, setEditingGroup] = useState<Group | null>(null);
  const [detailsModalGroup, setDetailsModalGroup] = useState<Group | null>(null);
  const [isDataModalOpen, setIsDataModalOpen] = useState(false);
  const [isTimelineOpen, setIsTimelineOpen] = useState(false);
  const [isDashboardOpen, setIsDashboardOpen] = useState(false);
  const [isRatingModalOpen, setIsRatingModalOpen] = useState(false);
  const [isBiasListOpen, setIsBiasListOpen] = useState(false);
  const [deleteConfirmGroup, setDeleteConfirmGroup] = useState<Group | null>(null);
  const [alertConfig, setAlertConfig] = useState<AlertConfig | null>(null);

  // Toast
  const [toast, setToast] = useState<{ msg: string; type: ToastType } | null>(null);

  // Helper to get current YYYY-MM
  const getCurrentMonth = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  };

  // --- Effects ---
  useEffect(() => {
    const saved = localStorage.getItem('stan-binder-v7-react');
    if (saved) {
      try {
        setMyGroups(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load data", e);
      }
    }
  }, []);

  useEffect(() => {
    if (myGroups.length > 0 || localStorage.getItem('stan-binder-v7-react')) {
      localStorage.setItem('stan-binder-v7-react', JSON.stringify(myGroups));
    }
  }, [myGroups]);

  // --- Handlers ---

  const showToast = (msg: string, type: ToastType = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const resetError = () => setIsInputError(false);

  const handleForceAdd = useCallback(() => {
    if (!inputQuery.trim()) return;
    const groupName = inputQuery.trim();
    const now = getCurrentMonth();

    const newGroup: Group = {
      id: Date.now().toString(),
      name: groupName,
      stanDate: now,
      isExpanded: true,
      members: [],
      timeline: [{ date: now, type: 'stan' }]
    };
    setMyGroups(prev => [newGroup, ...prev]);
    setEditingGroup(newGroup);
    setInputQuery('');
    resetError();

    fetchGroupLogo(groupName).then(url => {
      if (url) {
        setMyGroups(prev => prev.map(g => 
          g.id === newGroup.id ? { ...g, logoUrl: url } : g
        ));
      }
    });
  }, [inputQuery]);

  const handleSmartAdd = async () => {
    const rawInput = inputQuery.trim();
    if (!rawInput) return;

    setIsLoading(true);
    resetError();

    const key = normalizeString(rawInput);
    const now = getCurrentMonth();

    let preset = PRESET_DB[key];
    if (preset) {
      if (preset.ref && PRESET_DB[preset.ref]) {
        preset = PRESET_DB[preset.ref];
      }

      if (!preset.n) {
         showToast(`${key} 設定錯誤`, 'error');
         setIsLoading(false);
         return;
      }

      if (myGroups.find(g => g.name === preset.n)) {
        showToast(`${preset.n} 已存在`, 'error');
        setIsLoading(false);
        return;
      }

      const newGroup: Group = {
        id: Date.now().toString(),
        name: preset.n,
        stanDate: now,
        isExpanded: true,
        members: preset.m ? preset.m.map(m => ({ name: m[0], cn: m[1] || '', rank: 0 })) : [],
        logoUrl: preset.l,
        timeline: [{ date: now, type: 'stan' }]
      };

      setMyGroups(prev => [newGroup, ...prev]);
      showToast(`已新增 ${newGroup.name}`);
      setInputQuery('');
      setIsLoading(false);

      if (!newGroup.logoUrl) {
        fetchGroupLogo(newGroup.name).then(url => {
          if (url) {
            setMyGroups(prev => prev.map(g => 
              g.id === newGroup.id ? { ...g, logoUrl: url } : g
            ));
          }
        });
      }

      return;
    }

    try {
      const data = await fetchFromWikiAuto(rawInput);
      if (myGroups.find(g => g.name === data.name)) {
        showToast(`${data.name} 已存在`, 'error');
      } else {
        if (data.members.length === 0) {
          setAlertConfig({
            title: "無法抓取成員",
            msg: `找到 "${data.name}" 但無法自動抓取成員名單。\n\n您可以選擇手動新增此團體並自行編輯成員。`,
            action: handleForceAdd,
            actionLabel: "手動新增"
          });
        } else {
          const newGroup: Group = {
            id: Date.now().toString(),
            name: data.name,
            stanDate: now,
            isExpanded: true,
            members: data.members,
            logoUrl: data.logoUrl,
            timeline: [{ date: now, type: 'stan' }]
          };
          setMyGroups(prev => [newGroup, ...prev]);
          showToast(`已新增 ${data.name} 並透過 AI 優化中文名稱`);
          setInputQuery('');
        }
      }
    } catch (e) {
      setIsInputError(true);
      setAlertConfig({
        title: "找不到團體",
        msg: `找不到 "${rawInput}"。\n請確認拼字，或者直接手動建立此團體。`,
        action: handleForceAdd,
        actionLabel: `手動新增 "${rawInput}"`
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggleExpand = useCallback((id: string) => {
    setMyGroups(prev => prev.map(g => g.id === id ? { ...g, isExpanded: !g.isExpanded } : g));
  }, []);

  const handleMove = useCallback((index: number, dir: number) => {
    setMyGroups(prev => {
      const newGroups = [...prev];
      const targetIndex = index + dir;
      if (targetIndex >= 0 && targetIndex < newGroups.length) {
        [newGroups[index], newGroups[targetIndex]] = [newGroups[targetIndex], newGroups[index]];
        return newGroups;
      }
      return prev;
    });
  }, []);

  const handleToggleRank = useCallback((groupId: string, member: Member) => {
    setMyGroups(prev => prev.map(g => {
      if (g.id !== groupId) return g;
      return {
        ...g,
        members: g.members.map(m => 
          m.name === member.name ? { ...m, rank: (m.rank + 1) % 3 } : m
        )
      };
    }));
  }, []);

  const handleRemoveGroupClick = useCallback((group: Group) => {
    setDeleteConfirmGroup(group);
  }, []);

  const handleEditClick = useCallback((group: Group) => {
    setEditingGroup(group);
  }, []);

  const handleDetailsClick = useCallback((group: Group) => {
    setDetailsModalGroup(group);
  }, []);

  const performDeleteGroup = () => {
    if (deleteConfirmGroup) {
      setMyGroups(prev => prev.filter(g => g.id !== deleteConfirmGroup.id));
      showToast("團體已移除");
      setDeleteConfirmGroup(null);
    }
  };

  const handleSaveEdit = (groupId: string, members: Member[], logoUrl: string, timeline: TimelineEvent[]) => {
    setMyGroups(prev => {
        const earliestStan = timeline
            .filter(e => e.type === 'stan')
            .sort((a, b) => a.date.localeCompare(b.date))[0]?.date || '';

        const sortedEvents = [...timeline].sort((a, b) => b.date.localeCompare(a.date));
        const latestEvent = sortedEvents[0];
        const derivedUnstanDate = (latestEvent && latestEvent.type === 'unstan') ? latestEvent.date : undefined;

        const updatedGroups = prev.map(g => g.id === groupId ? { 
            ...g, 
            members, 
            logoUrl, 
            timeline,
            stanDate: earliestStan || g.stanDate,
            unstanDate: derivedUnstanDate
        } : g);

        return updatedGroups.sort((a, b) => {
            const aUnstan = !!a.unstanDate;
            const bUnstan = !!b.unstanDate;
            if (aUnstan === bUnstan) return 0;
            return aUnstan ? 1 : -1;
        });
    });
    showToast("團體已更新");
  };

  const handleSaveDetails = (groupId: string, details: GroupDetails) => {
    setMyGroups(prev => prev.map(g => g.id === groupId ? { ...g, details } : g));
    showToast("詳細筆記已儲存");
  };

  const handleUpdateRatings = (groupId: string, ratings: GroupRatings) => {
    setMyGroups(prev => prev.map(g => g.id === groupId ? { ...g, ratings } : g));
  };

  const handleImport = (data: Group[]) => {
    // 進行資料清洗，確保所有日期格式正確
    const sanitizedData = data.map(g => ({
      ...g,
      stanDate: sanitizeDate(g.stanDate),
      unstanDate: g.unstanDate ? sanitizeDate(g.unstanDate) : undefined,
      timeline: g.timeline ? g.timeline.map(e => ({
        ...e,
        date: sanitizeDate(e.date)
      })) : []
    }));

    setMyGroups(sanitizedData);
    showToast(`成功匯入 ${sanitizedData.length} 個團體`);
  };

  const handleReset = () => {
    if (window.confirm("恢復原廠設定：清除所有資料？")) {
      setMyGroups([]);
      localStorage.removeItem('stan-binder-v7-react');
      showToast("所有資料已清除");
      setIsDataModalOpen(false);
    }
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: 'smooth' });

  return (
    <div className="max-w-md mx-auto bg-slate-50 min-h-screen shadow-2xl relative overflow-hidden flex flex-col">
      <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-3 py-3 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-2 cursor-pointer group shrink-0" onClick={scrollToTop}>
          <div className="bg-gradient-to-br from-violet-500 to-fuchsia-500 text-white p-1.5 rounded-lg shadow-md shadow-violet-200 group-hover:scale-105 transition-transform">
            <BookHeart className="w-5 h-5" />
          </div>
          <div className="flex items-center gap-1.5 overflow-hidden">
            <h1 className="text-lg font-bold text-slate-800 tracking-tight group-hover:text-violet-700 transition-colors whitespace-nowrap">追星歷程</h1>
            {myGroups.length > 0 && (
              <span className="text-[10px] font-bold text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded-full border border-slate-200 shrink-0">
                {myGroups.length}
              </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-1">
          <button 
            onClick={() => setIsBiasListOpen(true)}
            className="p-2 text-rose-500 hover:bg-rose-50 rounded-full active:bg-rose-100 transition"
            title="本命清單"
          >
            <Heart className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setIsRatingModalOpen(true)}
            className="p-2 text-amber-500 hover:bg-amber-50 rounded-full active:bg-amber-100 transition"
            title="戰力評比"
          >
            <Trophy className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setIsDashboardOpen(true)}
            className="p-2 text-slate-500 hover:bg-slate-100 rounded-full active:bg-slate-200 transition"
            title="數據統計"
          >
            <BarChart3 className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setIsTimelineOpen(true)}
            className="p-2 text-slate-500 hover:bg-slate-100 rounded-full active:bg-slate-200 transition"
            title="時間軸"
          >
            <History className="w-5 h-5" />
          </button>
          <button onClick={() => setIsDataModalOpen(true)} className="p-2 text-slate-500 hover:bg-slate-100 rounded-full active:bg-slate-200 transition" title="資料管理">
            <Database className="w-5 h-5" />
          </button>
        </div>
      </header>

      <div className="bg-white p-3 border-b border-slate-100 sticky top-[57px] z-20 shadow-sm transition-all">
        <div className="relative flex items-center gap-2">
          <div className="relative flex-1">
            <input 
              value={inputQuery}
              onChange={(e) => { setInputQuery(e.target.value); resetError(); }}
              onKeyDown={(e) => e.key === 'Enter' && handleSmartAdd()}
              type="text" 
              placeholder="輸入團名 (如: 82MAJOR)" 
              disabled={isLoading}
              className={`
                w-full pl-4 pr-10 py-3 bg-slate-50 border-2 rounded-2xl outline-none text-base font-medium transition-all
                placeholder-slate-400
                ${isInputError ? 'border-red-300 bg-red-50 animate-shake' : 'border-slate-100 focus:border-violet-300 focus:ring-4 focus:ring-violet-100 focus:bg-white'}
              `}
            />
            {inputQuery && !isLoading && (
              <button onClick={() => { setInputQuery(''); resetError(); }} className="absolute right-3 top-3.5 text-slate-400 hover:text-slate-600">
                <X className="w-4 h-4" />
              </button>
            )}
            {isLoading && (
               <div className="absolute right-3 top-3.5 text-violet-500">
                  <Loader2 className="w-4 h-4 animate-spin" />
               </div>
            )}
          </div>

          <button 
            onClick={() => setViewMode(v => v === 'card' ? 'list' : 'card')} 
            className="p-3 text-slate-500 bg-slate-50 border border-slate-100 rounded-2xl active:bg-slate-100 transition shadow-sm shrink-0"
            title={viewMode === 'card' ? "切換至列表" : "切換至卡片"}
          >
            {viewMode === 'card' ? <List className="w-5 h-5" /> : <LayoutGrid className="w-5 h-5" />}
          </button>

          <button 
            onClick={handleSmartAdd}
            disabled={isLoading || !inputQuery}
            className={`
              text-white p-3 rounded-2xl shadow-lg active:scale-95 transition flex items-center justify-center min-w-[50px]
              ${isInputError ? 'bg-rose-500 shadow-rose-200' : 'bg-violet-600 shadow-violet-200 hover:bg-violet-700'}
              ${(isLoading || !inputQuery) ? 'opacity-50 scale-100 shadow-none' : ''}
            `}
          >
            {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Plus className="w-6 h-6" />}
          </button>
        </div>

        {isLoading ? (
          <div className="mt-2 text-center flex items-center justify-center gap-2 text-violet-500 animate-pulse">
            <Sparkles className="w-3.5 h-3.5" />
            <span className="text-xs font-bold">AI 正在搜尋與辨識成員...</span>
          </div>
        ) : isInputError ? (
          <div className="mt-2 text-center">
            <button onClick={handleForceAdd} className="text-xs text-violet-500 font-bold hover:underline flex items-center justify-center gap-1 mx-auto">
              <HelpCircle className="w-3 h-3" /> 找不到？手動新增 "{inputQuery}"
            </button>
          </div>
        ) : null}
      </div>

      <main className={`p-4 flex-1 overflow-y-auto ${viewMode === 'list' ? 'grid grid-cols-2 gap-3 items-stretch' : 'space-y-4'}`}>
        {myGroups.length === 0 && (
          <div className={`flex flex-col items-center justify-center py-12 text-center px-6 opacity-60 ${viewMode === 'list' ? 'col-span-2' : ''}`}>
            <div className="w-16 h-16 bg-slate-100 text-slate-300 rounded-full flex items-center justify-center mb-4">
              <Layers className="w-8 h-8" />
            </div>
            <p className="text-slate-400 font-medium leading-relaxed">尚無團體。<br/>試試輸入 "82MAJOR" 或 "8TURN"</p>
            <div className="mt-5">
              <button onClick={() => setIsDataModalOpen(true)} className="text-violet-500 text-sm font-bold hover:text-violet-600 transition-colors">已有備份？點此匯入</button>
            </div>
          </div>
        )}

        {myGroups.map((group, index) => (
          <div key={group.id} className={viewMode === 'list' ? 'col-span-1 h-full' : ''}>
             <GroupCard 
               group={group}
               isFirst={index === 0}
               isLast={index === myGroups.length - 1}
               onMove={(dir) => handleMove(index, dir)}
               onEdit={() => handleEditClick(group)}
               onDetails={() => handleDetailsClick(group)}
               onToggleExpand={() => handleToggleExpand(group.id)}
               onToggleRank={(m) => handleToggleRank(group.id, m)}
               onRemove={() => handleRemoveGroupClick(group)}
             />
          </div>
        ))}
      </main>

      <EditGroupModal 
        isOpen={!!editingGroup} 
        onClose={() => setEditingGroup(null)} 
        group={editingGroup} 
        onSave={handleSaveEdit} 
      />

      <GroupDetailsModal
        isOpen={!!detailsModalGroup}
        onClose={() => setDetailsModalGroup(null)}
        group={detailsModalGroup}
        onSave={handleSaveDetails}
      />

      <TimelineModal 
        isOpen={isTimelineOpen}
        onClose={() => setIsTimelineOpen(false)}
        groups={myGroups}
      />

      <DashboardModal 
        isOpen={isDashboardOpen} 
        onClose={() => setIsDashboardOpen(false)} 
        groups={myGroups} 
      />

      <RatingModal
        isOpen={isRatingModalOpen}
        onClose={() => setIsRatingModalOpen(false)}
        groups={myGroups}
        onUpdateRatings={handleUpdateRatings}
      />

      <BiasListModal
        isOpen={isBiasListOpen}
        onClose={() => setIsBiasListOpen(false)}
        groups={myGroups}
      />

      <DataModal 
        isOpen={isDataModalOpen} 
        onClose={() => setIsDataModalOpen(false)} 
        data={myGroups} 
        onImport={handleImport} 
        onReset={handleReset} 
      />

      <Modal 
        isOpen={!!deleteConfirmGroup} 
        onClose={() => setDeleteConfirmGroup(null)} 
        title="確認移除"
      >
        <div className="p-4">
          <p className="text-slate-600 mb-6">
            確定要移除 <span className="font-bold text-slate-800">{deleteConfirmGroup?.name}</span> 嗎？此動作無法復原。
          </p>
          <div className="flex gap-3">
              <button 
                onClick={() => setDeleteConfirmGroup(null)} 
                className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold active:scale-95 transition hover:bg-slate-200"
              >
                取消
              </button>
              <button 
                onClick={performDeleteGroup} 
                className="flex-1 py-3 bg-rose-500 text-white rounded-xl font-bold shadow-lg shadow-rose-200 active:scale-95 transition hover:bg-rose-600"
              >
                確認移除
              </button>
          </div>
        </div>
      </Modal>

      <Modal 
        isOpen={!!alertConfig} 
        onClose={() => setAlertConfig(null)} 
        title={alertConfig?.title || '提示'}
      >
         <div className="p-4">
           <div className="flex flex-col items-center text-center gap-3">
              <div className="w-12 h-12 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center">
                  <AlertTriangle className="w-6 h-6" />
              </div>
              <p className="text-slate-700 font-medium whitespace-pre-wrap">{alertConfig?.msg}</p>
           </div>

           {alertConfig?.action ? (
             <div className="flex gap-3 mt-6">
                <button 
                  onClick={() => setAlertConfig(null)} 
                  className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold active:scale-95 transition hover:bg-slate-200"
                >
                  取消
                </button>
                <button 
                  onClick={() => {
                    alertConfig.action?.();
                    setAlertConfig(null);
                  }}
                  className="flex-1 py-3 bg-violet-600 text-white rounded-xl font-bold shadow-lg shadow-violet-200 active:scale-95 transition hover:bg-violet-700"
                >
                  {alertConfig.actionLabel || '確定'}
                </button>
             </div>
           ) : (
             <button 
               onClick={() => setAlertConfig(null)} 
               className="w-full mt-6 py-3 bg-slate-800 text-white rounded-xl font-bold active:scale-95 transition hover:bg-slate-900"
             >
               我知道了
             </button>
           )}
         </div>
      </Modal>

      {toast && (
        <div className={`
          fixed bottom-6 left-1/2 transform -translate-x-1/2 px-4 py-2.5 rounded-full text-xs font-bold shadow-xl shadow-slate-300/50
          transition-all duration-300 flex items-center gap-2 pointer-events-none z-[110]
          animate-pop-in border border-white/20 backdrop-blur-md
          ${toast.type === 'error' ? 'bg-rose-500 text-white' : 'bg-slate-800 text-white'}
        `}>
          {toast.type === 'success' ? <CheckCircle className="w-4 h-4 text-emerald-400" /> : <AlertTriangle className="w-4 h-4 text-white" />}
          {toast.msg}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Copy, Download, AlertCircle, Cloud, CloudUpload, CloudDownload, Link, Loader2, CheckCircle2 } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group } from '../types';
import { sanitizeDate } from '../utils';

interface DataModalProps {
  isOpen: boolean;
  onClose: () => void;
  data: Group[];
  onImport: (data: Group[]) => void;
  onReset: () => void;
}

export const DataModal: React.FC<DataModalProps> = ({ isOpen, onClose, data, onImport, onReset }) => {
  const [activeTab, setActiveTab] = useState<'export' | 'import' | 'cloud'>('export');
  const [importStr, setImportStr] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [gasUrl, setGasUrl] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const exportStr = JSON.stringify(data);

  // 讀取存儲的 GAS URL
  useEffect(() => {
    const savedUrl = localStorage.getItem('stan-binder-gas-url');
    if (savedUrl) setGasUrl(savedUrl);
  }, []);

  const handleCopy = () => {
    navigator.clipboard.writeText(exportStr).then(() => {
        alert("已複製到剪貼簿！");
    });
  };

  const handleImport = () => {
    setErrorMsg('');
    try {
      if (!importStr.trim()) throw new Error("內容為空");
      const parsed = JSON.parse(importStr);
      if (!Array.isArray(parsed)) throw new Error("資料格式錯誤 (須為陣列)");
      onImport(parsed as Group[]);
      onClose();
      setImportStr('');
    } catch (e: any) {
      setErrorMsg(e.message || "匯入失敗");
    }
  };

  const handleCloudAction = async (type: 'upload' | 'download') => {
    if (!gasUrl.startsWith('https://script.google.com')) {
      setErrorMsg('無效的 GAS 網址');
      return;
    }

    setErrorMsg('');
    setIsSyncing(true);
    setSyncStatus('idle');
    localStorage.setItem('stan-binder-gas-url', gasUrl);

    try {
      if (type === 'upload') {
        const response = await fetch(gasUrl, {
          method: 'POST',
          mode: 'no-cors', 
          body: JSON.stringify(data),
          headers: { 'Content-Type': 'application/json' }
        });
        setSyncStatus('success');
        setTimeout(() => setSyncStatus('idle'), 3000);
      } else {
        const response = await fetch(gasUrl);
        const cloudData = await response.json();
        if (Array.isArray(cloudData)) {
          // 在匯入前先行清洗日期格式
          const sanitizedCloudData = cloudData.map(g => ({
            ...g,
            stanDate: sanitizeDate(g.stanDate),
            unstanDate: g.unstanDate ? sanitizeDate(g.unstanDate) : undefined,
            timeline: g.timeline ? g.timeline.map((e: any) => ({
              ...e,
              date: sanitizeDate(e.date)
            })) : []
          }));
          onImport(sanitizedCloudData);
          setSyncStatus('success');
          setTimeout(() => setSyncStatus('idle'), 3000);
        } else {
          throw new Error('雲端資料格式不正確');
        }
      }
    } catch (e: any) {
      setErrorMsg(e.message || "同步失敗，請檢查網址與權限");
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="資料管理">
      <div className="flex border-b border-slate-100">
        {[
          { id: 'export', label: '匯出', icon: Copy },
          { id: 'import', label: '匯入', icon: Download },
          { id: 'cloud', label: '雲端同步', icon: Cloud }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)} 
            className={`flex-1 py-4 font-bold text-xs flex flex-col items-center gap-1 transition ${activeTab === tab.id ? 'text-violet-600 border-b-2 border-violet-600' : 'text-slate-400 hover:text-slate-600'}`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="p-5 flex-1 overflow-y-auto bg-slate-50 min-h-[350px]">
        {activeTab === 'export' && (
          <div className="space-y-4 animate-pop-in">
            <p className="text-sm text-slate-600">複製代碼以進行手動備份：</p>
            <div className="relative">
              <textarea 
                readOnly 
                className="w-full h-48 p-3 text-xs font-mono bg-white border border-slate-200 rounded-xl focus:outline-none resize-none text-slate-500 break-all shadow-inner" 
                value={exportStr}
              />
              <button 
                onClick={handleCopy} 
                className="absolute bottom-3 right-3 bg-slate-800 text-white text-xs px-4 py-2 rounded-xl flex items-center gap-2 active:scale-95 transition hover:bg-slate-900 shadow-lg"
              >
                <Copy className="w-3.5 h-3.5" /> 一鍵複製
              </button>
            </div>
            <div className="text-center">
              <button onClick={onReset} className="text-[10px] font-black text-rose-400 uppercase tracking-widest hover:text-rose-600 transition">危險區域：重置所有資料</button>
            </div>
          </div>
        )}

        {activeTab === 'import' && (
          <div className="space-y-4 animate-pop-in">
            <p className="text-sm text-slate-600">貼上先前備份的 JSON 代碼：</p>
            <textarea 
              value={importStr}
              onChange={(e) => setImportStr(e.target.value)}
              className="w-full h-48 p-3 text-xs font-mono bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-violet-500 outline-none resize-none placeholder-slate-300 shadow-inner" 
              placeholder='[{"id":"...", "name":"..."}]'
            />
            {errorMsg && <p className="text-xs text-rose-500 flex items-center gap-1 font-bold animate-shake"><AlertCircle className="w-3 h-3" /> {errorMsg}</p>}
            <button 
              onClick={handleImport} 
              className="w-full bg-violet-600 text-white py-4 rounded-xl font-bold active:scale-95 transition flex items-center justify-center gap-2 shadow-xl shadow-violet-200"
            >
              <Download className="w-5 h-5" /> 覆蓋並匯入資料
            </button>
          </div>
        )}

        {activeTab === 'cloud' && (
          <div className="space-y-5 animate-pop-in">
            <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm space-y-3">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                <Link className="w-3.5 h-3.5" /> GAS API URL
              </label>
              <input 
                type="text" 
                value={gasUrl}
                onChange={(e) => setGasUrl(e.target.value)}
                placeholder="貼上您的 Google Apps Script 部署網址"
                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-mono focus:border-violet-400 focus:ring-4 focus:ring-violet-100 outline-none transition-all"
              />
              <p className="text-[10px] text-slate-400 leading-relaxed">
                * 請將 Google Sheets 的 Apps Script 部署為「網頁應用程式」，並設定存取權限為「所有人」。
              </p>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => handleCloudAction('upload')}
                disabled={isSyncing || !gasUrl}
                className="flex flex-col items-center justify-center gap-2 p-4 bg-white border border-slate-200 rounded-2xl hover:border-violet-300 hover:bg-violet-50 transition active:scale-95 disabled:opacity-50"
              >
                <CloudUpload className={`w-8 h-8 ${isSyncing ? 'text-slate-300' : 'text-violet-500'}`} />
                <span className="text-xs font-bold text-slate-600">備份到雲端</span>
              </button>
              <button 
                onClick={() => handleCloudAction('download')}
                disabled={isSyncing || !gasUrl}
                className="flex flex-col items-center justify-center gap-2 p-4 bg-white border border-slate-200 rounded-2xl hover:border-violet-300 hover:bg-violet-50 transition active:scale-95 disabled:opacity-50"
              >
                <CloudDownload className={`w-8 h-8 ${isSyncing ? 'text-slate-300' : 'text-emerald-500'}`} />
                <span className="text-xs font-bold text-slate-600">從雲端還原</span>
              </button>
            </div>

            {isSyncing && (
              <div className="flex items-center justify-center gap-2 text-violet-500 animate-pulse">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span className="text-xs font-bold">雲端同步中...</span>
              </div>
            )}

            {syncStatus === 'success' && (
              <div className="flex items-center justify-center gap-2 text-emerald-500 bg-emerald-50 py-2 rounded-xl border border-emerald-100 animate-pop-in">
                <CheckCircle2 className="w-4 h-4" />
                <span className="text-xs font-bold">同步成功！</span>
              </div>
            )}

            {errorMsg && (
              <div className="p-3 bg-rose-50 border border-rose-100 rounded-xl flex items-start gap-2 text-rose-600 animate-shake">
                <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
                <span className="text-[11px] font-bold leading-tight">{errorMsg}</span>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="p-3 border-t border-slate-100 bg-white rounded-b-2xl">
        <button onClick={onClose} className="w-full py-2 text-slate-400 text-sm font-bold hover:text-slate-600">關閉視窗</button>
      </div>
    </Modal>
  );
};

import React, { useState } from 'react';
import { Copy, Download, AlertCircle, Cloud, CloudUpload, CloudDownload, Link, Loader2, CheckCircle2, ShieldCheck } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group } from '../types';
import { sanitizeDate } from '../utils';

// 硬編碼您的專屬 GAS URL
const FIXED_GAS_URL = 'https://script.google.com/macros/s/AKfycbzXf-TAPJ9u_jyDbTAkZXQC-rA5riv0JLVzC5aYpBPkEm4oHEmA0z3JxwRJ8JOkYDZXKw/exec';

interface DataModalProps {
  isOpen: boolean;
  onClose: () => void;
  data: Group[];
  onImport: (data: Group[]) => void;
  onReset: () => void;
}

export const DataModal: React.FC<DataModalProps> = ({ isOpen, onClose, data, onImport, onReset }) => {
  const [activeTab, setActiveTab] = useState<'export' | 'import' | 'cloud'>('cloud'); // 預設打開雲端分頁
  const [importStr, setImportStr] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const exportStr = JSON.stringify(data);

  const handleCopy = () => {
    navigator.clipboard.writeText(exportStr).then(() => {
        alert("已複製到剪貼簿！");
    });
  };

  const handleImport = () => {
    setErrorMsg('');
    try {
      if (!importStr.trim()) throw new Error("內容為空");
      const parsed = JSON.parse(importStr);
      if (!Array.isArray(parsed)) throw new Error("資料格式錯誤 (須為陣列)");
      onImport(parsed as Group[]);
      onClose();
      setImportStr('');
    } catch (e: any) {
      setErrorMsg(e.message || "匯入失敗");
    }
  };

  const handleCloudAction = async (type: 'upload' | 'download') => {
    setErrorMsg('');
    setIsSyncing(true);
    setSyncStatus('idle');

    try {
      if (type === 'upload') {
        await fetch(FIXED_GAS_URL, {
          method: 'POST',
          mode: 'no-cors', 
          body: JSON.stringify(data),
          headers: { 'Content-Type': 'application/json' }
        });
        setSyncStatus('success');
        setTimeout(() => setSyncStatus('idle'), 3000);
      } else {
        const response = await fetch(FIXED_GAS_URL);
        const cloudData = await response.json();
        if (Array.isArray(cloudData)) {
          // 強制清洗所有日期格式，修復 T16:00 導致的節點遺失問題
          const sanitizedCloudData = cloudData.map(g => ({
            ...g,
            stanDate: sanitizeDate(g.stanDate),
            unstanDate: g.unstanDate ? sanitizeDate(g.unstanDate) : undefined,
            timeline: g.timeline ? g.timeline.map((e: any) => ({
              ...e,
              date: sanitizeDate(e.date)
            })) : []
          }));
          onImport(sanitizedCloudData);
          setSyncStatus('success');
          setTimeout(() => setSyncStatus('idle'), 3000);
        } else {
          throw new Error('雲端資料格式不正確');
        }
      }
    } catch (e: any) {
      setErrorMsg(e.message || "同步失敗，請確認 GAS 腳本部署權限為「所有人」");
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="資料管理">
      <div className="flex border-b border-slate-100">
        {[
          { id: 'cloud', label: '雲端資料庫', icon: Cloud },
          { id: 'export', label: '代碼匯出', icon: Copy },
          { id: 'import', label: '代碼匯入', icon: Download }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)} 
            className={`flex-1 py-4 font-bold text-xs flex flex-col items-center gap-1 transition ${activeTab === tab.id ? 'text-violet-600 border-b-2 border-violet-600 bg-violet-50/30' : 'text-slate-400 hover:text-slate-600'}`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="p-5 flex-1 overflow-y-auto bg-slate-50 min-h-[350px]">
        {activeTab === 'cloud' && (
          <div className="space-y-6 animate-pop-in">
            <div className="bg-emerald-50 p-4 rounded-2xl border border-emerald-100 flex items-center gap-3">
               <div className="w-10 h-10 bg-white rounded-full flex items-center justify-center text-emerald-500 shadow-sm shrink-0">
                  <ShieldCheck className="w-6 h-6" />
               </div>
               <div>
                  <h4 className="text-sm font-black text-emerald-800">專屬資料庫已連線</h4>
                  <p className="text-[10px] text-emerald-600 font-medium leading-tight">您的追星資料已與 Google Sheets 同步鎖定</p>
               </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <button 
                onClick={() => handleCloudAction('upload')}
                disabled={isSyncing}
                className="flex flex-col items-center justify-center gap-3 p-6 bg-white border border-slate-200 rounded-3xl hover:border-violet-300 hover:shadow-xl hover:shadow-violet-100 transition-all active:scale-95 disabled:opacity-50"
              >
                <CloudUpload className={`w-10 h-10 ${isSyncing ? 'text-slate-300' : 'text-violet-500'}`} />
                <span className="text-xs font-black text-slate-700">上傳備份</span>
              </button>
              <button 
                onClick={() => handleCloudAction('download')}
                disabled={isSyncing}
                className="flex flex-col items-center justify-center gap-3 p-6 bg-white border border-slate-200 rounded-3xl hover:border-emerald-300 hover:shadow-xl hover:shadow-emerald-100 transition-all active:scale-95 disabled:opacity-50"
              >
                <CloudDownload className={`w-10 h-10 ${isSyncing ? 'text-slate-300' : 'text-emerald-500'}`} />
                <span className="text-xs font-black text-slate-700">下載還原</span>
              </button>
            </div>

            <div className="bg-slate-100/50 p-3 rounded-xl border border-dashed border-slate-200">
               <div className="flex items-center gap-2 mb-1.5 opacity-50">
                  <Link className="w-3 h-3 text-slate-400" />
                  <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">Database End-point</span>
               </div>
               <div className="text-[10px] font-mono text-slate-400 break-all leading-tight">
                  {FIXED_GAS_URL}
               </div>
            </div>

            {isSyncing && (
              <div className="flex flex-col items-center justify-center gap-2 text-violet-500 animate-pulse py-2">
                <Loader2 className="w-5 h-5 animate-spin" />
                <span className="text-xs font-black tracking-widest">SYNCING DATA...</span>
              </div>
            )}

            {syncStatus === 'success' && (
              <div className="flex items-center justify-center gap-2 text-emerald-600 bg-emerald-100/50 py-3 rounded-2xl border border-emerald-200 animate-pop-in">
                <CheckCircle2 className="w-5 h-5" />
                <span className="text-xs font-black">同步成功！資料已安全存檔</span>
              </div>
            )}

            {errorMsg && (
              <div className="p-4 bg-rose-50 border border-rose-100 rounded-2xl flex items-start gap-3 text-rose-600 animate-shake shadow-sm">
                <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
                <div>
                   <span className="text-xs font-black block mb-1">連線發生錯誤</span>
                   <span className="text-[10px] font-medium leading-tight opacity-80">{errorMsg}</span>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'export' && (
          <div className="space-y-4 animate-pop-in">
            <p className="text-xs font-bold text-slate-500">若需更換裝置，也可手動複製 JSON 代碼：</p>
            <div className="relative">
              <textarea 
                readOnly 
                className="w-full h-48 p-4 text-[10px] font-mono bg-white border border-slate-200 rounded-2xl focus:outline-none resize-none text-slate-500 break-all shadow-inner leading-relaxed" 
                value={exportStr}
              />
              <button 
                onClick={handleCopy} 
                className="absolute bottom-4 right-4 bg-slate-800 text-white text-[10px] px-4 py-2.5 rounded-xl font-black flex items-center gap-2 active:scale-95 transition hover:bg-slate-900 shadow-lg"
              >
                <Copy className="w-3 h-3" /> 一鍵複製
              </button>
            </div>
            <div className="text-center pt-4">
              <button onClick={onReset} className="text-[9px] font-black text-rose-300 uppercase tracking-[0.2em] hover:text-rose-600 transition">Factory Reset</button>
            </div>
          </div>
        )}

        {activeTab === 'import' && (
          <div className="space-y-4 animate-pop-in">
            <p className="text-xs font-bold text-slate-500">貼上代碼（這會取代當前所有內容）：</p>
            <textarea 
              value={importStr}
              onChange={(e) => setImportStr(e.target.value)}
              className="w-full h-48 p-4 text-[10px] font-mono bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-violet-500 outline-none resize-none placeholder-slate-300 shadow-inner" 
              placeholder='[{"id":"...", "name":"..."}]'
            />
            {errorMsg && <p className="text-[10px] text-rose-500 flex items-center gap-1 font-bold animate-shake"><AlertCircle className="w-3 h-3" /> {errorMsg}</p>}
            <button 
              onClick={handleImport} 
              className="w-full bg-violet-600 text-white py-4 rounded-2xl font-black active:scale-95 transition flex items-center justify-center gap-2 shadow-xl shadow-violet-200"
            >
              <Download className="w-5 h-5" /> 覆蓋並匯入
            </button>
          </div>
        )}
      </div>

      <div className="p-4 border-t border-slate-100 bg-white rounded-b-2xl">
        <button onClick={onClose} className="w-full py-2 text-slate-400 text-xs font-black hover:text-slate-600 tracking-widest uppercase">Close</button>
      </div>
    </Modal>
  );
};

import React, { useMemo } from 'react';
import { Trophy, Users, Calendar, Heart, Activity, TrendingUp, Hourglass } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group } from '../types';

interface DashboardModalProps {
  isOpen: boolean;
  onClose: () => void;
  groups: Group[];
}

export const DashboardModal: React.FC<DashboardModalProps> = ({ isOpen, onClose, groups }) => {

  const stats = useMemo(() => {
    const now = new Date();
    const todayTimestamp = now.getTime();
    let earliestDate: Date | null = null;
    let activeCount = 0;
    let fadedCount = 0;
    let unstanCount = 0;

    let biasCount = 0; // Rank 1
    let ultCount = 0;  // Rank 2
    let totalMembers = 0;

    const yearlyIntake: Record<number, { count: number; names: string[] }> = {};

    groups.forEach(g => {
        // 1. Member Stats
        totalMembers += g.members.length;
        g.members.forEach(m => {
            if (m.rank === 1) biasCount++;
            if (m.rank === 2) ultCount++;
        });

        // 2. Status Determination & Timeline Logic
        const sortedTimeline = [...(g.timeline || [])].sort((a, b) => a.date.localeCompare(b.date));

        let isCurrentlyUnstanned = !!g.unstanDate;
        let isCurrentlyFaded = false;
        let effectiveStartDateStr = g.stanDate;

        if (sortedTimeline.length > 0) {
            const latest = sortedTimeline[sortedTimeline.length - 1];
            if (latest.type === 'unstan') { isCurrentlyUnstanned = true; isCurrentlyFaded = false; }
            else if (latest.type === 'fade') { isCurrentlyFaded = true; isCurrentlyUnstanned = false; }
            else { isCurrentlyUnstanned = false; isCurrentlyFaded = false; }

            const firstStan = sortedTimeline.find(t => t.type === 'stan');
            if (firstStan) effectiveStartDateStr = firstStan.date;
        }

        if (isCurrentlyUnstanned) unstanCount++;
        else if (isCurrentlyFaded) fadedCount++;
        else activeCount++;

        // 3. Yearly Intake
        if (effectiveStartDateStr && effectiveStartDateStr.length >= 4) {
            const year = parseInt(effectiveStartDateStr.substring(0, 4));
            if (!isNaN(year)) {
                if (!yearlyIntake[year]) yearlyIntake[year] = { count: 0, names: [] };
                yearlyIntake[year].count += 1;
                yearlyIntake[year].names.push(g.name);

                const d = new Date(effectiveStartDateStr);
                if (!isNaN(d.getTime())) {
                    if (!earliestDate || d < earliestDate) earliestDate = d;
                }
            }
        }
    });

    // Overall Fan Age (Time from first stan to now)
    let fanAge = "0 天";
    if (earliestDate) {
        const diff = Math.abs(todayTimestamp - (earliestDate as Date).getTime());
        const days = Math.ceil(diff / (1000 * 60 * 60 * 24));
        fanAge = days > 365 ? `${(days / 365).toFixed(1)} 年` : `${days} 天`;
    }

    const years = Object.keys(yearlyIntake).map(Number).sort((a, b) => a - b);
    const maxIntake = Math.max(...Object.values(yearlyIntake).map(v => v.count), 1);

    const chartData = [];
    if (years.length > 0) {
        const startY = years[0];
        const endY = Math.min(years[years.length - 1], now.getFullYear() + 1);
        for (let y = startY; y <= endY; y++) {
            chartData.push({ 
                year: y, 
                count: yearlyIntake[y]?.count || 0,
                names: yearlyIntake[y]?.names || []
            });
        }
    }

    return {
        activeCount, fadedCount, unstanCount,
        biasCount, ultCount, totalMembers,
        fanAge, chartData, maxIntake
    };
  }, [groups]);

  const totalGroups = groups.length || 1;
  const activeDeg = (stats.activeCount / totalGroups) * 360;
  const fadeDeg = (stats.fadedCount / totalGroups) * 360;

  const pieStyle = {
      background: `conic-gradient(
        #8b5cf6 0deg ${activeDeg}deg,
        #94a3b8 ${activeDeg}deg ${activeDeg + fadeDeg}deg,
        #e2e8f0 ${activeDeg + fadeDeg}deg 360deg
      )`
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="追星數據儀表板">
      <div className="p-5 overflow-y-auto flex-1 bg-slate-50 space-y-5 no-scrollbar">

        <div className="grid grid-cols-3 gap-3">
            <div className="bg-white p-3 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center justify-center gap-1">
                <div className="p-2 bg-violet-100 text-violet-600 rounded-full mb-1">
                    <Hourglass className="w-4 h-4" />
                </div>
                <span className="text-xl font-black text-slate-800">{stats.fanAge}</span>
                <span className="text-[10px] text-slate-400 font-bold">追星資歷</span>
            </div>
            <div className="bg-white p-3 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center justify-center gap-1">
                <div className="p-2 bg-emerald-100 text-emerald-600 rounded-full mb-1">
                    <Activity className="w-4 h-4" />
                </div>
                <span className="text-xl font-black text-slate-800">{stats.activeCount}</span>
                <span className="text-[10px] text-slate-400 font-bold">現役團體</span>
            </div>
             <div className="bg-white p-3 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center justify-center gap-1">
                <div className="p-2 bg-rose-100 text-rose-600 rounded-full mb-1">
                    <Heart className="w-4 h-4" />
                </div>
                <span className="text-xl font-black text-slate-800">{stats.biasCount + stats.ultCount}</span>
                <span className="text-[10px] text-slate-400 font-bold">本命總數</span>
            </div>
        </div>

        <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
            <div className="flex items-center gap-2 mb-4">
                <TrendingUp className="w-4 h-4 text-slate-400" />
                <h3 className="text-sm font-bold text-slate-600">入坑年份趨勢</h3>
            </div>

            {stats.chartData.length > 0 ? (
                <div className="flex items-end gap-2 h-40 pt-6 pb-2 px-2">
                    {stats.chartData.map((d) => (
                        <div key={d.year} className="flex-1 flex flex-col items-center gap-1 group relative h-full justify-end">
                             <div className="absolute -top-10 left-1/2 -translate-x-1/2 bg-slate-800 text-white text-[9px] px-2 py-1.5 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-10 pointer-events-none shadow-xl border border-white/10">
                                <div className="font-black border-b border-white/10 pb-0.5 mb-0.5">{d.year}年 ({d.count}團)</div>
                                <div className="opacity-80 leading-tight">
                                  {d.names.length > 0 ? d.names.join(', ') : '無'}
                                </div>
                                <div className="absolute top-full left-1/2 -translate-x-1/2 border-4 border-transparent border-t-slate-800"></div>
                             </div>

                             <div className="w-full flex-1 flex items-end justify-center">
                                 <div 
                                    className={`w-full max-w-[20px] rounded-t-sm transition-all relative ${d.count > 0 ? 'bg-violet-400 group-hover:bg-violet-600 shadow-[0_-4px_10px_rgba(139,92,246,0.1)]' : 'bg-slate-100'}`}
                                    style={{ height: d.count > 0 ? `${(d.count / stats.maxIntake) * 100}%` : '4px' }}
                                 >
                                 </div>
                             </div>
                             <span className="text-[10px] text-slate-400 font-medium font-mono">
                                {d.year.toString().slice(2)}
                             </span>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="h-32 flex flex-col items-center justify-center text-slate-400 text-xs border border-dashed border-slate-100 rounded-xl bg-slate-50/50">
                    <Calendar className="w-8 h-8 mb-2 opacity-50" />
                    <p className="font-bold">暫無時間資料</p>
                </div>
            )}
        </div>

        <div className="grid grid-cols-2 gap-3">
            <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center">
                 <h3 className="text-xs font-bold text-slate-500 mb-3 w-full text-left">狀態分佈</h3>
                 <div className="relative w-24 h-24 rounded-full mb-4 shadow-inner" style={pieStyle}>
                    <div className="absolute inset-4 bg-white rounded-full flex items-center justify-center">
                        <span className="text-xs font-bold text-slate-400">{groups.length} 團</span>
                    </div>
                 </div>
                 <div className="w-full space-y-1.5 px-1">
                    <div className="flex items-center justify-between text-[10px]">
                        <div className="flex items-center gap-1.5">
                            <div className="w-2 h-2 rounded-full bg-violet-500"></div>
                            <span className="text-slate-600 font-medium">坑底/回坑</span>
                        </div>
                        <span className="font-bold text-violet-600">{Math.round((stats.activeCount/totalGroups)*100)}%</span>
                    </div>
                    <div className="flex items-center justify-between text-[10px]">
                        <div className="flex items-center gap-1.5">
                            <div className="w-2 h-2 rounded-full bg-slate-400"></div>
                            <span className="text-slate-600 font-medium">淡坑</span>
                        </div>
                        <span className="font-bold text-slate-500">{Math.round((stats.fadedCount/totalGroups)*100)}%</span>
                    </div>
                    <div className="flex items-center justify-between text-[10px]">
                        <div className="flex items-center gap-1.5">
                            <div className="w-2 h-2 rounded-full bg-slate-200"></div>
                            <span className="text-slate-600 font-medium">退坑</span>
                        </div>
                        <span className="font-bold text-slate-400">{Math.round((stats.unstanCount/totalGroups)*100)}%</span>
                    </div>
                 </div>
            </div>

            <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col">
                 <h3 className="text-xs font-bold text-slate-500 mb-3 text-left">本命金字塔</h3>
                 <div className="flex-1 flex flex-col justify-center items-center gap-1">
                    <div className="w-1/3 bg-amber-100 border border-amber-200 text-amber-600 rounded-lg py-1.5 text-center shadow-sm relative group">
                        <Trophy className="w-3 h-3 absolute -left-1 top-1/2 -translate-y-1/2 -ml-3 text-amber-400" />
                        <span className="text-xs font-bold">{stats.ultCount}</span>
                    </div>
                    <div className="w-2/3 bg-rose-100 border border-rose-200 text-rose-600 rounded-lg py-1.5 text-center shadow-sm relative">
                        <Heart className="w-3 h-3 absolute -left-1 top-1/2 -translate-y-1/2 -ml-3 text-rose-400" />
                        <span className="text-xs font-bold">{stats.biasCount}</span>
                    </div>
                    <div className="w-full bg-slate-100 border border-slate-200 text-slate-500 rounded-lg py-1.5 text-center shadow-sm relative">
                        <Users className="w-3 h-3 absolute -left-1 top-1/2 -translate-y-1/2 -ml-3 text-slate-400" />
                        <span className="text-xs font-bold">{stats.totalMembers}</span>
                    </div>
                 </div>
                 <p className="text-[10px] text-center text-slate-400 mt-2">總計人數</p>
            </div>
        </div>

      </div>
      <div className="p-3 border-t border-slate-100 bg-white rounded-b-2xl">
        <button onClick={onClose} className="w-full py-2 text-slate-400 text-sm hover:text-slate-600">關閉</button>
      </div>
    </Modal>
  );
};

/**
 * 將圖片檔案壓縮並轉換為 Base64 字串
 */
export const compressImage = (
  file: File, 
  maxWidth: number = 300, 
  quality: number = 0.8
): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;

        if (width > maxWidth) {
          height *= maxWidth / width;
          width = maxWidth;
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', quality));
        } else {
          reject(new Error("Canvas context not available"));
        }
      };
      img.onerror = (err) => reject(err);
      img.src = event.target?.result as string;
    };
    reader.onerror = (err) => reject(err);
    reader.readAsDataURL(file);
  });
};

/**
 * 正規化字串：轉小寫並移除非英數字符
 */
export const normalizeString = (s: string): string => {
  return s.toLowerCase().replace(/[^a-z0-9]/g, '');
};

/**
 * 驗證兩個字串是否具有相關性（用於防止錯誤的搜尋結果）
 * 針對維基百科標題進行優化，忽略常見的後綴
 */
export const isFuzzyMatch = (query: string, resultTitle: string): boolean => {
  const nQuery = normalizeString(query);
  const nTitle = normalizeString(resultTitle)
    .replace(/southkorean/g, '')
    .replace(/band/g, '')
    .replace(/group/g, '')
    .replace(/kpop/g, '');

  return nTitle.includes(nQuery) || nQuery.includes(nTitle);
};

/**
 * 強化版清洗日期格式
 * 處理 ISO, YYYY/MM, YYYY-M 等 Google Sheets 常見變形
 */
export const sanitizeDate = (dateVal: any): string => {
  if (!dateVal) return '';
  const s = String(dateVal).trim();

  // 1. 標準 YYYY-MM
  const matchStandard = s.match(/^(\d{4})-(\d{2})/);
  if (matchStandard) return `${matchStandard[1]}-${matchStandard[2]}`;

  // 2. 處理 YYYY/MM/DD 變形
  const matchSlash = s.match(/^(\d{4})\/(\d{1,2})/);
  if (matchSlash) {
    return `${matchSlash[1]}-${matchSlash[2].padStart(2, '0')}`;
  }

  // 3. 嘗試使用原生的 Date 進行解析 (處理 ISO 8601)
  const d = new Date(s);
  if (!isNaN(d.getTime())) {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    // 檢查解析結果是否合理 (年份需 > 1900)
    if (y > 1900) return `${y}-${m}`;
  }

  // 4. 如果以上都失敗，但字串長度大於 7，嘗試擷取前 7 碼 (YYYY-MM)
  if (s.length >= 7 && /^\d{4}.\d{2}/.test(s)) {
    return s.substring(0, 7).replace(/[./]/g, '-');
  }

  // 最後防線：回傳原始值，不要抹除它
  return s;
};

import React, { useState } from 'react';
import { Copy, Download, AlertCircle, Cloud, CloudUpload, CloudDownload, Link, Loader2, CheckCircle2, ShieldCheck, AlertTriangle } from 'lucide-react';
import { Modal } from './ui/Modal';
import { Group } from '../types';
import { sanitizeDate } from '../utils';

// 硬編碼您的專屬 GAS URL
const FIXED_GAS_URL = 'https://script.google.com/macros/s/AKfycbzXf-TAPJ9u_jyDbTAkZXQC-rA5riv0JLVzC5aYpBPkEm4oHEmA0z3JxwRJ8JOkYDZXKw/exec';

interface DataModalProps {
  isOpen: boolean;
  onClose: () => void;
  data: Group[];
  onImport: (data: Group[]) => void;
  onReset: () => void;
}

export const DataModal: React.FC<DataModalProps> = ({ isOpen, onClose, data, onImport, onReset }) => {
  const [activeTab, setActiveTab] = useState<'export' | 'import' | 'cloud'>('cloud');
  const [importStr, setImportStr] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const exportStr = JSON.stringify(data);
  const isDataHeavy = exportStr.length > 45000; // 接近 50k 字元限制

  const handleCopy = () => {
    navigator.clipboard.writeText(exportStr).then(() => {
        alert("已複製到剪貼簿！");
    });
  };

  const handleImport = () => {
    setErrorMsg('');
    try {
      if (!importStr.trim()) throw new Error("內容為空");
      const parsed = JSON.parse(importStr);
      if (!Array.isArray(parsed)) throw new Error("資料格式錯誤 (須為陣列)");
      onImport(parsed as Group[]);
      onClose();
      setImportStr('');
    } catch (e: any) {
      setErrorMsg(e.message || "匯入失敗");
    }
  };

  const handleCloudAction = async (type: 'upload' | 'download') => {
    setErrorMsg('');
    setIsSyncing(true);
    setSyncStatus('idle');

    try {
      if (type === 'upload') {
        // 檢查是否超出 Google Sheets 限制
        if (exportStr.length > 50000) {
          if (!window.confirm("警告：資料大小已超過 50,000 字元，備份到 Google Sheets 可能會被截斷導致資料毀損。是否仍要嘗試？")) {
            setIsSyncing(false);
            return;
          }
        }

        await fetch(FIXED_GAS_URL, {
          method: 'POST',
          mode: 'no-cors', 
          body: exportStr,
          headers: { 'Content-Type': 'application/json' }
        });
        setSyncStatus('success');
        setTimeout(() => setSyncStatus('idle'), 3000);
      } else {
        const response = await fetch(FIXED_GAS_URL);
        const rawText = await response.text();

        // 檢查 JSON 是否完整
        let cloudData;
        try {
          cloudData = JSON.parse(rawText);
        } catch (e) {
          console.error("JSON Parse Error:", rawText);
          throw new Error('雲端資料不完整或已毀損（可能超過試算表 50,000 字元限制）。請檢查您的 Google Sheet A1 儲存格內容是否被切斷。');
        }

        if (Array.isArray(cloudData)) {
          const sanitizedCloudData = cloudData.map(g => ({
            ...g,
            stanDate: sanitizeDate(g.stanDate),
            unstanDate: g.unstanDate ? sanitizeDate(g.unstanDate) : undefined,
            timeline: g.timeline ? g.timeline.map((e: any) => ({
              ...e,
              date: sanitizeDate(e.date)
            })) : []
          }));
          onImport(sanitizedCloudData);
          setSyncStatus('success');
          setTimeout(() => setSyncStatus('idle'), 3000);
        } else {
          throw new Error('雲端資料格式不正確');
        }
      }
    } catch (e: any) {
      setErrorMsg(e.message || "同步失敗");
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="資料管理">
      <div className="flex border-b border-slate-100">
        {[
          { id: 'cloud', label: '雲端資料庫', icon: Cloud },
          { id: 'export', label: '代碼匯出', icon: Copy },
          { id: 'import', label: '代碼匯入', icon: Download }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)} 
            className={`flex-1 py-4 font-bold text-xs flex flex-col items-center gap-1 transition ${activeTab === tab.id ? 'text-violet-600 border-b-2 border-violet-600 bg-violet-50/30' : 'text-slate-400 hover:text-slate-600'}`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="p-5 flex-1 overflow-y-auto bg-slate-50 min-h-[350px]">
        {activeTab === 'cloud' && (
          <div className="space-y-6 animate-pop-in">
            <div className="bg-emerald-50 p-4 rounded-2xl border border-emerald-100 flex items-center gap-3">
               <div className="w-10 h-10 bg-white rounded-full flex items-center justify-center text-emerald-500 shadow-sm shrink-0">
                  <ShieldCheck className="w-6 h-6" />
               </div>
               <div>
                  <h4 className="text-sm font-black text-emerald-800">專屬資料庫已連線</h4>
                  <p className="text-[10px] text-emerald-600 font-medium leading-tight">資料將同步至 Google Sheets</p>
               </div>
            </div>

            {isDataHeavy && (
              <div className="p-3 bg-amber-50 border border-amber-200 rounded-xl flex items-start gap-2 text-amber-700 animate-pulse">
                <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
                <p className="text-[10px] font-bold leading-tight">
                  警告：目前資料量較大 ({exportStr.length} 字)，已接近試算表 50,000 字限制。建議減少 Logo 圖片大小以防資料遺失。
                </p>
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              <button 
                onClick={() => handleCloudAction('upload')}
                disabled={isSyncing}
                className="flex flex-col items-center justify-center gap-3 p-6 bg-white border border-slate-200 rounded-3xl hover:border-violet-300 hover:shadow-xl hover:shadow-violet-100 transition-all active:scale-95 disabled:opacity-50"
              >
                <CloudUpload className={`w-10 h-10 ${isSyncing ? 'text-slate-300' : 'text-violet-500'}`} />
                <span className="text-xs font-black text-slate-700">上傳備份</span>
              </button>
              <button 
                onClick={() => handleCloudAction('download')}
                disabled={isSyncing}
                className="flex flex-col items-center justify-center gap-3 p-6 bg-white border border-slate-200 rounded-3xl hover:border-emerald-300 hover:shadow-xl hover:shadow-emerald-100 transition-all active:scale-95 disabled:opacity-50"
              >
                <CloudDownload className={`w-10 h-10 ${isSyncing ? 'text-slate-300' : 'text-emerald-500'}`} />
                <span className="text-xs font-black text-slate-700">下載還原</span>
              </button>
            </div>

            {isSyncing && (
              <div className="flex flex-col items-center justify-center gap-2 text-violet-500 animate-pulse py-2">
                <Loader2 className="w-5 h-5 animate-spin" />
                <span className="text-xs font-black tracking-widest">SYNCING DATA...</span>
              </div>
            )}

            {syncStatus === 'success' && (
              <div className="flex items-center justify-center gap-2 text-emerald-600 bg-emerald-100/50 py-3 rounded-2xl border border-emerald-200 animate-pop-in">
                <CheckCircle2 className="w-5 h-5" />
                <span className="text-xs font-black">同步成功！資料已安全存檔</span>
              </div>
            )}

            {errorMsg && (
              <div className="p-4 bg-rose-50 border border-rose-100 rounded-2xl flex items-start gap-3 text-rose-600 animate-shake shadow-sm">
                <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
                <div>
                   <span className="text-xs font-black block mb-1">同步失敗</span>
                   <span className="text-[10px] font-medium leading-tight opacity-80">{errorMsg}</span>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'export' && (
          <div className="space-y-4 animate-pop-in">
            <p className="text-xs font-bold text-slate-500">若需更換裝置，也可手動複製 JSON 代碼：</p>
            <div className="relative">
              <textarea 
                readOnly 
                className="w-full h-48 p-4 text-[10px] font-mono bg-white border border-slate-200 rounded-2xl focus:outline-none resize-none text-slate-500 break-all shadow-inner leading-relaxed" 
                value={exportStr}
              />
              <button 
                onClick={handleCopy} 
                className="absolute bottom-4 right-4 bg-slate-800 text-white text-[10px] px-4 py-2.5 rounded-xl font-black flex items-center gap-2 active:scale-95 transition hover:bg-slate-900 shadow-lg"
              >
                <Copy className="w-3 h-3" /> 一鍵複製
              </button>
            </div>
          </div>
        )}

        {activeTab === 'import' && (
          <div className="space-y-4 animate-pop-in">
            <p className="text-xs font-bold text-slate-500">貼上代碼（這會取代當前所有內容）：</p>
            <textarea 
              value={importStr}
              onChange={(e) => setImportStr(e.target.value)}
              className="w-full h-48 p-4 text-[10px] font-mono bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-violet-500 outline-none resize-none placeholder-slate-300 shadow-inner" 
              placeholder='[{"id":"...", "name":"..."}]'
            />
            {errorMsg && <p className="text-[10px] text-rose-500 flex items-center gap-1 font-bold animate-shake"><AlertCircle className="w-3 h-3" /> {errorMsg}</p>}
            <button 
              onClick={handleImport} 
              className="w-full bg-violet-600 text-white py-4 rounded-2xl font-black active:scale-95 transition flex items-center justify-center gap-2 shadow-xl shadow-violet-200"
            >
              <Download className="w-5 h-5" /> 覆蓋並匯入
            </button>
          </div>
        )}
      </div>

      <div className="p-4 border-t border-slate-100 bg-white rounded-b-2xl">
        <button onClick={onClose} className="w-full py-2 text-slate-400 text-xs font-black hover:text-slate-600 tracking-widest uppercase">Close</button>
      </div>
    </Modal>
  );
};

import { useState, useEffect, useCallback } from 'react';
import { BookHeart, Database, LayoutGrid, List, Plus, X, Loader2, HelpCircle, Layers, CheckCircle, AlertTriangle, History, BarChart3, Sparkles, Trophy, Heart } from 'lucide-react';
import { Group, Member, GroupDetails, ToastType, TimelineEvent, GroupRatings } from './types';
import { PRESET_DB } from './constants';
import { fetchFromWikiAuto, fetchGroupLogo } from './services/wikiService';
import { GroupCard } from './components/GroupCard';
import { EditGroupModal } from './components/EditGroupModal';
import { GroupDetailsModal } from './components/GroupDetailsModal';
import { DataModal } from './components/DataModal';
import { TimelineModal } from './components/TimelineModal';
import { DashboardModal } from './components/DashboardModal';
import { RatingModal } from './components/RatingModal';
import { BiasListModal } from './components/BiasListModal';
import { Modal } from './components/ui/Modal';
import { normalizeString, sanitizeDate } from './utils';

interface AlertConfig {
  title: string;
  msg: string;
  action?: () => void;
  actionLabel?: string;
}

export default function App() {
  // --- State ---
  const [myGroups, setMyGroups] = useState<Group[]>([]);
  const [inputQuery, setInputQuery] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isInputError, setIsInputError] = useState(false);
  const [viewMode, setViewMode] = useState<'card' | 'list'>('card');

  // Modals
  const [editingGroup, setEditingGroup] = useState<Group | null>(null);
  const [detailsModalGroup, setDetailsModalGroup] = useState<Group | null>(null);
  const [isDataModalOpen, setIsDataModalOpen] = useState(false);
  const [isTimelineOpen, setIsTimelineOpen] = useState(false);
  const [isDashboardOpen, setIsDashboardOpen] = useState(false);
  const [isRatingModalOpen, setIsRatingModalOpen] = useState(false);
  const [isBiasListOpen, setIsBiasListOpen] = useState(false);
  const [deleteConfirmGroup, setDeleteConfirmGroup] = useState<Group | null>(null);
  const [alertConfig, setAlertConfig] = useState<AlertConfig | null>(null);

  // Toast
  const [toast, setToast] = useState<{ msg: string; type: ToastType } | null>(null);

  // Helper to get current YYYY-MM
  const getCurrentMonth = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  };

  // --- Effects ---
  useEffect(() => {
    const saved = localStorage.getItem('stan-binder-v7-react');
    if (saved) {
      try {
        setMyGroups(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load data", e);
      }
    }
  }, []);

  useEffect(() => {
    if (myGroups.length > 0 || localStorage.getItem('stan-binder-v7-react')) {
      localStorage.setItem('stan-binder-v7-react', JSON.stringify(myGroups));
    }
  }, [myGroups]);

  // --- Handlers ---

  const showToast = (msg: string, type: ToastType = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const resetError = () => setIsInputError(false);

  const handleForceAdd = useCallback(() => {
    if (!inputQuery.trim()) return;
    const groupName = inputQuery.trim();
    const now = getCurrentMonth();

    const newGroup: Group = {
      id: Date.now().toString(),
      name: groupName,
      stanDate: now,
      isExpanded: true,
      members: [],
      timeline: [{ date: now, type: 'stan' }]
    };
    setMyGroups(prev => [newGroup, ...prev]);
    setEditingGroup(newGroup);
    setInputQuery('');
    resetError();

    fetchGroupLogo(groupName).then(url => {
      if (url) {
        setMyGroups(prev => prev.map(g => 
          g.id === newGroup.id ? { ...g, logoUrl: url } : g
        ));
      }
    });
  }, [inputQuery]);

  const handleSmartAdd = async () => {
    const rawInput = inputQuery.trim();
    if (!rawInput) return;

    setIsLoading(true);
    resetError();

    const key = normalizeString(rawInput);
    const now = getCurrentMonth();

    let preset = PRESET_DB[key];
    if (preset) {
      if (preset.ref && PRESET_DB[preset.ref]) {
        preset = PRESET_DB[preset.ref];
      }

      if (!preset.n) {
         showToast(`${key} 設定錯誤`, 'error');
         setIsLoading(false);
         return;
      }

      if (myGroups.find(g => g.name === preset.n)) {
        showToast(`${preset.n} 已存在`, 'error');
        setIsLoading(false);
        return;
      }

      const newGroup: Group = {
        id: Date.now().toString(),
        name: preset.n,
        stanDate: now,
        isExpanded: true,
        members: preset.m ? preset.m.map(m => ({ name: m[0], cn: m[1] || '', rank: 0 })) : [],
        logoUrl: preset.l,
        timeline: [{ date: now, type: 'stan' }]
      };

      setMyGroups(prev => [newGroup, ...prev]);
      showToast(`已新增 ${newGroup.name}`);
      setInputQuery('');
      setIsLoading(false);

      if (!newGroup.logoUrl) {
        fetchGroupLogo(newGroup.name).then(url => {
          if (url) {
            setMyGroups(prev => prev.map(g => 
              g.id === newGroup.id ? { ...g, logoUrl: url } : g
            ));
          }
        });
      }

      return;
    }

    try {
      const data = await fetchFromWikiAuto(rawInput);
      if (myGroups.find(g => g.name === data.name)) {
        showToast(`${data.name} 已存在`, 'error');
      } else {
        if (data.members.length === 0) {
          setAlertConfig({
            title: "無法抓取成員",
            msg: `找到 "${data.name}" 但無法自動抓取成員名單。\n\n您可以選擇手動新增此團體並自行編輯成員。`,
            action: handleForceAdd,
            actionLabel: "手動新增"
          });
        } else {
          const newGroup: Group = {
            id: Date.now().toString(),
            name: data.name,
            stanDate: now,
            isExpanded: true,
            members: data.members,
            logoUrl: data.logoUrl,
            timeline: [{ date: now, type: 'stan' }]
          };
          setMyGroups(prev => [newGroup, ...prev]);
          showToast(`已新增 ${data.name} 並透過 AI 優化中文名稱`);
          setInputQuery('');
        }
      }
    } catch (e) {
      setIsInputError(true);
      setAlertConfig({
        title: "找不到團體",
        msg: `找不到 "${rawInput}"。\n請確認拼字，或者直接手動建立此團體。`,
        action: handleForceAdd,
        actionLabel: `手動新增 "${rawInput}"`
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggleExpand = useCallback((id: string) => {
    setMyGroups(prev => prev.map(g => g.id === id ? { ...g, isExpanded: !g.isExpanded } : g));
  }, []);

  const handleMove = useCallback((index: number, dir: number) => {
    setMyGroups(prev => {
      const newGroups = [...prev];
      const targetIndex = index + dir;
      if (targetIndex >= 0 && targetIndex < newGroups.length) {
        [newGroups[index], newGroups[targetIndex]] = [newGroups[targetIndex], newGroups[index]];
        return newGroups;
      }
      return prev;
    });
  }, []);

  const handleToggleRank = useCallback((groupId: string, member: Member) => {
    setMyGroups(prev => prev.map(g => {
      if (g.id !== groupId) return g;
      return {
        ...g,
        members: g.members.map(m => 
          m.name === member.name ? { ...m, rank: (m.rank + 1) % 3 } : m
        )
      };
    }));
  }, []);

  const handleRemoveGroupClick = useCallback((group: Group) => {
    setDeleteConfirmGroup(group);
  }, []);

  const handleEditClick = useCallback((group: Group) => {
    setEditingGroup(group);
  }, []);

  const handleDetailsClick = useCallback((group: Group) => {
    setDetailsModalGroup(group);
  }, []);

  const performDeleteGroup = () => {
    if (deleteConfirmGroup) {
      setMyGroups(prev => prev.filter(g => g.id !== deleteConfirmGroup.id));
      showToast("團體已移除");
      setDeleteConfirmGroup(null);
    }
  };

  const handleSaveEdit = (groupId: string, members: Member[], logoUrl: string, timeline: TimelineEvent[]) => {
    setMyGroups(prev => {
        const earliestStan = timeline
            .filter(e => e.type === 'stan')
            .sort((a, b) => a.date.localeCompare(b.date))[0]?.date || '';

        const sortedEvents = [...timeline].sort((a, b) => b.date.localeCompare(a.date));
        const latestEvent = sortedEvents[0];
        const derivedUnstanDate = (latestEvent && latestEvent.type === 'unstan') ? latestEvent.date : undefined;

        const updatedGroups = prev.map(g => g.id === groupId ? { 
            ...g, 
            members, 
            logoUrl, 
            timeline,
            stanDate: earliestStan || g.stanDate,
            unstanDate: derivedUnstanDate
        } : g);

        return updatedGroups.sort((a, b) => {
            const aUnstan = !!a.unstanDate;
            const bUnstan = !!b.unstanDate;
            if (aUnstan === bUnstan) return 0;
            return aUnstan ? 1 : -1;
        });
    });
    showToast("團體已更新");
  };

  const handleSaveDetails = (groupId: string, details: GroupDetails) => {
    setMyGroups(prev => prev.map(g => g.id === groupId ? { ...g, details } : g));
    showToast("詳細筆記已儲存");
  };

  const handleUpdateRatings = (groupId: string, ratings: GroupRatings) => {
    setMyGroups(prev => prev.map(g => g.id === groupId ? { ...g, ratings } : g));
  };

  /**
   * 核心資料匯入邏輯：自動修復與對齊
   */
  const handleImport = (data: Group[]) => {
    // 進行深度資料清洗，這段邏輯模擬了「編輯儲存」的修復行為
    const processedData = data.map(g => {
      // 1. 清洗 timeline 中的所有日期
      const sanitizedTimeline = (g.timeline || []).map(e => ({
        ...e,
        date: sanitizeDate(e.date)
      })).sort((a, b) => a.date.localeCompare(b.date));

      // 2. 重新從 timeline 推算最早入坑日期 (stanDate)
      const earliestFromTimeline = sanitizedTimeline
          .filter(e => e.type === 'stan')
          .sort((a, b) => a.date.localeCompare(b.date))[0]?.date;

      const finalStanDate = earliestFromTimeline || sanitizeDate(g.stanDate);

      // 3. 重新從 timeline 推算退坑日期 (unstanDate)
      const sortedEventsDesc = [...sanitizedTimeline].sort((a, b) => b.date.localeCompare(a.date));
      const latestEvent = sortedEventsDesc[0];
      const derivedUnstanDate = (latestEvent && latestEvent.type === 'unstan') ? latestEvent.date : sanitizeDate(g.unstanDate);

      return {
        ...g,
        stanDate: finalStanDate,
        unstanDate: derivedUnstanDate || undefined,
        timeline: sanitizedTimeline,
        isExpanded: false // 預設全部收起，視覺上更整齊
      };
    }).sort((a, b) => {
        // 4. 重新自動排序：現役在前，退坑在後
        const aUnstan = !!a.unstanDate;
        const bUnstan = !!b.unstanDate;
        if (aUnstan === bUnstan) return 0;
        return aUnstan ? 1 : -1;
    });

    setMyGroups(processedData);
    showToast(`成功匯入並自動優化 ${processedData.length} 個團體`);
  };

  const handleReset = () => {
    if (window.confirm("恢復原廠設定：清除所有資料？")) {
      setMyGroups([]);
      localStorage.removeItem('stan-binder-v7-react');
      showToast("所有資料已清除");
      setIsDataModalOpen(false);
    }
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: 'smooth' });

  return (
    <div className="max-w-md mx-auto bg-slate-50 min-h-screen shadow-2xl relative overflow-hidden flex flex-col">
